INSERT INTO `produk` (`kode_produk`, `admin_id`, `nama`, `image`, `deskripsi`, `detail`, `cara_pembuatan`, `bahan`, `jumlah_benang`, `panjang`, `lebar`, `sejarah`, `kategori`) VALUES
('P0001', NULL, 'Ragidup', 'df.jpg', 'Ragidup adalah salah satu jenis ulos tradisional Batak yang sarat akan makna dan nilai-nilai kehidupan. Dalam bahasa Batak, “ragidup” secara harfiah berarti “pemberi hidup” atau “penghidupan.” Sesuai dengan namanya, ulos ini melambangkan doa dan harapan akan kehidupan yang sejahtera, panjang umur, dan penuh berkat.\r\nDalam kehidupan sehari-hari masyarakat Batak, Ragidup memiliki peran penting, bukan hanya sebagai kain pelengkap pakaian adat, tetapi juga sebagai simbol kasih sayang, penghormatan, dan restu. Ulos Ragidup biasanya digunakan dalam momen-momen penting seperti pernikahan, upacara adat, dan pemberian ulos kepada orang yang dihormati. Misalnya, seorang orang tua bisa memberikan ulos Ragidup kepada anaknya yang baru menikah sebagai lambang restu dan harapan akan kehidupan rumah tangga yang harmonis.\r\n\r\nSelain itu, Ragidup juga dikenakan dalam upacara syukuran, atau ketika seseorang mencapai pencapaian besar dalam hidupnya — seperti kelulusan, kelahiran anak, atau saat seseorang membangun rumah baru. Dalam hal ini, Ragidup menjadi medium penyambung nilai-nilai kekeluargaan dan spiritualitas.\r\n\r\nSecara filosofis, Ragidup menggambarkan kesatuan antara kehidupan fisik dan spiritual. Motif dan warna-warna pada ulos ini biasanya dibuat dengan penuh ketelitian, dan seringkali mengandung simbol yang merepresentasikan keseimbangan hidup, harapan, dan kekuatan. Setiap helai benang seolah merajut kisah tentang perjuangan, cinta, dan kebersamaan.', '', '3. Rumus \r\n   1.	Jumlah benang lungsi = Lebar ulos (cm) × 10\r\n   2.	Susunan motif Ragihotang = 1 putih + 3 merah + 1 putih (3 posisi: tengah & dua sisi)\r\n   3.	Susunan warna benang lungsi:\r\n   4.	Susunan warna benang lungsi:\r\n      •	300 helai hitam\r\n      •	1 putih + 3 merah + 1 putih (motif Ragihotang tengah)\r\n      •	290 helai hitam\r\n      •	1 putih + 3 merah + 1 putih (motif sisi kiri)\r\n      •	300 helai hitam\r\n   5.	Panjang tiap benang = Panjang kain (200 cm) + sisa pemasangan (50 cm) × 2\r\n        Panjang tiap benang = 200 cm + (50 cm × 2) = 300 cm (3 meter).\r\n\r\n4. Panghintaman – Menyusun Benang Lungsi\r\n   1.	Ukur panjang benang lungsi: 4,5 meter per helai (agar cukup untuk panjang kain dan pemasangan).\r\n   2.	 900 helai benang berwarna hitam.\r\n   3.	Di helai ke-300 hingga 310:\r\n      •	1 putih – 3 merah – 1 putih (pola Ragihotang tengah).\r\n   4.	Di helai ke-100–105 dan 795–800:\r\n      •	1 putih – 3 merah – 1 putih (pola Ragihotang sisi).\r\n  5.	Gulung semua benang ke turak (penggulung), dalam urutan tetap dan rapi.\r\n\r\n5.  Mangalehon – Memasang Benang ke Alat Tenun\r\n    1.	Masukkan satu per satu 900 helai benang ke sisorhon (sisir tenun), 10 helai per rongga (90 rongga total).\r\n    2.	Masukkan benang ke torop (alat pembagi jalur atas-bawah) sesuai urutan silang.\r\n    3.	Ikat bagian belakang ke penggulung belakang, bagian depan ke pemberat/penggulung depan.\r\n    4.	Periksa ulang susunan warna agar tiga garis Ragihotang (tengah dan sisi) berada tepat pada posisinya.\r\n\r\n6. Mangtenun – Proses Menenun\r\n   1.	Duduk di alat tenun gedogan, injak pedal kanan dan kiri bergantian untuk membuka lungsi.\r\n   2.	Masukkan benang pakan hitam dari kanan ke kiri (menggunakan sekoci), lalu pukul dengan baliga agar rapat.\r\n   3.	Setiap 50 sisipan benang pakan, selipkan pola warna:\r\n      •	3 kali benang merah\r\n      •	1 kali benang putih\r\n      •	Lakukan ini di tengah dan di dua sisi\r\n      •	Total: 3 bagian motif Ragihotang pada kain\r\n   4.	Lanjutkan menenun hingga mencapai panjang 200 cm kain efektif (total proses ±2–3 hari kerja tergantung kecepatan).\r\n   5.	Pastikan setiap 50 baris motif warna dijahit rapi dan ditekan agar tidak geser.\r\n\r\n7. Pangurung – Menyelesaikan Tenunan\r\n    1.	Setelah panjang 200 cm tercapai, ikat dan potong benang dari alat tenun.\r\n    2.	Buat simpul ujung benang untuk menghindari lepas.\r\n    3.	Rapikan pinggiran menggunakan jarum tangan atau dijahit manual agar tidak terurai.\r\n\r\n8. Pagolong – Finishing\r\n    1.	Jemur kain di tempat teduh selama 6 jam.\r\n    2.	Setrika ulos menggunakan suhu sedang.\r\n    3.	Lipat kain menjadi tiga bagian memanjang, sesuai tradisi penyimpanan ulos Ragihotang.', 'Benang LusiBenang PakanSutra (untuk kualitas tinggi)Benang KapasBenang NilonPewarna Alami atau SintetisKapas atau Serat Alam (untuk bahan dasar benang)Benang Emas atau Perak (untuk aksen atau ornamen khusus)', '2 kg', '250', '71', 'Ulos Ragidup adalah salah satu jenis ulos yang sangat dihormati dalam budaya Batak, khususnya di daerah Sumatera Utara, Indonesia. Nama \"ragidup\" memiliki arti \"bernyawa\" atau \"hidup,\" yang menggambarkan makna simbolis dari ulos ini, yaitu sebagai lambang kehidupan, harapan, dan keselamatan. Ulos ini memiliki kedudukan yang sangat penting dalam berbagai upacara adat Batak, seperti pernikahan, kelahiran, dan acara-upacara lainnya yang melibatkan perjalanan hidup seseorang.\r\n\r\nSejarah asal usul Ulos Ragidup tidak dapat dipisahkan dari tradisi panjang pembuatan ulos dalam masyarakat Batak. Ulos secara umum memiliki peran sentral dalam budaya Batak, dengan berbagai jenis ulos yang masing-masing memiliki makna dan kegunaan tersendiri. Ragidup, sebagai salah satu jenis ulos, dikenal karena fungsinya yang sangat erat dengan doa dan harapan kehidupan yang penuh berkah. Ulos ini biasanya diberikan dalam upacara adat, seperti pada saat pernikahan atau kelahiran, untuk melambangkan kehidupan yang penuh vitalitas dan keberkahan.\r\n\r\nProses pembuatan Ulos Ragidup memerlukan keterampilan tinggi dari pengrajin tenun Batak. Ulos ini dibuat dari benang tenun yang diwarnai dengan warna alami, dan motif-motifnya biasanya mencerminkan simbol kehidupan dan harapan akan panjang umur serta kebahagiaan. Ragidup sering kali memiliki desain yang cerah dan dinamis, yang menggambarkan semangat hidup dan vitalitas.\r\n\r\nSecara keseluruhan, Ulos Ragidup tidak hanya sekadar kain tenun, melainkan juga sebuah simbol yang menghubungkan manusia dengan leluhur dan dunia spiritual dalam kepercayaan masyarakat Batak. Pemberian ulos ini menggambarkan harapan agar kehidupan seseorang atau keluarga yang menerima ulos ini diberkahi dengan kebahagiaan, kesehatan, dan umur panjang. Oleh karena itu, Ulos Ragidup dianggap sebagai simbol kehidupan yang hidup dan mengalir, yang terus berlanjut dalam tradisi dan budaya masyarakat Batak.', 'Tradisional'),
('P0002', NULL, 'Ragihotang', 'WhatsApp Image 2025-04-22 at 22.25.59_0d729d2c.jpg', 'Ulos Ragihotang adalah salah satu jenis ulos tradisional Batak yang sarat akan makna dan digunakan dalam berbagai momen penting, baik dalam upacara adat maupun sebagai simbol dalam kehidupan sehari-hari. Nama \"Ragihotang\" berasal dari kata \"ragi\" yang berarti inti atau sumber, dan \"hotang\" yang berarti rotan—yang secara filosofis melambangkan kekuatan ikatan, kesetiaan, dan kekompakan. Ulos ini sering dipakai dalam upacara pernikahan sebagai pemberian dari orang tua kepada anak yang menikah, sebagai lambang restu dan doa agar rumah tangga yang dibangun menjadi kuat dan harmonis. Selain itu, ulos ini digunakan sebagai simbol pengikat hubungan kekeluargaan dalam berbagai acara adat, serta sebagai hadiah kehormatan kepada orang yang dihormati, seperti tokoh masyarakat atau pemuka adat. Dalam kehidupan sehari-hari, Ulos Ragihotang mengajarkan nilai-nilai penting seperti kesetiaan, daya tahan, dan pentingnya menjaga hubungan antarmanusia agar tetap kuat dan tidak mudah terputus, seperti rotan yang kuat namun tetap lentur.', '', '3. Rumus \r\n    1.	Jumlah benang lungsi = Lebar ulos (cm) × 10\r\n    2.	Susunan motif Ragihotang = 1 putih + 3 merah + 1 putih (3 posisi: tengah & dua sisi)\r\n    3.	Susunan warna benang lungsi:\r\n    4.	Susunan warna benang lungsi:\r\n      •	300 helai hitam\r\n      •	1 putih + 3 merah + 1 putih (motif Ragihotang tengah)\r\n      •	290 helai hitam\r\n      •	1 putih + 3 merah + 1 putih (motif sisi kiri)\r\n      •	300 helai hitam\r\n   5.Panjang tiap benang = Panjang kain (200 cm) + sisa pemasangan (50 cm) × 2\r\n      Panjang tiap benang = 200 cm + (50 cm × 2) = 300 cm (3 meter).\r\n\r\n4. Panghintaman – Menyusun Benang Lungsi\r\n   1. Ukur panjang benang lungsi: 4,5 meter per helai (agar cukup untuk panjang kain dan pemasangan).\r\n   2. 900 helai benang berwarna hitam.\r\n   3. Di helai ke-300 hingga 310:\r\n      •	1 putih – 3 merah – 1 putih (pola Ragihotang tengah).\r\n   4. Di helai ke-100–105 dan 795–800:\r\n      •	1 putih – 3 merah – 1 putih (pola Ragihotang sisi).\r\n   5. Gulung semua benang ke turak (penggulung), dalam urutan tetap dan rapi.\r\n\r\n5.  Mangalehon – Memasang Benang ke Alat Tenun\r\n     1. Masukkan satu per satu 900 helai benang ke sisorhon (sisir tenun), 10 helai per rongga (90 rongga total).\r\n     2. Masukkan benang ke torop (alat pembagi jalur atas-bawah) sesuai urutan silang.\r\n     3. Ikat bagian belakang ke penggulung belakang, bagian depan ke pemberat/penggulung depan.\r\n     4. Periksa ulang susunan warna agar tiga garis Ragihotang (tengah dan sisi) berada tepat pada posisinya.\r\n\r\n6. Mangtenun – Proses Menenun\r\n    1.	Duduk di alat tenun gedogan, injak pedal kanan dan kiri bergantian untuk membuka lungsi.\r\n    2.	Masukkan benang pakan hitam dari kanan ke kiri (menggunakan sekoci), lalu pukul dengan baliga agar rapat.\r\n    3.	Setiap 50 sisipan benang pakan, selipkan pola warna:\r\n      •	3 kali benang merah\r\n      •	1 kali benang putih\r\n      •	Lakukan ini di tengah dan di dua sisi\r\n      •	Total: 3 bagian motif Ragihotang pada kain\r\n    4.	Lanjutkan menenun hingga mencapai panjang 200 cm kain efektif (total proses ±2–3 hari kerja tergantung kecepatan).\r\n    5.	Pastikan setiap 50 baris motif warna dijahit rapi dan ditekan agar tidak geser.\r\n\r\n7. Pangurung – Menyelesaikan Tenunan\r\n    1.	Setelah panjang 200 cm tercapai, ikat dan potong benang dari alat tenun.\r\n    2.	Buat simpul ujung benang untuk menghindari lepas.\r\n    3.	Rapikan pinggiran menggunakan jarum tangan atau dijahit manual agar tidak terurai.\r\n\r\n8. Pagolong – Finishing\r\n    1.	Jemur kain di tempat teduh selama 6 jam.\r\n    2.	Setrika ulos menggunakan suhu sedang.\r\n    3.	Lipat kain menjadi tiga bagian memanjang, sesuai tradisi penyimpanan ulos Ragihotang.', 'Kapas\nBenang lungsi\nBenang pakan\nDaun tarum (pewarna biru tua/hitam)\nKulit kayu jaha/soga/kayu tinggi (pewarna merah/cokelat)\nKulit buah pinang atau daun-daunan lain (pewarna tambahan)\nTawas (pengikat warna)\nAir bersih', NULL, '200', '70', 'Ulos Ragi Hotang adalah kain tradisional khas Batak Toba yang memiliki makna sakral dalam budaya Batak. Ulos ini sering digunakan dalam upacara adat seperti pernikahan, kelahiran, dan pemakaman, serta sebagai simbol penghormatan atau doa.\r\n\r\nAsal-usulnya berkaitan erat dengan keterampilan menenun yang diwariskan turun-temurun oleh masyarakat Batak. Proses pembuatan ulos ini melibatkan pemintalan kapas menjadi benang, pewarnaan dengan bahan alami, dan penenunan menggunakan alat tradisional. Ragi Hotang memiliki warna dominan merah dan hitam, yang melambangkan kekuatan, kemakmuran, kesetiaan, dan kesucian.\r\n\r\nSetiap motif dan warna pada ulos ini tidak hanya memiliki estetika, tetapi juga makna simbolis yang mendalam dalam kehidupan masyarakat Batak.', 'Tradisional'),
('P0003', NULL, 'Sadum', 'WhatsApp Image 2025-04-22 at 23.03.01_32c74ad8.jpg', 'Ulos Sadum digunakan dalam kehidupan sehari-hari sebagai pelengkap pakaian, sering dikenakan sebagai selendang atau penutup bahu, baik saat berada di rumah maupun dalam kegiatan sehari-hari. Selain itu, ulos ini juga dipakai dalam berbagai upacara adat, meskipun lebih sederhana dibandingkan dengan jenis ulos lainnya, seperti Ulos Ragihotang. Ulos Sadum sering terlihat dalam perayaan kecil atau upacara adat keluarga, seperti pernikahan atau kelahiran, dan juga diberikan kepada tamu yang dihormati. Dalam konteks simbolis, ulos Sadum melambangkan kehormatan dan penghargaan, serta dipercaya membawa kekuatan dan perlindungan bagi pemakainya. Sebagai bagian dari tradisi Batak, ulos ini juga menunjukkan keterikatan kuat dengan budaya dan identitas masyarakat Batak, sering digunakan untuk memperkuat ikatan sosial dan persatuan dalam komunitas.', 'Salah satu jenis ulos khas Batak Toba yang memiliki warna mencolok dan motif simetris.\nWarna dominan: merah terang, hitam, dan benang emas.\nDigunakan dalam acara adat sebagai simbol kasih sayang, restu, dan penghormatan.\nUmumnya diberikan kepada menantu perempuan atau orang yang sangat dihormati.\nTermasuk ulos yang bernilai tinggi secara estetika dan budaya.', '3. Rumus\r\n    Jumlah benang lungsi = Lebar ulos (cm) × 10\r\n    Susunan motif Sadum modern = Garis-garis horizontal warna emas, kuning, hijau, perak secara berkala\r\n    Susunan warna benang lungsi:\r\n    900 helai benang merah menyala sebagai dasar\r\n    Sisipan benang emas, kuning, hijau, dan perak ditempatkan setiap ±100 helai secara merata\r\n    Panjang tiap benang = Panjang kain (200 cm) + cadangan mesin (30 cm × 2)\r\n    Panjang benang = 200 + 60 = 260 cm (2,6 meter)\r\n\r\n4. Digital Winding – Menyusun Benang Lungsi\r\n    Ukur panjang benang lungsi: 2,6 meter per helai menggunakan mesin winding otomatis.\r\n    Siapkan 900 helai benang warna merah menyala.\r\n    Selipkan motif warna di titik-titik tertentu:\r\n    Helai ke-100: benang emas\r\n    Helai ke-200: benang kuning\r\n    Helai ke-300: benang hijau\r\n    Helai ke-400: benang perak\r\n    Ulangi pola hingga helai ke-900\r\n    Gulung semua benang ke dalam spool digital, urutan tetap terjaga rapi dan sesuai pola Sadum.\r\n\r\n5. Auto Warping – Memasang Benang ke Mesin Tenun\r\n    Masukkan satu per satu 900 helai benang ke sisorhon (reed/sisir tenun) menggunakan mesin warping otomatis.\r\n   10 helai per rongga → 90 rongga total\r\n    Masukkan benang ke torop (alat pembagi jalur atas-bawah) sesuai urutan silang digital.\r\n    Ikat bagian belakang ke penggulung belakang mesin, bagian depan ke penggulung depan.\r\n    Periksa ulang pola warna pada sistem digital agar posisi garis motif Sadum tersebar simetris dan konsisten.\r\n\r\n6. Digital Weaving – Proses Menenun\r\n    Aktifkan mesin tenun semi-digital (Jacquard atau Dobby).\r\n    Benang pakan utama: merah menyala dimasukkan otomatis dari kanan ke kiri.\r\n    Setiap 60 sisipan benang pakan, selipkan motif horizontal:\r\n    2 sisipan benang emas\r\n    2 sisipan benang kuning\r\n    2 sisipan benang hijau\r\n    2 sisipan benang perak\r\n    Motif ini ditampilkan berulang horizontal sepanjang kain.\r\n    Lanjutkan menenun hingga mencapai panjang 200 cm kain efektif (total proses ±10 jam kerja).\r\n    Sistem otomatis menekan dan merapatkan benang setiap sisipan agar hasil padat dan rata.\r\n\r\n7. Finishing Mekanis – Menyelesaikan Tenunan\r\n    Setelah 200 cm tercapai, mesin otomatis memotong benang dari alat tenun.\r\n    Ujung kain dikunci dengan jahitan overlock industri agar tidak terurai.\r\n    Pinggiran kain dirapikan menggunakan mesin pemotong tepi atau laser sealing.\r\n\r\n8. Pagolong – Finishing\r\n    Kain dijemur di ruang pengering suhu rendah (±40°C) selama 2–3 jam.\r\n    Disetrika menggunakan setrika uap industri (steam press).\r\n    Kain dilipat secara otomatis menjadi tiga bagian memanjang, sesuai tradisi penyimpanan Ulos Sadum.', 'Benang kapas\nPewarna alami\nKapur sirih (sebagai bahan pengikat pewarna alami)\nAir (untuk pewarnaan dan pencucian)\nGaram (untuk membantu proses pewarnaan dan memperkuat warna)\nSerbuk kayu atau abu (untuk membantu proses pembuatan pewarna alami)\nGetah pohon (untuk melapisi benang atau memberikan tekstur pada ulos)\nMinyak kelapa atau minyak alami (untuk merawat benang dan ulos setelah selesai ditenun)', NULL, '200', '60', 'Ulos Sadum berasal dari suku Batak Toba, yang mendiami daerah sekitar Danau Toba, Sumatra Utara. Ulos ini merupakan bagian dari tradisi tenun yang sudah ada sejak ratusan tahun lalu. Seperti halnya ulos-ulos lainnya dalam budaya Batak, ulos Sadum memiliki peran penting dalam berbagai upacara adat, seperti pernikahan, kelahiran, dan kematian.\r\n\r\nSecara historis, ulos Sadum dianggap sebagai simbol keberkahan, keselamatan, dan perlindungan. Nama \"Sadum\" sendiri merujuk pada salah satu jenis ulos dengan motif tertentu yang khas. Pada awalnya, ulos ini hanya digunakan oleh kalangan tertentu dalam masyarakat Batak, dan biasanya ditenun secara manual menggunakan alat tenun tradisional. Ulos Sadum seringkali digunakan dalam acara-acara besar atau penting yang melibatkan masyarakat Batak, untuk mempererat ikatan antara keluarga dan komunitas.\r\n\r\nSeiring berjalannya waktu, ulos Sadum tetap mempertahankan fungsinya dalam kehidupan sosial dan budaya Batak, meskipun terdapat pengaruh modernisasi dalam beberapa aspek. Namun, nilai tradisional dan simbolisme yang terkandung dalam ulos ini tetap dijaga dan dilestarikan sebagai bagian dari warisan budaya Batak.', 'Modern'),
('P0004', NULL, 'Ragi Hotang', 'psr.jpg', 'Ulos Ragi Hotang modern adalah kain tradisional Batak yang bermakna \"pengikat hati,\" dan kini banyak digunakan dalam kehidupan sehari-hari sebagai simbol kasih sayang dan persatuan. Selain dipakai dalam acara adat seperti pernikahan dan pemberian kepada bayi, Ragi Hotang juga sering dijadikan syal, selendang, atau aksesori fashion modern untuk menunjukkan identitas budaya dengan gaya kontemporer. Dalam rumah, ulos ini dimanfaatkan sebagai dekorasi dinding atau taplak meja untuk menciptakan suasana hangat dan penuh cinta. Ragi Hotang juga sering dijadikan cendera mata atau hadiah spesial kepada orang yang dihormati, serta sebagai tanda dukungan emosional dalam masa-masa sulit, sehingga penggunaannya meluas tidak hanya dalam tradisi tetapi juga dalam berbagai momen modern.', '', '3. Rumus Modernisasi\r\n    Jumlah Benang Lungsi = Lebar ulos (cm) × 10\r\n    (sama seperti tradisional untuk menjaga kepadatan motif)\r\n    Motif Ragihotang (Tengah & Dua Sisi) = Tetap: 1 putih + 3 merah + 1 putih\r\n    Susunan Benang Lungsi (Dengan Mesin Winding):\r\n    300 helai hitam\r\n    1 putih + 3 merah + 1 putih (motif tengah)\r\n    290 helai hitam\r\n    1 putih + 3 merah + 1 putih (motif sisi kiri)\r\n    300 helai hitam\r\n    Panjang Tiap Benang Lungsi = Panjang kain (200 cm) + cadangan mesin (30 cm × 2) = 260 cm\r\n\r\n4. Digital Winding – Penggulungan Benang Otomatis\r\n    Gunakan mesin winding otomatis untuk menggulung benang lungsi sepanjang 2,6 meter/helai.\r\n     Program mesin untuk menyisipkan benang motif Ragihotang di posisi:\r\n     Helai ke-300 s/d 305 (tengah)\r\n     Helai ke-100–105 & 795–800 (dua sisi)\r\n    Jumlah total benang lungsi tetap: 900 helai\r\n    Hasil winding langsung disimpan dalam bentuk rol siap pasang.\r\n\r\n5. Auto Warping – Pemasangan Benang ke Mesin Tenun\r\n    Gunakan mesin warping otomatis untuk memasukkan benang ke sisir (reed) dan torop (heddle) dengan akurasi tinggi.\r\n    10 helai benang dimasukkan per rongga sisir, menghasilkan 90 rongga.\r\n     Mesin membaca barcode pola motif, memastikan posisi garis Ragihotang tetap di tengah dan sisi secara tepat.\r\n     Sistem tension otomatis menjaga ketegangan benang stabil selama proses.\r\n\r\n6. Digital Weaving – Proses Menenun dengan Mesin Jacquard\r\n    Gunakan mesin tenun Jacquard semi-digital dengan pedal otomatis dan pola terprogram.\r\n    Benang pakan hitam dimasukkan otomatis oleh sistem shuttle (sekoci mekanik).\r\n    Setiap 50 baris benang pakan, mesin otomatis menyisipkan motif warna:\r\n    3 baris benang merah\r\n    1 baris benang putih\r\n    Motif ini muncul di tengah dan dua sisi kain, sesuai pola digital yang diprogram.\r\n    Proses penenunan selesai dalam waktu ±8–12 jam kerja, tergantung kecepatan mesin.\r\n\r\n7. Finishing Mekanis – Penyempurnaan Tenunan\r\n    Setelah panjang kain 200 cm tercapai, kain otomatis tergulung dan dipotong rapi oleh mesin.\r\n    Ujung benang dikunci dengan simpul otomatis atau dijahit tepi (overlock) menggunakan mesin jahit industri.\r\n    Pinggiran juga bisa menggunakan teknik laser cut & edge sealing agar tidak mudah terurai.\r\n\r\n8. Final Treatment – Finishing Modern\r\n    Kain dijemur atau diangin-anginkan dalam ruang pengering bersuhu rendah (±40°C) selama 2–3 jam.\r\n    Gunakan setrika uap industri (steam press) untuk merapikan tekstur kain.\r\n    Lipat ulos secara otomatis dengan mesin folding menjadi tiga bagian memanjang, mengikuti pola penyimpanan adat ulos Ragihotang.', NULL, NULL, '200', '70', 'Ulos Ragi Hotang berasal dari budaya Batak di Sumatera Utara, khususnya dari masyarakat Batak Toba, yang sejak zaman dahulu menggunakan ulos sebagai simbol ikatan batin, kasih sayang, dan doa perlindungan. Nama \"Ragi Hotang\" berarti \"corak rotan,\" melambangkan kekuatan dan kekokohan hubungan antar manusia, seperti rotan yang kuat dan sulit dipatahkan. Ulos ini secara tradisional diberikan dalam momen-momen penting seperti pernikahan, kelahiran, atau acara adat lainnya untuk mempererat hubungan keluarga dan komunitas. Seiring perkembangan zaman, Ulos Ragi Hotang tidak hanya dipakai dalam upacara adat, tetapi juga berkembang menjadi bagian dari busana, hadiah, dan dekorasi modern, tanpa kehilangan makna spiritual dan emosionalnya yang dalam.', 'Modern'),
('P0005', NULL, 'Ulos Mangiring', 'njgdnkj.jpg', 'Ulos Mangiring adalah salah satu jenis ulos tradisional Batak yang memiliki makna mendalam sebagai simbol pengharapan, kasih sayang, dan penyertaan dalam hidup seseorang. Dalam kehidupan sehari-hari, ulos ini banyak digunakan untuk mendampingi momen-momen penting, terutama ketika seorang anak atau orang muda sedang memulai tahap baru seperti memasuki dunia pendidikan, meraih prestasi, memulai pekerjaan, atau memasuki jenjang pernikahan. Diberikan oleh orang tua atau kerabat dekat, Ulos Mangiring menjadi simbol restu dan doa agar penerimanya senantiasa mendapatkan penyertaan dan perlindungan, baik dari keluarga maupun dari Tuhan. Tak hanya dalam konteks upacara adat, ulos ini juga sering dijadikan hadiah ulang tahun, kenang-kenangan, atau tanda kasih dalam acara syukuran, peresmian usaha, bahkan sebagai hiasan rumah yang sarat makna. Keberadaan Ulos Mangiring mencerminkan betapa kuatnya nilai budaya dan spiritual dalam masyarakat Batak, menjadikannya lebih dari sekadar kain tenun, melainkan bagian dari ungkapan cinta, penghargaan, dan harapan yang terus mengiringi kehidupan sehari-hari.', '', 'targttrqrtq3t', NULL, NULL, '200', '90', 'Ulos Mangiring berasal dari budaya Batak Toba di Sumatera Utara, yang telah menenun ulos sejak ratusan tahun lalu sebagai bagian tak terpisahkan dari kehidupan adat dan spiritual mereka. Kata Mangiring dalam bahasa Batak berarti “mengiringi” atau “mengiringkan”, yang merujuk pada fungsinya untuk menyertai seseorang dalam perjalanannya melalui berbagai tahapan hidup.\r\n\r\nAwalnya, ulos digunakan sebagai penghangat tubuh karena suhu dingin di dataran tinggi Tapanuli. Namun, seiring waktu, ulos berkembang menjadi simbol adat yang sakral dan berkelas tinggi. Ulos Mangiring muncul sebagai salah satu varian yang ditujukan untuk menyampaikan kasih sayang dan harapan kepada generasi muda atau seseorang yang baru memulai fase kehidupan baru. Ia diberikan sebagai bentuk restu dan doa agar si penerima selalu diiringi dengan berkat, kesehatan, dan kebahagiaan.\r\n\r\nUlos Mangiring biasanya ditenun oleh para perempuan Batak menggunakan alat tenun tradisional yang disebut gedogan, dan prosesnya bisa memakan waktu beberapa minggu hingga bulan tergantung tingkat kerumitan motifnya. Motifnya sendiri bersifat khas, dengan garis-garis dan simbol yang mengandung filosofi tentang perjalanan hidup dan kebersamaan keluarga.', 'Tradisional'),
('P0006', NULL, 'Ragihidup', 'aydgdf.jpg', 'Ulos Ragihidup adalah salah satu kain tenun tradisional Batak yang memiliki makna mendalam, melambangkan kehidupan yang penuh berkah, kemakmuran, dan kesejahteraan. Dalam konteks adat Batak, ulos ini sering diberikan sebagai tanda kasih dan doa restu dalam berbagai peristiwa penting, seperti kelahiran, pernikahan, dan upacara adat lainnya. Nama \"Ragihidup\" sendiri berasal dari kata \"ragi\" yang berarti motif atau corak, dan \"hidup\" yang mencerminkan makna simbolis kehidupan yang baik, sejahtera, dan penuh harapan.\r\n\r\nDalam kehidupan modern, Ulos Ragihidup mengalami adaptasi bentuk dan fungsi agar tetap relevan di tengah arus globalisasi dan perkembangan mode. Ulos ini tidak hanya dikenakan dalam acara adat, tetapi juga telah banyak digunakan sebagai elemen busana kontemporer, seperti gaun, jas, selendang, hingga aksesoris modern seperti tas, dompet, dan syal. Tak hanya itu, kain ini juga dijadikan dekorasi interior rumah bergaya etnik, sebagai penanda identitas dan bentuk penghormatan terhadap warisan budaya.\r\n\r\nMotif dan warna pada Ulos Ragihidup modern tetap mempertahankan filosofi Batak yang kaya:\r\n\r\nMerah melambangkan keberanian, semangat hidup, dan kasih sayang,\r\n\r\nHitam menggambarkan keteguhan hati, kekuatan, dan keabadian,\r\n\r\nPutih menyiratkan kesucian, ketulusan, dan harapan akan masa depan yang baik.\r\n\r\nDengan susunan motif yang rapi dan estetika yang kuat, Ulos Ragihidup modern menjadi representasi sempurna dari perpaduan antara nilai tradisi dan inovasi desain, menjadikannya bukan hanya warisan budaya, tetapi juga produk kreatif yang bisa bersaing secara global. Ulos ini kini tidak hanya dikenakan oleh masyarakat Batak, tetapi juga oleh pecinta budaya dan fashion dari berbagai kalangan, sebagai bentuk penghargaan terhadap nilai lokal yang universal.', '', '3. Rumus\r\n    Jumlah benang lungsi = Lebar ulos (cm) × 10\r\n    Susunan motif Ragihidup modern = Motif berulang garis putih dan merah menyala dalam blok horizontal\r\n    Susunan warna benang lungsi:\r\n    920 helai benang dasar hitam\r\n    Setiap 230 helai, selipkan pola: 1 putih – 2 merah – 1 putih (4 titik total)\r\n    Panjang tiap benang = Panjang kain (200 cm) + cadangan pemasangan mesin (30 cm × 2)   \r\n    Panjang benang = 200 + 60 = 260 cm (2,6 meter)\r\n\r\n4. Digital Winding – Menyusun Benang Lungsi\r\n    Ukur panjang benang lungsi: 2,6 meter per helai menggunakan mesin winding otomatis.\r\n    Siapkan total 920 helai benang hitam (sebagai dasar).\r\n    Pada posisi helai ke:\r\n    230: sisipkan 1 putih – 2 merah – 1 putih\r\n    460: sisipkan lagi pola sama\r\n    690: ulangi pola\r\n    920: terakhir sisipan\r\n    Benang digulung ke spool digital sesuai urutan dan disimpan dalam batch produksi.\r\n\r\n5. Auto Warping – Memasang Benang ke Mesin Tenun\r\n    Gunakan mesin warping otomatis untuk memasukkan 920 helai benang ke sisorhon (reed), 10 helai per rongga → 92 rongga total.\r\n    Masukkan benang ke torop (heddle) sesuai silang tradisional.\r\n    Ikat ke sistem penggulung depan dan belakang pada mesin tenun elektronik.\r\n    Verifikasi dengan sistem scanner pola benang untuk memastikan posisi empat blok motif Ragihidup berada tepat dan merata sepanjang kain.\r\n\r\n6. Digital Weaving – Proses Menenun\r\n    Aktifkan mesin tenun Jacquard semi-digital dengan desain Ragihidup yang telah diprogram.\r\n    Gunakan benang pakan hitam sebagai warna dasar.\r\n    Selipkan motif horizontal secara berkala:\r\n    Setiap 60 sisipan benang pakan, tambahkan:\r\n    2 benang merah\r\n    1 benang putih\r\n    2 benang merah\r\n    Motif disisipkan pada 4 bagian sepanjang kain\r\n    Proses penenunan berlangsung ±10 jam untuk panjang 200 cm.\r\n    Mesin otomatis melakukan pemadatan benang (baliga otomatis) agar motif tidak bergeser.\r\n\r\n7. Finishing Mekanis – Menyelesaikan Tenunan\r\n    Setelah kain mencapai panjang efektif, mesin otomatis memotong benang dari alat tenun.\r\n    Ujung-ujung benang dikunci menggunakan jahitan overlock mesin industri.\r\n    Pinggiran kain disegel dengan laser untuk mencegah terurai.\r\n\r\n8. Pagolong – Finishing\r\n    Kain dikeringkan dalam ruangan ventilasi atau pengering suhu rendah (±40°C) selama 3 jam.\r\n    Disetrika menggunakan steam press untuk hasil rata dan bersih.\r\n    Kain dilipat tiga bagian memanjang menggunakan mesin pelipat otomatis, sesuai standar penyimpanan ulos Ragihidup.', NULL, NULL, '242', '127', 'Ulos Ragihidup berasal dari warisan tenun tradisional suku Batak Toba di Sumatera Utara, Indonesia. Nama “Ragihidup” sendiri berasal dari dua kata dalam bahasa Batak: “ragi” yang berarti corak atau motif, dan “hidup” yang bermakna kehidupan. Secara harfiah, Ulos Ragihidup dapat diartikan sebagai “motif kehidupan” atau “hiasan hidup,” yang mencerminkan nilai-nilai harapan, keberlangsungan, dan kesejahteraan dalam hidup manusia.\r\n\r\nSejak dahulu, masyarakat Batak percaya bahwa ulos bukan hanya kain biasa, melainkan simbol kekuatan spiritual dan sosial. Ulos Ragihidup dipercaya membawa berkah dan perlindungan bagi si pemakai, terutama dalam fase-fase penting kehidupan seperti kelahiran, pernikahan, dan pemberkatan. Kain ini sering diberikan sebagai ulos holong (ulos kasih sayang) atau ulos parompa (untuk bayi yang baru lahir), sebagai lambang harapan agar hidup anak tersebut penuh kemakmuran dan dilindungi.\r\n\r\nUlos Ragihidup tidak ditemukan di semua daerah Batak, melainkan hanya ditenun oleh kelompok penenun tertentu yang telah mewarisi pola dan makna khas dari generasi ke generasi. Kain ini dulunya hanya dipakai oleh orang-orang tertentu dalam struktur adat, seperti orang tua yang memberikan berkat kepada anaknya, atau sebagai bagian dari prosesi upacara adat yang sangat sakral.\r\n\r\nMotif Ulos Ragihidup dikenal karena memiliki garis-garis halus dan pola geometris yang kaya makna, biasanya dikombinasikan dengan warna merah, hitam, dan putih, yang masing-masing mengandung filosofi mendalam dalam kosmologi Batak. Warna dan motif tersebut tidak hanya mempercantik kain, tetapi juga berfungsi sebagai bahasa visual yang menyampaikan pesan budaya dan spiritual.\r\n\r\nSeiring waktu, Ulos Ragihidup mengalami transformasi bentuk dan fungsi. Di era modern, meskipun penggunaannya dalam konteks adat masih sangat dijaga, banyak desainer dan pengrajin mulai mengadaptasi Ulos Ragihidup ke dalam bentuk-bentuk modern seperti busana, aksesori, dan karya seni. Adaptasi ini dilakukan tanpa meninggalkan nilai-nilai luhur dan simbolisme yang melekat pada kain tersebut, menjadikannya sebagai warisan budaya yang hidup dan terus berkembang.', 'Modern'),
('P0007', NULL, 'Ulos Ragi Pakko', 'dbmds.jpg', 'Ulos Ragi Pakko dalam kehidupan sehari-hari masyarakat Batak memiliki peran penting sebagai simbol kasih sayang, penghormatan, dan status sosial yang diwariskan secara turun-temurun. Ulos ini lazim digunakan dalam berbagai momen sakral dan bermakna, seperti saat pernikahan, di mana orang tua memberi ulos kepada anak sebagai lambang restu dan harapan atas kehidupan rumah tangga yang sejahtera. Ketika seorang cucu pertama lahir, kakek dan nenek akan memberikan ulos ini sebagai ungkapan sukacita dan tanda bahwa garis keturunan terus berlanjut. Dalam upacara adat lainnya seperti naik sidi, kematian, atau pesta syukuran, ulos Ragi Pakko dikenakan sebagai penutup tubuh atau selendang yang menunjukkan kedewasaan, penghargaan, atau duka cita yang mendalam. Di luar acara adat, ulos ini sering dijadikan hiasan dinding rumah sebagai simbol identitas budaya, dan kadang dikenakan dalam acara formal untuk menunjukkan kebanggaan akan warisan Batak. Keberadaannya dalam kehidupan sehari-hari mencerminkan kedalaman makna budaya Batak yang terus dijaga melalui simbol kain tenun yang kaya nilai ini.', '', '3. Rumus\r\n   Jumlah benang lungsi = Lebar ulos (cm) × 10\r\n   (contoh: 100 cm × 10 = 1000 helai)\r\n   Susunan motif Ragi Pakko:\r\n   2 putih + 2 merah + 2 putih (tengah dan dua sisi)\r\n   Susunan warna benang lungsi:\r\n   350 helai hitam\r\n   2 putih + 2 merah + 2 putih (motif Ragi Pakko tengah)\r\n   300 helai hitam\r\n   2 putih + 2 merah + 2 putih (motif sisi kiri)\r\n   350 helai hitam\r\n   Panjang tiap benang = Panjang kain (200 cm) + sisa pemasangan (50 cm × 2) = 300 cm (3 meter)\r\n\r\n4. Panghintaman – Menyusun Benang Lungsi\r\n    Ukur panjang benang lungsi: 4,5 meter per helai (untuk memastikan cukup hingga pengikatan).\r\n    Jumlah total benang: ±1000 helai berwarna hitam.\r\n    Posisi motif Ragi Pakko:\r\n    Helai ke-350 sampai 355 → 2 putih – 2 merah – 2 putih (motif tengah)\r\n    Helai ke-100–105 dan 895–900 → 2 putih – 2 merah – 2 putih (motif sisi)\r\n    Gulung seluruh benang ke turak secara teratur sesuai urutan warna.\r\n\r\n5. Mangalehon – Memasang Benang ke Alat Tenun\r\n    Masukkan 1000 helai benang ke dalam sisorhon (sisir tenun), 10 helai per rongga → total 100 rongga.\r\n    Masukkan benang ke torop sesuai pola silang atas-bawah.\r\n    Ikat bagian belakang ke penggulung belakang, bagian depan ke pemberat/penggulung depan.\r\n    Pastikan posisi 3 pola Ragi Pakko berada tepat pada bagian tengah dan dua sisi kain.\r\n\r\n6. Mangtenun – Proses Menenun\r\n    Duduk di alat tenun gedogan, injak pedal kanan dan kiri untuk membuka celah lungsi.\r\n    Masukkan benang pakan hitam dari kanan ke kiri menggunakan sekoci, lalu tekan dengan baliga.\r\n    Setiap 60 sisipan, masukkan pola pakan warna:\r\n    2 helai putih\r\n    2 helai merah\r\n    2 helai putih\r\n    (dilakukan di tengah dan dua sisi)\r\n    Lanjutkan menenun hingga mencapai panjang 200 cm kain efektif.\r\n    (Proses ±2–3 hari tergantung kecepatan penenun)\r\n    Tekan dan rapatkan setiap baris motif agar tidak bergeser.\r\n\r\n7. Pangurung – Menyelesaikan Tenunan\r\n    Setelah panjang kain mencapai 200 cm, potong benang dari alat tenun.\r\n    Buat simpul ujung benang untuk mencegah terurai.\r\n    Rapikan pinggiran menggunakan jarum tangan atau mesin jahit.\r\n\r\n8. Pagolong – Finishing\r\n    Jemur ulos di tempat teduh selama 6–8 jam agar warna tidak pudar.\r\n    Setrika dengan suhu sedang hingga rapi.\r\n    Lipat ulos menjadi tiga bagian memanjang, mengikuti tradisi penyimpanan ulos Ragi Pakko.', NULL, NULL, '200', '100', 'Ulos Ragi Pakko berasal dari budaya Batak Toba di Sumatera Utara dan merupakan salah satu jenis ulos yang memiliki nilai adat dan spiritual tinggi. Nama \"Ragi Pakko\" berasal dari kata ragi yang berarti “isi” atau “jiwa” dan pakko yang mengacu pada kelengkapan atau kesempurnaan. Ulos ini diyakini sebagai simbol kasih sayang yang utuh dan sempurna, sehingga dahulu hanya digunakan dalam upacara adat tertentu oleh keluarga bangsawan atau tokoh adat. Ulos Ragi Pakko biasanya diwariskan secara turun-temurun dan diberikan pada momen penting seperti pernikahan, kelahiran cucu pertama, atau sebagai bentuk penghormatan terakhir dalam pemakaman. Keberadaan dan penggunaannya menunjukkan status sosial dan erat kaitannya dengan nilai-nilai kekeluargaan dan penghormatan dalam masyarakat Batak.', 'Tradisional'),
('P0008', NULL, 'Ulos Sibolang', 'kndfsbk.jpg', 'Ulos Sibolang modern adalah kain tenun Batak yang merupakan hasil inovasi dari ulos Sibolang tradisional. Ciri khas utamanya adalah motif kotak-kotak kecil berwarna putih atau biru di atas dasar hitam, yang melambangkan keteguhan, penghiburan, dan semangat menghadapi duka atau perjuangan hidup. Dalam versi modern, warna dan komposisi bisa sedikit disesuaikan agar cocok untuk kebutuhan kontemporer seperti fashion dan interior.\r\n\r\nUlos ini biasanya memiliki ukuran sekitar 2 meter panjang dan 1 meter lebar, menjadikannya serbaguna untuk berbagai keperluan. Dalam kehidupan sehari-hari, ulos Sibolang modern tidak hanya digunakan dalam konteks adat Batak—seperti acara kematian, penghiburan, atau pemberian ulos kepada anggota keluarga yang menghadapi kesulitan—tetapi juga sering dimanfaatkan sebagai bahan fashion (outer, scarf, tas), aksesori interior (taplak, hiasan dinding), dan souvenir budaya.\r\n\r\nDaya tarik utamanya adalah kombinasi nilai budaya yang kuat dengan tampilan visual yang elegan dan netral, sehingga cocok digunakan lintas generasi dan lintas konteks.', '', '3. Rumus Modernisasi\r\n   Jumlah Benang Lungsi: Lebar ulos (cm) × 10.\r\n   Contoh: Lebar 90 cm × 10 = 900 helai benang lungsi.\r\n   Motif Sibolang: Motif kotak-kotak kecil berwarna putih atau biru di atas dasar hitam, melambangkan keteguhan dan semangat menghadapi tantangan hidup.\r\n   Susunan Benang Lungsi (Dengan Mesin Winding):\r\n   300 helai hitam\r\n   Motif tengah: 1 putih + 1 biru + 1 putih\r\n   290 helai hitam\r\n   Motif sisi kiri: 1 putih + 1 biru + 1 putih\r\n   300 helai hitam\r\n   Panjang Tiap Benang Lungsi: Panjang kain (200 cm) + cadangan mesin (30 cm × 2) = 260 cm.\r\n\r\n 4. Digital Winding – Penggulungan Benang Otomatis\r\n     Gunakan mesin winding otomatis untuk menggulung benang lungsi sepanjang 2,6 meter per helai.\r\n     Program mesin untuk menyisipkan motif kotak-kotak Sibolang di posisi:\r\n     Helai ke-300 s/d 302 (tengah)\r\n     Helai ke-100–102 & 797–799 (dua sisi)\r\n    Jumlah total benang lungsi: 900 helai.\r\n    Hasil winding langsung disimpan dalam bentuk rol siap pasang.\r\n\r\n5. Auto Warping – Pemasangan Benang ke Mesin Tenun\r\n   Gunakan mesin warping otomatis untuk memasukkan benang ke sisir (reed) dan torop (heddle) dengan akurasi tinggi.\r\n   10 helai benang dimasukkan per rongga sisir, menghasilkan 90 rongga.\r\n   Mesin membaca barcode pola motif, memastikan posisi motif kotak-kotak Sibolang tetap di tengah dan sisi secara tepat.\r\n   Sistem tension otomatis menjaga ketegangan benang stabil selama proses.\r\n\r\n6. Digital Weaving – Proses Menenun dengan Mesin Jacquard\r\n    Gunakan mesin tenun Jacquard semi-digital dengan pedal otomatis dan pola terprogram.\r\n    Benang pakan hitam dimasukkan otomatis oleh sistem shuttle (sekoci mekanik).\r\n    Setiap 50 baris benang pakan, mesin otomatis menyisipkan motif warna:\r\n    1 baris benang putih\r\n    1 baris benang biru\r\n    1 baris benang putih\r\n    Motif ini muncul di tengah dan dua sisi kain, sesuai pola digital yang diprogram.\r\n    Proses penenunan selesai dalam waktu ±8–12 jam kerja, tergantung kecepatan mesin.\r\n\r\n7. Finishing Mekanis – Penyempurnaan Tenunan\r\n    Setelah panjang kain 200 cm tercapai, kain otomatis tergulung dan dipotong rapi oleh mesin.\r\n    Ujung benang dikunci dengan simpul otomatis atau dijahit tepi (overlock) menggunakan mesin jahit industri.\r\n    Pinggiran juga bisa menggunakan teknik laser cut & edge sealing agar tidak mudah terurai.\r\n\r\n8. Final Treatment – Finishing Modern\r\n    Kain dijemur atau diangin-anginkan dalam ruang pengering bersuhu rendah (±40°C) selama 2–3 jam.\r\n    Gunakan setrika uap industri (steam press) untuk merapikan tekstur kain.\r\n    Lipat ulos secara otomatis dengan mesin folding menjadi tiga bagian memanjang, mengikuti pola penyimpanan adat ulos Sibolang.', NULL, NULL, '200', '90', 'Ulos Sibolang merupakan salah satu jenis kain tenun tradisional khas suku Batak yang berasal dari Sumatera Utara, Indonesia. Secara harfiah, \"ulos\" berarti selimut, yang awalnya digunakan oleh nenek moyang suku Batak untuk menghangatkan tubuh dari udara dingin di daerah pegunungan tempat mereka tinggal. Seiring waktu, ulos berkembang menjadi simbol kasih sayang, restu, dan persatuan dalam berbagai upacara adat. Ulos Sibolang memiliki ciri khas warna dasar hitam dengan motif garis-garis biru dan putih. Dalam tradisi Batak, ulos ini sering digunakan dalam upacara kematian, terutama untuk orang yang telah menikah namun belum memiliki cucu. Penggunaan ulos ini melambangkan penghormatan dan doa bagi arwah yang telah meninggal. Dengan perkembangan zaman, proses pembuatan Ulos Sibolang mengalami modernisasi untuk meningkatkan efisiensi dan kualitas tanpa menghilangkan nilai-nilai budaya yang terkandung di dalamnya.', 'Modern'),
('P0009', NULL, 'Ulos Simarinjam Sisi  ', 'fvvsvbkdsf.jpg', 'Ulos Simarinjam Sisi adalah salah satu jenis ulos tradisional dari masyarakat Batak Toba yang kaya akan makna filosofis dan nilai simbolik. Nama \"Simarinjam Sisi\" secara harfiah berarti \"yang menjepit sisi\", merujuk pada motif atau cara penggunaan ulos ini yang menyemat erat di bagian sisi tubuh saat dikenakan. Ulos ini bukan hanya sebuah kain, melainkan bagian integral dari identitas, struktur sosial, dan spiritualitas masyarakat Batak.\r\n\r\nDalam tradisi Batak, setiap jenis ulos memiliki makna dan fungsinya masing-masing, dan Ulos Simarinjam Sisi sering dikaitkan dengan kehormatan, kehangatan, dan ikatan sosial yang kuat antaranggota masyarakat. Ulos ini sangat umum diberikan dalam acara-acara adat sebagai simbol penghargaan, doa keselamatan, dan rasa hormat kepada seseorang, terutama kepada pihak-pihak yang memiliki posisi terhormat dalam suatu acara, seperti tulang (paman dari pihak ibu), hula-hula (keluarga pihak istri), atau kepada pengantin baru.\r\n\r\nUlos Simarinjam Sisi umumnya digunakan dalam upacara adat seperti:\r\n\r\nPernikahan adat Batak, di mana ulos ini dikenakan oleh orang tua atau keluarga dekat sebagai bagian dari ritus pemberian ulos (mangulosi).\r\n\r\nUpacara kelahiran atau upa-upa, sebagai simbol doa dan perlindungan.\r\n\r\nAcara duka, sebagai bentuk penghormatan terakhir kepada yang meninggal dunia.\r\n\r\nPenerimaan tamu agung, sebagai bentuk penyambutan dengan penghormatan tinggi.\r\n\r\nDalam kehidupan sehari-hari masyarakat Batak, walaupun ulos tidak dikenakan setiap hari, kehadirannya tetap terasa penting. Ulos biasanya disimpan dengan penuh hormat dan hanya dikeluarkan dalam momen-momen penting yang berkaitan dengan daur hidup manusia. Dalam banyak rumah adat Batak, ulos sering digantung atau dipajang sebagai simbol status, warisan leluhur, dan penghargaan terhadap tradisi.', '', '3. Rumus\r\n    Jumlah benang lungsi = Lebar ulos (cm) × 10\r\n    → 60 cm × 10 = 600 helai benang lungsi\r\n    Motif utama Simarinjam Sisi:\r\n    Motif garis putih bersusun secara simetris di tengah dan di kedua sisi\r\n    Tidak menggunakan warna merah, hanya hitam sebagai dasar dan putih sebagai pola motif\r\n    Susunan warna benang lungsi (simetris kiri–tengah–kanan):\r\n    250 helai benang hitam\r\n    5 helai benang putih (motif sisi kiri)\r\n    90 helai benang hitam\r\n    5 helai benang putih (motif tengah)\r\n    90 helai benang hitam\r\n    5 helai benang putih (motif sisi kanan)\r\n    155 helai benang hitam\r\n    Panjang tiap helai benang lungsi =\r\n    Panjang kain (250 cm) + sisa pemasangan (50 cm × 2) = 350 cm / 3,5 meter\r\n\r\n4. Panghintaman – Menyusun Benang Lungsi\r\n    Ukur panjang benang lungsi: 3,5 meter per helai\r\n    Susun 600 helai benang sesuai urutan warna berikut:\r\n    Helai 1–250: benang hitam\r\n    Helai 251–255: benang putih (motif sisi kiri)\r\n    Helai 256–345: benang hitam\r\n    Helai 346–350: benang putih (motif tengah)\r\n    Helai 351–440: benang hitam\r\n    Helai 441–445: benang putih (motif sisi kanan)\r\n    Helai 446–600: benang hitam\r\n    Gulung semua benang ke turak secara berurutan, pastikan tidak tertukar warnanya\r\n\r\n5. Mangalehon – Memasang Benang ke Alat Tenun\r\n    Masukkan 600 helai benang ke sisorhon (sisir tenun)\r\n    → 10 helai per rongga, total 60 rongga\r\n    Pasang benang ke torop, pastikan setiap benang menyilang sesuai pola\r\n    Ikat bagian belakang ke penggulung belakang, bagian depan ke pemberat depan\r\n    Periksa ulang agar garis putih berada tepat pada posisi kiri, tengah, dan kanan\r\n\r\n6. Mangtenun – Proses Menenun\r\n    Duduk di alat tenun gedogan, injak pedal secara bergantian\r\n    Masukkan benang pakan berwarna hitam menggunakan sekoci dari kanan ke kiri\r\n    Setiap 30–40 sisipan benang pakan, sisipkan:\r\n    1 helai benang putih sebagai aksen motif horizontal (jika diinginkan)\r\n    Namun dalam versi klasik Simarinjam Sisi: pola pakan polos hitam saja untuk menonjolkan garis putih lungsi\r\n    Tenun hingga panjang kain mencapai 250 cm\r\n    Waktu pengerjaan ± 4–6 hari, tergantung keterampilan dan kecepatan penenun\r\n\r\n7. Pangurung – Menyelesaikan Tenunan\r\n    Setelah panjang tercapai, ikat dan potong benang dari alat tenun\r\n    Buat simpul pengunci pada ujung benang\r\n    Rapikan bagian pinggir dengan jarum tangan atau dijahit pinggiran secara manual\r\n\r\n8. Pagolong – Finishing\r\n   Jemur kain di tempat sejuk, teduh, dan tidak terkena sinar matahari langsung selama ±6 jam\r\n   Setrika dengan suhu sedang, jangan terlalu panas untuk menjaga warna putih tetap cerah\r\n   Lipat kain tiga bagian secara memanjang sesuai cara penyimpanan tradisional Ulos Simarinjam Sisi', NULL, NULL, '250', '50', 'Ulos Simarinjam Sisi berasal dari tradisi menenun masyarakat Batak Toba di wilayah Sumatera Utara, khususnya di daerah Tapanuli. Nama \"Simarinjam Sisi\" memiliki arti simbolis; “simarinjam” berarti “berdekatan” atau “merapat”, sedangkan “sisi” berarti “pinggir”. Nama ini merujuk pada pola khas ulos ini yang memiliki sisi atau garis-garis tepi yang tampak seperti saling mendekat atau menyatu di bagian ujung kain, melambangkan kekompakan, keselarasan, dan keharmonisan dalam keluarga atau masyarakat.\r\n\r\nSecara historis, Ulos Simarinjam Sisi dulunya tidak termasuk dalam kategori ulos yang digunakan untuk upacara adat besar, melainkan lebih banyak dipakai dalam kehidupan sehari-hari atau sebagai bentuk penghormatan dalam acara kecil seperti pemberian tanda kasih sayang atau persaudaraan. Namun, seiring perkembangan waktu, ulos ini juga memiliki makna adat tersendiri, yaitu sebagai penguat hubungan antarkeluarga atau antarindividu, terutama dalam konteks mangulosi (memberi ulos) sebagai tanda restu atau harapan agar hubungan tetap erat.\r\n\r\nDari segi teknik, ulos ini dikenal karena kesederhanaan motifnya, namun tetap memerlukan keahlian tinggi karena penempatan motif di sisi kain harus seimbang dan simetris. Ini mencerminkan filosofi Batak tentang pentingnya keseimbangan dalam hidup dan hubungan sosial. Meski tidak semegah ulos Ragidup atau Ragi Hotang, ulos Simarinjam Sisi tetap memiliki tempat penting dalam budaya Batak karena nilai simbolik dan proses tenunannya yang mengandung makna mendalam.', 'Tradisional');
INSERT INTO `produk` (`kode_produk`, `admin_id`, `nama`, `image`, `deskripsi`, `detail`, `cara_pembuatan`, `bahan`, `jumlah_benang`, `panjang`, `lebar`, `sejarah`, `kategori`) VALUES
('P0010', NULL, 'Ulos Pinucaan ', 'aejyfdg.jpg', 'Ulos Pinucaan Modern merupakan hasil adaptasi kain tradisional Batak yang telah berkembang mengikuti kebutuhan dan gaya hidup masyarakat masa kini, sehingga tidak hanya digunakan dalam konteks upacara adat, tetapi juga meresap ke berbagai aspek kehidupan sehari-hari sebagai simbol identitas, kehangatan, dan estetika. Di luar fungsinya sebagai bagian dari ritus adat seperti mangulosi (pemberian ulos sebagai tanda restu atau kasih sayang), ulos ini kini banyak dikenakan sebagai pelengkap busana modern—dijadikan selendang, scarf, kain pinggang, bahkan diolah menjadi jaket, tas, dan gaun etnik kontemporer yang populer di kalangan desainer lokal. Di lingkungan rumah tangga, ulos Pinucaan Modern sering dijadikan elemen dekoratif seperti taplak meja, hiasan dinding, sarung bantal, atau lembaran kain penghias ruang tamu yang menambah nuansa hangat dan berbudaya dalam interior. Dalam konteks sosial, ulos ini juga sering diberikan sebagai buah tangan atau hadiah istimewa dalam acara ulang tahun, syukuran, perpisahan, atau penghargaan kerja, karena membawa makna simbolis tentang harapan baik, kekuatan, dan penghormatan terhadap penerimanya. Bahkan dalam dunia usaha, ulos Pinucaan Modern kerap dipakai sebagai seragam formal atau aksesoris resmi dalam pertemuan dan seminar, khususnya di wilayah-wilayah yang menjunjung tinggi nilai kultural. Nilai fungsional dan estetis yang dimiliki ulos ini membuatnya tidak lagi hanya menjadi milik masyarakat Batak, tetapi telah diadopsi lebih luas sebagai bagian dari ekspresi keberagaman budaya Indonesia yang bisa hadir di panggung nasional maupun internasional—sebagai pakaian, karya seni, dan simbol kebanggaan etnik yang dinamis.', '', '3. Rumus Dasar & Desain Motif\r\n    Jumlah benang lungsi = lebar ulos (cm) × 10\r\n    (Contoh: 85 cm × 10 = 850 helai benang lungsi)\r\n    Warna utama: Hitam dan putih, dengan penekanan kontras tinggi yang melambangkan keseimbangan dan dualitas.\r\n    Susunan benang lungsi:\r\n    850 helai benang: 700 helai hitam sebagai dasar\r\n    Setiap 50 helai disisipkan 1 helai benang putih untuk menciptakan pola vertikal yang teratur dan elegan\r\n    Panjang benang per helai:\r\n    Panjang kain (240 cm) + cadangan mesin (30 cm × 2) = 300 cm (3 meter)\r\n\r\n4. Proses Winding – Penyusunan Benang Lungsi\r\n    Ukur panjang benang lungsi: 3 meter per helai menggunakan mesin winding presisi.\r\n    Siapkan 700 helai benang hitam sebagai dasar.\r\n    Sisipkan benang putih pada interval:\r\n    Helai ke-51, 102, 153, dst. hingga helai ke-850\r\n    Susunan pola dibuat berulang untuk membentuk kesan vertikal bergaris putih di antara dominasi warna hitam.\r\n    Semua benang digulung dan diatur ke spool winding agar tetap konsisten saat dipasang ke alat tenun.\r\n\r\n5. Warping – Penataan Benang ke Mesin Tenun\r\n    Masukkan semua 850 helai benang ke dalam reed (sisorhon) dengan 10 helai per rongga → total 85 rongga.\r\n    Benang diarahkan ke torop, menjaga jalur silang untuk memungkinkan gerakan naik-turun dalam proses tenun.\r\n    Susunan pola disesuaikan dengan rancangan digital agar posisi garis putih tetap teratur dan proporsional di seluruh bidang kain.\r\n    Benang diikat ke gulungan depan dan belakang alat tenun, siap untuk proses tenun.\r\n\r\n6. Proses Tenun (Digital Weaving)\r\n    Gunakan alat tenun semi-digital (Jacquard/Dobby) untuk presisi tinggi.\r\n    Benang pakan utama: putih, ditenun secara horizontal dari kanan ke kiri.\r\n    Setiap 70 sisipan, disisipkan 2 baris benang hitam sebagai aksen horizontal.\r\n    Pola hitam-putih ini menciptakan motif geometris kotak-kotak kecil atau jalur menyilang yang mencerminkan corak khas Pinucaan modern, tetapi dalam nuansa monokrom \r\n    elegan.\r\n    Tenunan dilanjutkan hingga panjang 240 cm, dengan total waktu pengerjaan ±8 jam.\r\n\r\n7. Finishing Mekanis\r\n    Setelah panjang tercapai, kain dipotong dari mesin secara otomatis.\r\n    Ujung-ujung kain dijahit dengan jahitan overdeck industri agar tidak terurai.\r\n    Tepi kain dirapikan menggunakan pemotong laser untuk hasil simetris dan rapi.\r\n    Pinggiran ulos disisir dan dibersihkan dari serat-serat halus.\r\n\r\n8. Pagolong – Pengeringan & Penyelesaian Akhir\r\n    Kain dikeringkan dalam ruang bertekanan rendah (40°C) selama ±3 jam untuk menghilangkan kelembaban dari proses tenun.\r\n    Disetrika menggunakan setrika uap industri agar tekstur kain lebih halus dan motif terlihat jelas.\r\n    Kain dilipat tiga secara memanjang, menyesuaikan cara tradisional penyimpanan ulos, lalu dibungkus untuk distribusi atau penjualan.', NULL, NULL, '250', '70', 'Ulos Pinucaan adalah salah satu jenis ulos tradisional dari suku Batak Toba, yang berasal dari wilayah Sumatera Utara. Nama Pinucaan berasal dari kata Batak \"pucah,\" yang berarti membuka atau terbuka, yang menggambarkan makna ulos ini dalam berbagai upacara adat Batak, terutama dalam upacara yang menandai transisi penting dalam kehidupan, seperti pernikahan, kelahiran, atau kematian. Ulos ini digunakan sebagai simbol dari peralihan, keberkahan, dan hubungan dengan leluhur serta alam semesta.\r\n\r\nSejarah pembuatan Ulos Pinucaan dimulai sejak zaman nenek moyang, di mana ulos ini ditenun dengan menggunakan alat tenun tradisional yang sederhana, secara manual oleh para perempuan Batak. Biasanya, bahan yang digunakan untuk membuat ulos ini adalah serat alami seperti kapas atau benang alami lainnya yang diolah dan dipintal dengan tangan. Proses pembuatan ulos ini sangat memakan waktu dan tenaga, dan setiap ulos memiliki pola yang kaya akan simbolisme, menggambarkan kehidupan, harapan, dan doa kepada Tuhan dan leluhur.\r\n\r\nMotif pada Ulos Pinucaan biasanya berupa garis horizontal dan pola geometris, yang melambangkan perjalanan hidup dan harmoni antara manusia dengan dunia spiritual dan alam. Pola ini juga mencerminkan rasa keseimbangan dalam kehidupan, di mana garis-garis dan bentuk-bentuk tersebut diatur sedemikian rupa untuk menciptakan kesan keteraturan dan keharmonisan.\r\n\r\nSeiring berjalannya waktu, pembuatan Ulos Pinucaan telah mengalami perubahan, terutama dalam hal bahan dan teknik produksi. Pada masa kini, selain menggunakan bahan tradisional seperti kapas, ulos ini juga mulai dibuat dengan bahan yang lebih modern dan teknik tenun semi-otomatik menggunakan mesin Jacquard. Meskipun teknologi telah maju, pola dan makna dari Ulos Pinucaan tetap dijaga, baik dalam pembuatan maupun dalam penggunaannya dalam kehidupan masyarakat Batak.', 'Modern'),
('P0011', NULL, 'Ulos Lobu Lobu', 'lobu.jpg', 'Ulos Lobu-Lobu adalah salah satu jenis ulos tradisional dari suku Batak yang memiliki makna dan fungsi khusus. Nama \"Lobu-Lobu\" sendiri berasal dari kata \"lobu\" yang berarti \"masuk\", sehingga ulos ini sering disebut sebagai ulos yang membawa hal-hal baik masuk ke dalam rumah pemakainya. Ulos ini memiliki bentuk seperti kain sarung, dengan rambu (fringe) yang tidak boleh dipotong, melambangkan kesatuan dan keberlanjutan.\r\n\r\nFungsi utama dari Ulos Lobu-Lobu adalah sebagai simbol perlindungan dan harapan. Ulos ini biasanya diberikan kepada individu atau keluarga yang sering mengalami kemalangan, seperti kehilangan anak atau anggota keluarga lainnya. Pemberian ulos ini bertujuan untuk memberikan kekuatan dan harapan agar mereka terhindar dari musibah dan mendapatkan keberuntungan di masa depan. Oleh karena itu, ulos ini tidak diperjualbelikan secara umum dan hanya dipesan langsung oleh mereka yang memerlukannya, menjadikannya sangat khusus dan sakral.\r\n\r\nSelain itu, Ulos Lobu-Lobu juga memiliki peran penting dalam upacara adat Batak. Ulos ini sering digunakan dalam acara pemberian ulos (mangulosi), sebagai simbol kasih sayang dan doa restu dari orang tua atau keluarga kepada individu yang bersangkutan. Dalam konteks ini, ulos ini menjadi media untuk menyampaikan harapan dan doa agar individu tersebut dilindungi dan diberikan kebahagiaan.\r\n\r\nKeunikan lain dari Ulos Lobu-Lobu adalah proses pembuatannya yang memerlukan keterampilan tinggi. Ulos ini ditenun secara manual menggunakan alat tenun tradisional, dengan motif dan pola yang khas. Proses pembuatan yang rumit dan memakan waktu ini menambah nilai spiritual dan budaya dari ulos ini, menjadikannya lebih dari sekadar kain, tetapi juga sebagai simbol dari nilai-nilai luhur masyarakat Batak.\r\n\r\nDalam kehidupan sehari-hari, meskipun tidak digunakan secara rutin, keberadaan Ulos Lobu-Lobu tetap dihormati dan dijaga. Ulos ini sering disimpan sebagai warisan keluarga, diturunkan dari generasi ke generasi sebagai simbol identitas dan budaya Batak. Keberadaannya menjadi pengingat akan pentingnya nilai-nilai kekeluargaan, harapan, dan doa dalam kehidupan masyarakat Batak.', '', '3. Rumus Pembuatan Ulos Lobu-Lobu Tradisional\r\n    1. Jumlah Benang Lungsi\r\n    Jumlah Benang Lungsi\r\n     =\r\n     Lebar Ulos (cm) × 10\r\n    Jumlah Benang Lungsi=Lebar Ulos (cm)×10\r\n    Misalnya, jika lebar ulos adalah 50 cm, maka jumlah benang lungsi yang dibutuhkan adalah:\r\n    50cm ×10=500\r\n    helai benang\r\n   50cm×10=500helai benang\r\n\r\n   2. Susunan Motif Ulos Lobu-Lobu\r\n    Motif pada Ulos Lobu-Lobu Tradisional lebih sederhana dan lebih mengutamakan pola garis atau strip warna hitam dan putih dengan sedikit aksen merah. Berikut contoh \r\n    susunan motif yang digunakan:\r\n    Motif Tengah: 1 putih + 2 hitam + 1 putih (motif tengah)\r\n    Motif Sisi: 1 putih + 2 hitam + 1 putih (motif sisi kiri dan kanan)\r\n\r\n    3. Susunan Warna Benang Lungsi\r\n    Susunan benang lungsi pada Ulos Lobu-Lobu tradisional adalah sebagai berikut:\r\n    300 helai hitam: benang utama (warna dominan)\r\n   1 putih + 2 hitam + 1 putih: pola motif tengah\r\n   300 helai hitam: benang utama untuk bagian lainnya\r\n   1 putih + 2 hitam + 1 putih: pola motif sisi kiri dan kanan\r\n   300 helai hitam: untuk sisi bagian akhir\r\n\r\n    4. Panjang Tiap Benang\r\n    Panjang Tiap Benang\r\n    =\r\n    Panjang Kain + Sisa Pemasangan\r\n    Panjang Tiap Benang=Panjang Kain+Sisa Pemasangan\r\n    Misalnya, panjang kain yang diinginkan adalah 200 cm, dan sisa pemasangan adalah 50 cm untuk mengatur ketegangan benang, maka panjang tiap benang adalah:\r\n    Panjang Tiap Benang\r\n    = 200cm+(50cm×2)=300cm\r\n    = 3 meter\r\n    Panjang Tiap Benang=200cm+(50cm×2)=300cm=3meter\r\n\r\n4. Panghintaman – Menyusun Benang Lungsi\r\n    Mengukur Panjang Benang Lungsi:\r\n    Setiap helai benang lungsi diukur dengan panjang 3 meter (300 cm).\r\n    Dibutuhkan sekitar 500 hingga 700 helai benang tergantung pada ukuran ulos yang diinginkan.\r\n    Menyusun Warna Benang:\r\n    300 helai hitam digunakan untuk bagian utama benang lungsi.\r\n    Motif putih dan hitam disisipkan secara bergantian pada posisi tengah dan sisi ulos, dengan pola 1 putih + 2 hitam + 1 putih pada bagian tengah dan sisi.\r\n    Menggulung Benang:\r\n    Semua benang disusun rapi dan digulung dalam urutan yang telah ditentukan.\r\n\r\n5. Mangalehon – Memasang Benang ke Alat Tenun\r\n    Memasukkan Benang ke Sisorhon:\r\n    Benang lungsi dimasukkan ke dalam sisorhon (sisir tenun), dengan 10 helai per rongga (tergantung jumlah rongga dalam alat tenun).\r\n    Mengatur Benang di Torop:\r\n    Benang lungsi diatur dan diposisikan dengan benar di torop (alat pembagi jalur atas-bawah) untuk memastikan ketegangan benang yang merata.\r\n    Memeriksa Urutan Warna:\r\n    Pastikan posisi motif 1 putih + 2 hitam + 1 putih berada di posisi yang benar, baik di bagian tengah maupun sisi kiri dan kanan.\r\n\r\n6. Mangtenun – Proses Menenun\r\n    Posisi Duduk di Alat Tenun:\r\n    Penenun duduk di depan gedogan (alat tenun tradisional Batak) dan mulai menginjak pedal untuk membuka benang lungsi.\r\n    Menyiapkan Benang Pakan:\r\n    Benang pakan berwarna hitam dimasukkan dari kanan ke kiri menggunakan sekoci, dan kemudian dipukul dengan baliga untuk menekan benang agar rapat.\r\n    Menyisipkan Motif:\r\n    Setiap 50 baris benang pakan, sisipkan motif warna:\r\n    1 putih + 2 hitam + 1 putih pada bagian tengah dan sisi ulos.\r\n    Proses menenun dilakukan hingga mencapai panjang 200 cm untuk kain yang efektif.\r\n    Melanjutkan Proses Menenun:\r\n    Menenun dilanjutkan hingga panjang kain tercapai, dengan waktu pengerjaan yang dapat bervariasi antara 2 hingga 3 hari kerja, tergantung kecepatan penenun.\r\n\r\n6. Pangurung – Menyelesaikan Tenunan\r\n    Mengikat dan Memotong Benang:\r\n    Setelah mencapai panjang 200 cm, ikat benang dengan rapat dan potong benang dari alat tenun.\r\n    Finishing Pinggiran Kain:\r\n    Ulos Lobu-Lobu biasanya memiliki pinggiran yang dijahit tangan secara manual untuk mencegah benang terurai.\r\n\r\n7. Pagolong – Finishing dan Penyelesaian\r\n    Menjemur Kain:\r\n    Setelah selesai menenun, ulos dijemur di tempat yang teduh selama 6 jam agar tidak terpapar sinar matahari langsung.\r\n    Setrika dan Lipat:\r\n    Setelah kering, ulos disetrika dengan suhu sedang untuk merapikan kain dan memberi tampilan yang halus.\r\n    Lipat ulos menjadi tiga bagian panjang, sesuai dengan tradisi penyimpanan ulos Batak.', NULL, NULL, '240', '70', 'Ulos Lobu-Lobu adalah salah satu jenis ulos Batak yang memiliki nilai adat dan spiritual tinggi. Secara tradisional, ulos ini berasal dari daerah Tapanuli, khususnya di wilayah Batak Toba. Kata \"lobu-lobu\" dalam bahasa Batak dapat diartikan sebagai “berkelimpahan” atau “kesejahteraan”, dan makna ini erat kaitannya dengan tujuan penggunaannya dalam kehidupan masyarakat Batak.\r\n\r\nAsal usul Ulos Lobu-Lobu tidak terlepas dari sistem nilai dan kepercayaan orang Batak terhadap kekuatan simbolik ulos. Dahulu, ulos ini tidak sekadar kain penutup atau pelengkap pakaian, tetapi dianggap sebagai pemberi berkat, perlindungan, serta simbol doa dan harapan dari pemberi kepada penerima. Ulos Lobu-Lobu secara khusus digunakan dalam upacara adat, seperti pemberian kepada anak atau cucu yang baru menikah, atau pada saat kelahiran untuk menyampaikan harapan akan hidup yang makmur dan bahagia.\r\n\r\nMotifnya yang sederhana namun teratur mencerminkan filosofi hidup yang seimbang dan penuh kedamaian. Tidak seperti ulos yang bermotif rumit, Ulos Lobu-Lobu justru menekankan kesederhanaan dan keteguhan, yang mencerminkan harapan agar kehidupan si pemakai tetap lurus, penuh kesabaran, dan diberkati dari segala sisi.\r\n\r\nUlos ini diturunkan dari generasi ke generasi, dan proses pembuatannya selalu dilakukan dengan cara tradisional, menggunakan alat tenun bukan mesin (ATBM) dan pewarna alami. Hal ini memperlihatkan bahwa Ulos Lobu-Lobu adalah warisan budaya yang tidak hanya berwujud kain, tetapi juga mengandung nilai identitas, spiritualitas, dan filosofi hidup masyarakat Batak sejak zaman dahulu.', 'Tradisional'),
('P0012', NULL, 'Ulos Bintang Maratur', 'khagdf.jpg', 'Ulos Bintang Maratur merupakan salah satu jenis ulos tradisional Batak yang memiliki kedudukan istimewa dalam kehidupan masyarakat Batak. Ulos ini dikenal dengan motif \"bintang maratur\" yang menggambarkan pola bintang yang simetris dan teratur, mencerminkan keselarasan, harapan, dan kemakmuran dalam kehidupan. Motif bintang dalam ulos ini bukan hanya sekadar desain, tetapi juga memiliki makna simbolis yang mendalam. Bintang tersebut melambangkan harapan agar pemakai ulos ini dapat hidup dengan penuh kedamaian dan keberuntungan, serta mendapatkan berkah yang melimpah.\r\n\r\nUlos Bintang Maratur memiliki peran yang sangat penting dalam berbagai ritual adat Batak. Pada masa lalu, ulos ini sering digunakan dalam upacara adat seperti pemberian kepada anak cucu yang baru lahir, pada perayaan pernikahan, atau bahkan dalam acara kematian sebagai bentuk penghormatan kepada yang telah meninggal. Pada setiap upacara adat, pemberian ulos ini selalu diiringi dengan doa dan harapan agar kehidupan pemakainya diberkahi dan dilindungi.\r\n\r\nSelain sebagai simbol dalam acara adat, Ulos Bintang Maratur juga digunakan dalam kehidupan sehari-hari. Di masyarakat Batak, ulos ini dapat dikenakan pada acara-acara tertentu atau bahkan dalam pakaian sehari-hari sebagai bagian dari identitas budaya. Ulos Bintang Maratur modern sering digunakan oleh masyarakat Batak dalam berbagai acara penting seperti pesta pernikahan, upacara adat, dan acara keluarga lainnya. Tak hanya itu, ulos ini juga dapat digunakan untuk tujuan dekorasi atau bahkan dalam pembuatan barang-barang kerajinan tangan, seperti tas atau kain penutup meja, yang tetap menjaga nilai budaya.\r\n\r\nPenggunaan Ulos Bintang Maratur dalam Kehidupan Sehari-hari\r\n\r\nDalam kehidupan sehari-hari, Ulos Bintang Maratur modern sering dipakai dalam acara adat yang melibatkan keluarga besar Batak, seperti perayaan ulang tahun, pemberian kepada pasangan baru menikah, atau sebagai bagian dari upacara adat untuk menghormati leluhur. Selain itu, ulos ini juga digunakan oleh generasi muda Batak sebagai simbol kebanggaan budaya mereka, baik untuk melengkapi pakaian adat pada saat acara penting atau untuk menghadiri acara budaya dan seni tradisional Batak.', '', '3. Rumus Pembuatan Ulos Bintang Maratur Modern\r\n    Jumlah Benang Lungsi (Warp): Lebar ulos (cm) × 10\r\n    Susunan Motif Bintang Maratur: Motif bintang dengan lima titik (merah, putih, emas, biru, hijau), masing-masing motif berulang secara simetris di tengah dan dua sisi kain.\r\n    Susunan Warna Benang Lungsi:\r\n    800 helai benang hitam sebagai dasar (untuk memberikan latar belakang yang kuat)\r\n    Sisipan benang warna merah, putih, emas, biru, dan hijau, ditempatkan setiap ±100 helai untuk menciptakan pola bintang yang teratur\r\n    Panjang Tiap Benang: Panjang kain (200 cm) + cadangan pemasangan mesin (30 cm × 2)\r\n    Panjang Benang: 200 cm + 60 cm = 260 cm (2,6 meter)\r\n\r\n4. Digital Winding – Menyusun Benang Lungsi\r\n    Pengukuran panjang benang lungsi: Setiap benang dipotong sepanjang 2,6 meter menggunakan mesin winding otomatis untuk memastikan konsistensi dan efisiensi.\r\n    Siapkan 800 helai benang hitam yang akan digunakan sebagai dasar, dan susun benang warna berikut untuk motif bintang:\r\n    Helai ke-100: Benang merah\r\n    Helai ke-200: Benang putih\r\n    Helai ke-300: Benang emas\r\n    Helai ke-400: Benang biru\r\n    Helai ke-500: Benang hijau\r\n    Ulangi pola ini sepanjang 800 helai benang.\r\n    Benang-benang ini digulung menggunakan mesin winding digital agar pola tetap rapi dan seragam.\r\n\r\n5. Auto Warping – Memasang Benang ke Mesin Tenun\r\n   Memasukkan Benang ke Mesin Tenun: 800 helai benang lungsi dimasukkan ke dalam sisorhon (reed atau sisir tenun) menggunakan sistem warping otomatis. Proses ini \r\n   memastikan benang tertata rapi dengan jumlah yang tepat.\r\n   Pembagian Benang: Setiap rongga mesin akan memuat 10 helai benang, sehingga terdapat total 80 rongga yang siap dipasang.\r\n   Pengaturan Pola: Setelah benang dimasukkan, periksa sistem untuk memastikan motif bintang (berwarna merah, putih, emas, biru, dan hijau) tersebar merata dan simetris di \r\n   seluruh benang lungsi.\r\n\r\n6. Digital Weaving – Proses Menenun\r\n    Aktivasi Mesin Tenun Semi-Digital: Mesin tenun semi-digital (Jacquard atau Dobby) digunakan untuk menenun benang pakan.\r\n    Benang Pakan (Weft): Benang pakan utama (biasanya berwarna hitam) dimasukkan otomatis dari sisi kanan ke kiri oleh mesin tenun, sementara motif warna akan dimasukkan \r\n    secara bergantian sesuai pola.\r\n    Penempatan Motif: Setiap 50 sisipan benang pakan, benang motif bintang akan dimasukkan dalam urutan sebagai berikut:\r\n    2 sisipan benang merah\r\n    2 sisipan benang putih\r\n    2 sisipan benang emas\r\n    2 sisipan benang biru\r\n    2 sisipan benang hijau\r\n    Proses Menenun: Mesin secara otomatis menekan benang pakan untuk memastikan ketepatan dan kekuatan pada setiap baris tenunan. Proses ini dilanjutkan hingga panjang \r\n    kain mencapai 200 cm (total proses menenun memakan waktu ±8–10 jam).\r\n\r\n7. Finishing Mekanis – Menyelesaikan Tenunan\r\n    Setelah mencapai panjang 200 cm, mesin otomatis akan memotong benang dari alat tenun dengan presisi.\r\n    Jahitan Overlock: Bagian ujung kain diberi jahitan overlock secara otomatis untuk menghindari benang terurai.\r\n    Pemotongan Tepi: Pinggiran kain dirapikan menggunakan mesin pemotong tepi otomatis atau laser sealing untuk hasil yang halus dan rapi.\r\n\r\n8. Pagolong – Proses Finishing\r\n    Pengeringan: Kain dijemur di ruang pengering suhu rendah (±40°C) selama 2–3 jam untuk memastikan kain kering secara merata tanpa merusak serat.\r\n    Penyetrikaan: Setelah kering, kain disetrika menggunakan setrika uap industri (steam press) untuk merapikan dan menghaluskan permukaan kain.\r\n    Lipat Kain: Kain dilipat secara otomatis menjadi tiga bagian memanjang, sesuai dengan tradisi penyimpanan dan penataan ulos Bintang Maratur.', NULL, NULL, '215', '73', 'Selain sebagai penanda status sosial dan simbol harapan, Ulos Bintang Maratur juga memiliki peran penting dalam berbagai upacara adat Batak. Dalam upacara pernikahan, ulos ini sering diberikan kepada pengantin sebagai doa agar kehidupan rumah tangga mereka selalu tertata rapi, harmonis, dan penuh berkah. Sementara itu, dalam upacara kelahiran, ulos ini diberikan kepada bayi sebagai harapan agar ia tumbuh menjadi pribadi yang disiplin, beruntung, dan berbakti kepada keluarga.\r\n\r\nPada masa kolonial, perkembangan ulos sempat terhambat karena adanya pengaruh budaya Barat yang mulai masuk ke Tanah Batak. Namun, ulos tetap bertahan sebagai identitas budaya yang kuat, terutama di kalangan masyarakat Batak yang tinggal di pedesaan.\r\n\r\nMemasuki era modern, Ulos Bintang Maratur mulai mengalami transformasi dari segi desain dan penggunaan. Pengrajin ulos kini menggabungkan motif tradisional dengan pola kontemporer agar lebih menarik bagi generasi muda. Selain itu, ulos ini tidak lagi terbatas sebagai kain tenun untuk upacara adat, tetapi juga diolah menjadi produk fesyen seperti tas, syal, dompet, dan hiasan interior.\r\n\r\nPemerintah Sumatera Utara juga mendorong promosi ulos sebagai warisan budaya dunia melalui festival, pameran, dan sertifikasi produk ulos, termasuk Ulos Bintang Maratur. Hal ini bertujuan untuk meningkatkan nilai ekonomi ulos sekaligus menjaga kelestariannya agar tidak tergerus oleh modernisasi dan globalisasi.', 'Modern'),
('P0013', NULL, 'Ulos Suri-Suri Naganjang', 'hb.jpg', 'Ulos Suri-suri Naganjang adalah salah satu jenis ulos khas Batak yang dikenal karena bentuknya yang lebih panjang dari ulos pada umumnya serta motif garis-garis simetris yang elegan. Kata “suri-suri” merujuk pada motifnya yang khas, sementara “naganjang” berarti panjang, sehingga ulos ini secara harfiah berarti “ulos bermotif suri-suri yang panjang”. Ulos ini bukan sekadar kain tenun, tetapi mengandung makna filosofis yang mendalam dan memiliki fungsi penting dalam kehidupan masyarakat Batak, baik dalam adat maupun keseharian yang bermakna.\r\nDalam kehidupan sehari-hari, Ulos Suri-suri Naganjang digunakan dalam berbagai momen penting, terutama dalam acara adat. Saat pernikahan, ulos ini diberikan sebagai ulos restu (ulos pasu-pasu) dari orang tua kepada anak atau menantu, melambangkan kasih sayang dan harapan akan kebahagiaan rumah tangga. Dalam acara kelahiran, ulos ini digunakan untuk menyelimuti bayi sebagai simbol perlindungan dan doa agar sang anak tumbuh dalam berkat. Pada saat kematian, ulos ini dikenakan oleh keluarga dekat sebagai bentuk penghormatan terakhir dan simbol kekuatan dalam menghadapi duka. Ulos ini juga sering diberikan kepada orang-orang yang dihormati sebagai tanda kehormatan dan penghargaan dalam masyarakat Batak.\r\nSecara simbolis, ulos ini mencerminkan nilai kesabaran, ketekunan, dan harapan akan panjang umur serta keberkahan hidup. Karena makna-makna tersebut, ulos ini dianggap sakral dan sangat dijaga penggunaannya. Ulos Suri-suri Naganjang juga menggambarkan hubungan kasih antara orang tua dan anak, antara yang lebih tua dan yang lebih muda, serta ikatan kekeluargaan yang erat.', '', '3. Rumus\r\nJumlah benang lungsi (memanjang) = Lebar ulos (cm) × 10\r\nContoh: 95 cm × 10 = 950 helai benang lungsi\r\n\r\nSusunan motif Suri-suri Naganjang:\r\nMotif garis-garis sejajar dan rapi, didominasi warna hitam dan aksen merah serta putih dalam pola berulang.\r\n\r\nSusunan warna benang lungsi:\r\n\r\n250 helai hitam\r\n\r\n1 putih – 3 merah – 1 putih (motif tengah)\r\n\r\n200 helai hitam\r\n\r\n1 putih – 3 merah – 1 putih (motif sisi kiri)\r\n\r\n50 helai hitam\r\n\r\n1 putih – 3 merah – 1 putih (motif sisi kanan)\r\n\r\n250 helai hitam\r\n\r\nPanjang tiap benang = Panjang kain (400 cm) + sisa pemasangan (50 cm × 2)\r\n= 400 cm + 100 cm = 500 cm (5 meter per helai)\r\n\r\n4. Panghintaman – Menyusun Benang Lungsi\r\nUkur panjang benang lungsi: 5 meter per helai\r\n\r\n950 helai benang total (mayoritas hitam)\r\n\r\nDi helai ke-250–255 → 1 putih – 3 merah – 1 putih (motif tengah)\r\n\r\nDi helai ke-100–105 dan 845–850 → pola yang sama (motif sisi kiri & kanan)\r\n\r\nGulung semua benang ke turak (penggulung), urut dan rapi\r\n\r\n5. Mangalehon – Memasang Benang ke Alat Tenun\r\nMasukkan 950 helai benang ke sisorhon (sisir tenun), 10 helai per rongga → 95 rongga\r\n\r\nMasukkan ke torop sesuai pola silang\r\n\r\nIkat bagian belakang ke penggulung belakang, depan ke pemberat depan\r\n\r\nCek ulang posisi tiga motif suri-suri (tengah dan dua sisi)\r\n\r\n6. Mangtenun – Proses Menenun\r\nDuduk di alat tenun gedogan, injak pedal kanan-kiri bergantian\r\n\r\nMasukkan benang pakan warna hitam dari kanan ke kiri menggunakan sekoci\r\n\r\nSetiap 40 sisipan pakan, selipkan pola motif:\r\n\r\n3 benang merah\r\n\r\n1 benang putih\r\n\r\nDiterapkan di tengah dan dua sisi kain\r\n\r\nPola ini diulang sepanjang kain, menjaga jarak antar garis agar merata\r\n\r\nLanjutkan hingga panjang 400 cm (efektif)\r\n\r\nWaktu pengerjaan: ±3–5 hari tergantung kecepatan\r\n\r\nTekan benang dengan baliga agar rapat, motif tidak bergeser\r\n\r\n7. Pangurung – Menyelesaikan Tenunan\r\nSetelah panjang 400 cm tercapai, potong dan ikat benang dari alat tenun\r\n\r\nBuat simpul di ujung-ujung benang agar tidak terlepas\r\n\r\nRapikan tepi kain secara manual (dijahit tangan)\r\n\r\n8. Pagolong – Finishing\r\nJemur kain di tempat teduh dan angin-anginkan selama ±6–8 jam\r\n\r\nSetrika dengan suhu sedang, hindari lipatan motif\r\n\r\nLipat kain menjadi tiga bagian memanjang, sesuai adat penyimpanan ulos panjang\r\n\r\nSimpan di tempat kering, jangan dilipat sembarangan untuk menjaga bentuk dan motif', NULL, NULL, '350', '90', 'Sejarah Ulos Suri-suri Naganjang tidak terlepas dari sejarah panjang peradaban Batak itu sendiri. Suku Batak, yang mendiami wilayah pegunungan Tapanuli di Sumatera Utara, sudah sejak ratusan tahun lalu mengenal teknik menenun (martonun) sebagai bagian penting dari budaya mereka. Kegiatan menenun ini umumnya dilakukan oleh perempuan, yang belajar dari generasi ke generasi dalam lingkungan keluarga.\r\n\r\nAwalnya, ulos ditenun sebagai kebutuhan dasar untuk menghangatkan tubuh di daerah pegunungan yang dingin. Namun seiring waktu, kain ini berkembang menjadi simbol budaya, identitas, dan spiritualitas. Ulos Suri-suri Naganjang secara khusus diyakini berkembang di wilayah Balige dan Laguboti, kawasan di sekitar Danau Toba yang menjadi pusat peradaban Batak Toba kuno. Di masa lampau, hanya keluarga bangsawan atau tokoh adat terkemuka yang memiliki atau memakai ulos ini, karena panjang dan kompleksitas motifnya mencerminkan status sosial yang tinggi.\r\n\r\nMenurut kepercayaan adat Batak, ulos bukan sekadar kain, melainkan penyambung berkat dari leluhur, dan berfungsi sebagai pelindung spiritual. Dalam hal ini, Ulos Suri-suri Naganjang dipercaya membawa berkat yang panjang, lestari, dan penuh kehormatan, cocok diberikan kepada seseorang yang hendak menempuh fase penting dalam hidupnya, seperti pernikahan atau kelahiran.\r\n\r\nPara penenun dahulu menenun ulos ini secara manual dengan alat tradisional, dan memakan waktu hingga berminggu-minggu untuk satu helai ulos, tergantung tingkat kerumitan motif. Karena itu pula, ulos ini termasuk dalam kategori ulos yang \"mahal\", baik secara harga maupun nilai simbolis.\r\n\r\nSelain itu, masyarakat Batak percaya bahwa motif suri-suri mencerminkan ketekunan dan kedisiplinan hidup, karena garis-garis yang terbentuk harus sangat rapi, presisi, dan konsisten. Kesalahan sedikit saja dalam pola, diyakini dapat mengganggu keharmonisan makna ulos tersebut.\r\n\r\nDalam beberapa cerita lisan, Ulos Suri-suri Naganjang juga disebut sebagai bagian dari ulos yang diberikan oleh para leluhur kepada anak cucunya yang akan merantau, sebagai lambang doa agar perjalanan dan kehidupan mereka selalu panjang, terang, dan penuh restu dari para leluhur.', 'Tradisional'),
('P0014', NULL, 'Ulos Mangiring', 'mnm.jpg', 'Ulos Mangiring merupakan salah satu jenis kain tenun tradisional Batak Toba yang memiliki ciri khas motif garis-garis vertikal (mangiring) dengan pola warna dominan hitam, merah, dan putih yang tersusun secara berulang dan simetris. Dalam budaya Batak, ulos ini mengandung makna filosofis yang mendalam sebagai simbol kesinambungan hidup, perlindungan spiritual, dan harapan akan keberkahan. Motif mangiring yang berupa garis lurus dari atas ke bawah melambangkan kesatuan dan kelanggengan hubungan antar generasi dalam keluarga Batak. Warna hitam melambangkan keteguhan, merah menyimbolkan keberanian dan kehidupan, sedangkan putih merepresentasikan kesucian dan kebenaran.\r\n\r\nSecara tradisional, proses pembuatan Ulos Mangiring dilakukan secara manual menggunakan alat tenun bukan mesin (ATBM) dengan teknik tenun yang rumit dan membutuhkan ketelitian tinggi. Para penenun ahli biasanya memerlukan waktu 2 hingga 4 minggu untuk menyelesaikan satu lembar Ulos Mangiring asli, tergantung pada kerumitan motif dan ukuran kain. Bahan benang yang digunakan umumnya terbuat dari kapas alami yang diwarnai dengan pewarna tradisional dari tumbuhan, memberikan ciri khas warna yang lebih natural dan tahan lama.\r\n\r\nDalam kehidupan sehari-hari masyarakat Batak, Ulos Mangiring memiliki peran multi-fungsi yang sangat penting. Pada upacara kelahiran, ulos ini digunakan sebagai kain gendong bayi (parompa) yang dipercaya dapat memberikan perlindungan spiritual kepada sang bayi. Dalam prosesi pernikahan adat Batak, Ulos Mangiring sering dijadikan sebagai ulos hela, yaitu kain berkat yang diberikan orang tua kepada mempelai sebagai simbol restu dan harapan untuk kehidupan rumah tangga yang langgeng. Sementara dalam upacara kematian, ulos ini berfungsi sebagai kain penutup jenazah (tungkup) atau dikenakan sebagai selendang duka cita oleh keluarga yang berduka.', '', '3. Rumus\r\nJumlah benang lungsi = Lebar ulos (cm) × 10\r\n(Misal lebar 90 cm → 900 helai benang lungsi)\r\n\r\nSusunan motif Ulos Mengiring modern = Kombinasi garis dan titik-titik warna putih, ungu, dan biru keabu-abuan secara vertikal dan horizontal.\r\n\r\nSusunan warna benang lungsi:\r\n\r\n900 helai benang dasar hitam pekat.\r\n\r\nSisipan benang putih, ungu, dan biru keabu-abuan disisipkan setiap ±90 helai untuk menciptakan pola khas Ulos Mengiring.\r\n\r\nPanjang tiap benang lungsi = 200 cm (kain efektif) + (2 × 30 cm) cadangan mesin = 260 cm (2,6 meter).\r\n\r\n4. Digital Winding – Menyusun Benang Lungsi\r\nUkur panjang setiap helai benang lungsi: 2,6 meter menggunakan mesin winding otomatis.\r\n\r\nSiapkan 900 helai benang hitam pekat sebagai dasar.\r\n\r\nSisipkan warna pada urutan helai sebagai berikut:\r\n\r\nHelai ke-90: putih\r\n\r\nHelai ke-180: ungu\r\n\r\nHelai ke-270: biru keabu-abuan\r\n\r\nUlangi pola hingga helai ke-900.\r\n\r\nSemua benang digulung secara otomatis ke spool digital, urutan tetap sesuai pola Mengiring.\r\n\r\n5. Auto Warping – Pemasangan Benang ke Mesin Tenun\r\nPasang satu per satu 900 helai benang ke dalam sisorhon (reed) otomatis.\r\n\r\n10 helai per rongga → 90 rongga total.\r\n\r\nBenang dimasukkan ke torop (pembagi jalur atas-bawah) berdasarkan pola silang digital.\r\n\r\nIkat ke gulungan depan dan belakang mesin tenun.\r\n\r\nSistem digital memverifikasi distribusi warna untuk memastikan keseimbangan dan simetri pola vertikal Ulos Mengiring.\r\n\r\n6. Digital Weaving – Proses Menenun\r\nAktifkan mesin tenun semi-digital (Jacquard atau Dobby).\r\n\r\nGunakan benang pakan dasar: hitam pekat.\r\n\r\nSetiap 50 sisipan benang pakan, masukkan motif horizontal sebagai berikut:\r\n\r\n1 sisipan benang putih\r\n\r\n1 sisipan benang ungu\r\n\r\n1 sisipan benang biru keabu-abuan\r\n\r\nMotif ditenun berulang secara berkala untuk menghasilkan corak khas Ulos Mengiring modern.\r\n\r\nProses menenun dilanjutkan hingga mencapai 200 cm kain efektif (±10 jam kerja).\r\n\r\nTekanan dan rapatan benang dijaga otomatis untuk hasil akhir yang padat dan simetris.\r\n\r\n7. Finishing Mekanis – Penyelesaian Kain\r\nSetelah panjang tercapai, mesin otomatis memotong kain dari alat tenun.\r\n\r\nUjung kain dijahit menggunakan overlock industri.\r\n\r\nSisi-sisi kain dipotong rapi menggunakan laser sealing atau alat pemotong mekanis.\r\n\r\n8. Pagolong – Finishing Akhir\r\nKain dijemur di ruang pengering suhu rendah (±40°C) selama 2–3 jam.\r\n\r\nDisetrika menggunakan steam press industri agar permukaan kain halus.\r\n\r\nKain dilipat tiga bagian memanjang, sesuai tradisi penyimpanan Ulos Mengiring.', NULL, NULL, '200', '90', 'Ulos Mangiring modern merupakan hasil transformasi dari warisan tenun tradisional Batak Toba yang mengalami modernisasi sejak akhir abad ke-20. Berawal dari Ulos Mangiring klasik yang dibuat secara manual menggunakan benang kapas dan pewarna alami dengan motif garis-garis vertikal simbolis, perkembangan zaman membawa perubahan signifikan dalam teknik produksinya. Pada dekade 1990-an, para pengrajin mulai mengadopsi bahan sintetis seperti benang polyester dan katun campuran yang lebih tahan lama serta pewarna kimia yang stabil, sambil tetap mempertahankan pola garis vertikal khas yang melambangkan kesinambungan hidup. Era 2000-an menandai babak baru ketika mesin tenun semi-otomatis diperkenalkan, memangkas waktu produksi dari sebelumnya satu bulan menjadi hanya 1-2 minggu, sekaligus memperluas fungsi ulos ini dari sekadar busana adat menjadi bagian dari fashion modern seperti syal, dasi, dan aksesori interior. Inovasi desain pun muncul dengan variasi warna yang lebih beragam dan motif yang lebih dinamis, meskipun warna tradisional hitam (kekuatan), merah (kehidupan), dan putih (kesucian) tetap menjadi pilihan utama. Transformasi ini tidak mengurangi makna filosofis ulos sebagai simbol perlindungan dan pengharapan, melainkan justru memperluas jangkauan pemakainya, menjadikan Ulos Mangiring modern sebagai perpaduan harmonis antara nilai-nilai luhur budaya Batak dengan tuntutan gaya hidup kontemporer, sekaligus bukti nyata kemampuan adaptasi warisan budaya dalam menghadapi perubahan zaman.', 'Modern'),
('P0015', NULL, 'Ulos Antak-Antak', 'hbd.jpg', 'Ulos Antak-Antak merupakan mahakarya tekstil tradisional Batak Toba yang menempati posisi istimewa dalam khazanah budaya masyarakat Batak. Kain tenun ini secara visual dikenali dari motif geometrisnya yang unik berupa pola kotak-kotak kecil yang tersusun rapat dan berulang, menciptakan kesan dinamis namun tetap harmonis. Motif \"antak-antak\" yang menjadi ciri khasnya ini tidak sekadar ornamen dekoratif, melainkan merupakan visualisasi dari falsafah hidup orang Batak yang menjunjung keteraturan, ketekunan, dan kesinambungan.\r\n\r\nDari segi warna, Ulos Antak-Antak tradisional memiliki palet warna yang khas dan sarat makna. Warna hitam yang dominan melambangkan keteguhan dan kekuatan, merah menyimbolkan keberanian dan vitalitas kehidupan, sedangkan putih merepresentasikan kesucian dan kebenaran. Pada beberapa varian, terdapat tambahan warna biru yang melambangkan kedamaian dan kesejukan. Kombinasi warna-warna ini tidak dipilih secara acak, melainkan melalui pertimbangan filosofis yang mendalam.\r\n\r\nDalam konteks teknik tenun, Ulos Antak-Antak dibuat dengan metode yang sangat rumit dan membutuhkan keterampilan tinggi. Proses pembuatannya menggunakan alat tenun bukan mesin (ATBM) tradisional dengan teknik tenun ikat yang presisi. Seorang penenun ahli biasanya membutuhkan waktu 4-8 minggu untuk menyelesaikan satu lembar Ulos Antak-Antak berkualitas tinggi, tergantung pada kerumitan motif dan ukuran kain. Benang yang digunakan umumnya terbuat dari kapas alami yang diwarnai dengan pewarna tradisional dari bahan-bahan alam, memberikan karakter warna yang khas dan tahan lama.\r\n\r\nDalam kehidupan masyarakat Batak Toba, Ulos Antak-Antak memiliki fungsi yang sangat beragam dan penting. Pada upacara pernikahan adat, kain ini sering difungsikan sebagai \"ulos hobbang\" atau kain persembahan yang diberikan keluarga mempelai wanita kepada mempelai pria, melambangkan ikatan yang kuat dan harapan akan kehidupan rumah tangga yang harmonis. Dalam tradisi kelahiran, Ulos Antak-Antak digunakan sebagai kain gendong bayi yang diyakini memberikan kehangatan fisik sekaligus perlindungan spiritual. Sementara dalam upacara kematian, kain ini berperan sebagai penutup jenazah atau selendang duka yang dikenakan keluarga sebagai bentuk penghormatan terakhir.', '', '3. Rumus\r\nJumlah benang lungsi = Lebar ulos (cm) × 10\r\n\r\nSusunan motif Antak Antak = 2 benang biru tua + 1 benang putih + 2 benang biru tua (3 posisi: tengah & dua sisi)\r\n\r\nSusunan warna benang lungsi:\r\n\r\n280 helai hitam\r\n\r\n2 biru tua + 1 putih + 2 biru tua (motif tengah)\r\n\r\n270 helai hitam\r\n\r\n2 biru tua + 1 putih + 2 biru tua (motif sisi kiri)\r\n\r\n280 helai hitam\r\n\r\nPanjang tiap benang = Panjang kain (220 cm) + sisa pemasangan (40 cm × 2)\r\n→ Panjang = 220 + 80 = 300 cm (3 meter)\r\n\r\n4. Panghintaman – Menyusun Benang Lungsi\r\nUkur panjang benang lungsi: 3 meter per helai\r\n\r\nTotal 900 helai benang hitam\r\n\r\nDi helai ke-280 hingga 285:\r\n\r\n2 biru tua – 1 putih – 2 biru tua (motif tengah)\r\n\r\nDi helai ke-90–95 dan 815–820:\r\n\r\n2 biru tua – 1 putih – 2 biru tua (motif sisi)\r\n\r\nGulung semua benang ke turak dalam susunan tetap dan rapi\r\n\r\n5. Mangalehon – Memasang Benang ke Alat Tenun\r\nMasukkan 900 helai benang ke sisorhon (10 helai per rongga → 90 rongga total)\r\n\r\nMasukkan benang ke torop sesuai urutan silang (naik-turun)\r\n\r\nIkat bagian belakang ke penggulung belakang, dan bagian depan ke pemberat\r\n\r\nPastikan susunan motif Antak Antak berada tepat di tengah dan dua sisi\r\n\r\n6. Mangtenun – Proses Menenun\r\nDuduk di ATBM (alat tenun bukan mesin), injak pedal bergantian untuk buka lungsi\r\n\r\nMasukkan benang pakan (biru tua/hitam) dari kanan ke kiri pakai sekoci\r\n\r\nSetiap 60 sisipan benang pakan, selipkan motif warna:\r\n\r\n2 kali benang biru tua\r\n\r\n1 kali benang putih\r\n\r\n2 kali benang biru tua\r\n\r\nLakukan di tengah dan dua sisi kain\r\n\r\nLanjutkan proses hingga mencapai panjang 220 cm\r\n\r\nTekan setiap baris motif dengan baliga agar rapat dan tidak bergeser\r\n\r\n7. Pangurung – Menyelesaikan Tenunan\r\nSetelah panjang tercapai, potong dan ikat benang dari alat tenun\r\n\r\nBuat simpul pada ujung benang agar tidak lepas\r\n\r\nRapikan pinggiran dengan jarum tangan atau dijahit rapi\r\n\r\n8. Pagolong – Finishing\r\nJemur ulos di tempat teduh selama 5–6 jam\r\n\r\nSetrika dengan suhu sedang\r\n\r\nLipat ulos menjadi tiga bagian memanjang, sesuai tradisi penyimpanan ulos Antak Antak', NULL, NULL, '200', '80', 'Ulos Antak-Antak tradisional merupakan salah satu warisan tenun tertua masyarakat Batak Toba yang diperkirakan telah ada sejak abad ke-16 di wilayah sekitar Danau Toba. Kain ini dinamai \"Antak-Antak\" karena motif kotak-kotak kecilnya yang saling bertaut rapat, menyerupai anyaman jala, dimana setiap kotak melambangkan ikatan kekeluargaan dan persatuan dalam masyarakat Batak. Pada masa lalu, ulos ini memiliki fungsi sakral dalam berbagai upacara penting seperti pernikahan, pengukuhan pemimpin adat, dan ritual kematian, karena dipercaya mengandung kekuatan spiritual yang mampu menghubungkan dunia nyata dengan alam roh leluhur. Warna tradisionalnya yang terdiri dari hitam (dari pewarna kulit kayu lobung), merah (dari akar mengkudu), dan putih (dari kapur) masing-masing menyimbolkan kekuatan, keberanian, dan kesucian. Proses pembuatannya yang rumit membutuhkan keterampilan tinggi, dimana para penenun tradisional menggunakan alat tenun bukan mesin (ATBM) dan memerlukan waktu 1-2 bulan untuk menyelesaikan satu lembar ulos dengan motif yang sempurna. Meskipun telah mengalami beberapa adaptasi teknik dan bahan seiring perkembangan zaman, Ulos Antak-Antak tradisional tetap mempertahankan makna filosofisnya sebagai simbol persatuan dan perlindungan dalam budaya Batak, serta terus digunakan dalam berbagai upacara adat penting sebagai wujud penghormatan terhadap warisan leluhur.', 'Tradisional'),
('P0016', NULL, 'Ulos Tumtuman', 'mbavdd.jpg', 'Ulos Tumtuman modern telah menjadi bagian yang fleksibel dan dinamis dalam keseharian masyarakat Batak maupun pecinta budaya Indonesia. Dengan desain yang lebih ringan dan praktis dibanding ulos tradisional, kain ini mudah dipadukan dengan berbagai gaya busana, mulai dari casual hingga semi-formal. Sebagai selendang atau syal, ulos ini tidak hanya memberikan sentuhan elegan tetapi juga menjaga kehangatan tubuh di kala cuaca dingin. Warna-warnanya yang lebih bervariasi—seperti hitam, merah, emas, atau biru—memungkinkan pemakainya menyesuaikan dengan outfit tanpa kehilangan nuansa tradisional. Motif-motif khas Batak seperti ragi hotang atau bintang siat tetap dipertahankan, meski dengan sentuhan lebih sederhana, sehingga cocok dipakai ke kantor, acara keluarga, atau bahkan sekadar nongkrong di kafe.\r\n\r\nSelain sebagai fashion item, Ulos Tumtuman modern juga kerap digunakan sebagai elemen dekorasi rumah. Kain ini bisa dijadikan taplak meja, hiasan dinding, atau lapik altar di gereja, memberikan nuansa budaya yang hangat tanpa terkesan kaku. Di acara-acara adat yang lebih santai, seperti pemberian ulos (ulos panjoloan) dalam pernikahan atau syukuran keluarga, ulos modern ini sering dipilih karena harganya yang lebih terjangkau namun tetap sarat makna. Bahkan, banyak wisatawan yang membelinya sebagai oleh-oleh karena kepraktisannya dan nilai budayanya yang kental.', '', '3. Rumus Dasar\r\nJumlah benang lungsi = Lebar ulos (cm) × 10\r\nContoh: Lebar 100 cm → 1.000 helai benang lungsi.\r\nSusunan motif: Kombinasi garis vertikal/horizontal dengan warna dominan hitam, merah, emas, dan aksen putih.\r\nPanjang benang lungsi: 200 cm (kain efektif) + 2 × 30 cm (cadangan mesin) = 2,6 meter per helai.\r\n\r\n4. Digital Winding – Penyiapan Benang Lungsi\r\nBenang dasar: 1.000 helai benang hitam pekat.\r\nSisipan warna:\r\nSetiap 100 helai, sisipkan benang warna:\r\nHelai ke-100: merah\r\nHelai ke-200: emas\r\nHelai ke-300: putih\r\nUlangi pola hingga helai ke-1.000.\r\nPenggulungan: Benang digulung otomatis ke spool digital dengan urutan terprogram.\r\n\r\n5. Auto Warping – Pemasangan Benang ke Mesin Tenun\r\nDistribusi benang:\r\n10 helai benang per rongga sisorhon (reed) → total 100 rongga.\r\nBenang dipasang ke torop (pembagi jalur) secara silang berdasar pola digital.\r\nVerifikasi sistem: Sensor digital memastikan distribusi warna simetris untuk motif Tumtuman.\r\n\r\n6. Digital Weaving – Proses Menenun\r\nBenang pakan dasar: Hitam pekat.\r\nSisipan motif: Setiap 40 sisipan benang pakan, tambahkan:\r\n1 sisipan benang merah\r\n1 sisipan benang emas\r\n1 sisipan benang putih\r\nDurasi tenun: ±8–10 jam untuk mencapai panjang 200 cm.\r\nPengaturan mesin:\r\nTekanan benang diatur otomatis untuk kerapatan sedang (tidak terlalu padat seperti ulos tradisional).\r\n\r\n7. Finishing Mekanis\r\nPemotongan: Mesin otomatis memotong kain dengan pisau laser untuk tepian rapi.\r\nJahitan tepi: Overlock industri untuk mencegah fraying (terurai).\r\nPengepresan: Steam press suhu 40°C untuk menghaluskan permukaan.\r\n8. Pagolong – Penyimpanan\r\nKain dilipat tiga bagian memanjang sesuai adat Batak.\r\nDikemas dalam plastik vakum untuk proteksi selama distribusi.', NULL, NULL, '200', '120', 'Ulos Tumtuman modern berakar dari tradisi tenun Batak Toba yang telah ada sejak abad ke-17 di wilayah sekitar Danau Toba, khususnya di kawasan Samosir. Awalnya, ulos ini dikenal sebagai \"tumtuman\" yang dalam bahasa Batak berarti \"penyangga\" atau \"penopang\", mencerminkan fungsinya sebagai kain pelengkap dalam berbagai upacara adat penting. Para tetua adat dahulu menggunakan Tumtuman tradisional sebagai ikat pinggang dalam ritual pernikahan dan upacara kematian, dengan motif garis-garis vertikal berwarna coklat tanah yang dihasilkan dari pewarna alami akar mengkudu dan hordeng, serta benang emas asli yang melambangkan kemuliaan dan hubungan dengan alam spiritual.\r\n\r\nPerkembangan menjadi bentuk modern dimulai pada pertengahan abad ke-20 ketika para pengrajin mulai mengadaptasi teknik dan bahan baru. Era 1980-an menjadi titik penting ketika para desainer Batak di Medan mulai memodifikasi Tumtuman untuk penggunaan yang lebih luas, tidak hanya terbatas pada upacara adat. Inovasi terbesar terjadi pada awal 2000-an dengan diperkenalkannya benang polyester-metalik yang memberikan efek kilau modern namun tetap mempertahankan makna filosofisnya. Warna coklat tua yang menjadi ciri khas tetap dipertahankan sebagai simbol kesuburan tanah leluhur, sementara garis-garis vertikalnya yang khas kini dibuat lebih variatif namun tetap mempertahankan makna aslinya sebagai petunjuk jalan hidup yang lurus.\r\n\r\nProses modernisasi ini tidak menghilangkan nilai-nilai tradisional, melainkan justru membuat Ulos Tumtuman semakin dikenal luas, baik sebagai busana adat yang sakral maupun sebagai elemen fashion kontemporer yang bernilai budaya tinggi. Kini, Tumtuman modern diproduksi dengan teknik tenun semi-mekanis yang lebih efisien, namun tetap mempertahankan ketelitian dan makna filosofis yang sama seperti yang dijaga oleh para penenun tradisional di pedesaan Samosir selama berabad-abad.', 'Modern');
INSERT INTO `produk_alat` (`id`, `kode_produk`, `nama_alat`, `gambar_alat`, `deskripsi`, `cara_penggunaan`) VALUES
(3842, 'P0004', 'Mesin Tenun Jacquard Semi-Automatik', '1745851079_Picture8.jpg', 'Mesin ini memungkinkan penciptaan pola-pola rumit dengan menggunakan kartu Jacquard atau file digital yang berisi desain motif Ragihotang.', 'Mesin tenun Jacquard mengatur benang lusi dan pakan secara otomatis untuk menciptakan pola yang telah diprogramkan.'),
(3843, 'P0004', '. Warping Machine (Mesin Penggulung Benang Lusi)', '1745851079_Picture9.jpg', 'Mengatur benang lusi agar terletak dengan rapat dan sejajar sebelum digunakan dalam proses penenunan.', 'Mesin ini digunakan untuk menggulung benang lusi dengan rapat dan sejajar pada beam sebelum dimasukkan ke mesin tenun.'),
(3844, 'P0004', 'Shuttle (Alat Pembawa Benang Pakan)', '1745851079_Picture10.jpg', 'Shuttle membawa benang pakan bolak-balik melalui benang lusi untuk menyusun pola.', 'Membawa benang pakan melintasi benang lusi selama proses penenunan'),
(3845, 'P0004', '. Steam Press Machine (Mesin Pres Uap)', '1745851079_Picture11.jpg', 'Menghilangkan kerutan pada kain dan memperbaiki tekstur kain ulos.', 'Mesin ini digunakan untuk menghaluskan dan merapikan kain ulos setelah proses penenunan selesai.'),
(3846, 'P0004', 'Gunting Kain Industri', '1746613009_Picture12.jpg', 'Memotong kain sesuai pola dan ukuran produk akhir (selendang, syal, taplak, tas, dll).', 'Gunting digunakan untuk memotong kain ulos sesuai dengan ukuran produk akhir.'),
(3862, 'P0003', 'Mesin Tenun Jacquard Semi-Automatik', '1745849361_Picture6.jpg', 'Mesin ini memungkinkan pembuatan pola rumit pada ulos Sadum dengan kontrol otomatis dan digital.', 'Mesin tenun Jacquard digunakan untuk mengatur benang lusi dan pakan secara otomatis, menciptakan pola sesuai dengan desain yang sudah diprogramkan.'),
(3863, 'P0003', 'Warping Machine (Mesin Penggulung Benang Lusi)', '1745849361_Picture7.jpg', 'Mesin ini digunakan untuk menggulung benang lusi secara teratur dan rapat pada beam.', 'Mesin ini digunakan untuk menggulung benang lusi secara teratur dan rapat pada beam.'),
(3864, 'P0003', 'Shuttle (Alat Pembawa Benang Pakan)', '1745849361_Picture8.jpg', 'Membawa benang pakan bolak-balik selama proses penenunan.', 'Shuttle membawa benang pakan melintasi benang lusi untuk membentuk pola.'),
(3865, 'P0003', 'Steam Press Machine (Mesin Pres Uap)', '1745849361_Picture9.jpg', 'Menghilangkan kerutan dan memperbaiki tekstur kain ulos.', 'Mesin ini digunakan untuk menghaluskan dan merapikan kain ulos setelah selesai ditenun.'),
(3866, 'P0003', '. Gunting Kain Industri', '1745849361_Picture10.jpg', 'Memotong kain sesuai ukuran yang diinginkan untuk produk akhir (selendang, syal, taplak, dll).', 'Gunting digunakan untuk memotong kain sesuai dengan ukuran produk akhir.'),
(4083, 'P0006', 'Mesin Tenun Jacquard Semi-Automatic', '1747038314_ghjghh.jpg', 'Menenun benang lusi dan pakan menjadi kain bermotif Ragihidup secara otomatis dengan pola kompleks.', 'Mengotomatiskan proses penenunan pola kompleks pada ulos ragihidup. Mesin ini memungkinkan pengrajin menciptakan motif rumit secara presisi menggunakan kartu berlubang atau program digital.\r\n\r\n'),
(4084, 'P0006', 'Warping Machine (Mesin Penggulung Benang Lusi)', '1747038314_hkjgj.jpg', 'Membuat lembaran benang lusi sejajar dan rapi sebelum masuk ke mesin tenun.', 'Mengatur dan menggulung benang lusi secara teratur sebelum dipasang pada mesin tenun. Ini memastikan benang lusi tetap lurus dan tidak kusut selama proses tenun.'),
(4085, 'P0006', 'Shuttle (Alat Bawa Benang Pakan)', '1747038314_jkh.jpg', 'Membawa benang pakan bolak-balik menyeberangi benang lusi saat proses tenun.', 'Alat berbentuk perahu kecil yang membawa benang pakan untuk disisipkan melintang melalui benang lusi saat penenunan, membentuk pola motif.'),
(4086, 'P0006', 'Steam Press Machine (Mesin Pres Uap)', '1747038314_yigy.jpg', 'Menghaluskan ulos setelah ditenun, menghilangkan kerutan dan memperbaiki tekstur.', 'Digunakan untuk meratakan kain ulos setelah proses tenun, sekaligus membantu memperkuat pengikatan warna agar lebih awet dan tidak mudah pudar.'),
(4087, 'P0006', 'Gunting Kain Industri', '1747038314_sdkf.jpg', 'Memotong ulos sesuai ukuran produk (selendang, syal, taplak, tas, dll).', 'Digunakan untuk memotong kain ulos sesuai ukuran yang diinginkan. Gunting ini memiliki mata pisau tajam untuk menghasilkan potongan yang rapi dan presisi.'),
(4088, 'P0006', 'Alat Ukur Tekstil (Meteran dan Penggaris Besar)', '1747038314_ljdsfh.jpg', 'Mengukur panjang kain dan membuat pola potongan.', 'Digunakan untuk mengukur panjang dan lebar kain ulos secara akurat sebelum dan sesudah proses tenun agar sesuai dengan spesifikasi produk.'),
(4101, 'P0005', 'Alat Tenun Bukan Mesin (ATBM)', '1747056530_gk.jpg', 'Terbuat dari kayu, bekerja manual menggunakan kaki dan tangan', 'Digunakan untuk menenun seluruh bagian ulos'),
(4102, 'P0005', 'Baliga (Pemintal Manual)', '1747056530_dghd.jpg,1747056796_wdwbwd.jpg', 'Baliga adalah alat tradisional pemintal manual yang digunakan untuk mengubah kapas menjadi benang dalam pembuatan ulos Mangiring.', 'Kapas yang sudah dibersihkan diletakkan di ujung alat, lalu diputar secara terus-menerus menggunakan tangan agar serat kapas saling melilit dan membentuk benang. Benang yang dihasilkan kemudian digulung dan siap untuk diproses ke tahap pewarnaan atau langsung ditenun.'),
(4103, 'P0005', 'Palapaan (Penggulung Benang Lusi)', '1747056530_rhhr.jpg,1747056796_kwr.jpg', 'Alat kayu untuk menggulung dan menyiapkan benang lusi sebelum dipasang', ''),
(4104, 'P0005', 'Hapan (Beater)', '1747056530_tsteat.jpg', '•	Alat kayu untuk memadatkan anyaman setiap sisiran', 'Setelah benang pakan dimasukkan melalui parompa, tarik hapan ke arah penenun dan ketukkan secara perlahan namun tegas ke arah benang pakan. Ulangi proses ini setiap kali benang pakan baru dimasukkan untuk memastikan kerapatan yang konsisten.'),
(4105, 'P0005', 'Parompa (Shuttle)', '1747056531_adkadhfb.jpg', 'Alat pengantar benang pakan secara manual bolak-balik', ' Isi parompa dengan benang pakan yang sudah digulung rapi. Pegang parompa di tangan dominan, lalu dorong secara perlahan melalui celah benang lungsin dari satu sisi ke sisi lainnya. Tarik benang pakan hingga rata, lalu ulangi proses hingga selesai.'),
(4106, 'P0005', 'Punu (Pisau Kecil)', '1747056531_sdkfjhj.jpg,1747056796_dfndfg.jpg', 'Digunakan untuk memotong dan merapikan sisa benang\r\n\r\n', 'Gunakan ujung punu untuk mengiris benang pakan yang berlebih atau benang lungsin yang terjuntai. Potong secara hati-hati agar tidak merusak struktur anyaman dan pastikan potongan benang rapi agar hasil ulos tampak halus.'),
(4214, 'P0010', 'Mesin Tenun Jacquard Semi-Automatik', '1747318447_aekhfhb.jpg', 'Fungsi: Menjalankan pola ulos Pinucaan yang rumit secara otomatis.', 'Digunakan untuk menenun benang lusi dan pakan secara otomatis, menghasilkan motif yang rumit dan presisi seperti pada Ulos Pinucaan Modern.'),
(4215, 'P0010', 'Mesin Warping (Penggulung Benang Lusi)', '1747318447_ajsd.jpg', 'Fungsi: Menyusun benang lusi sejajar dan rapi.', 'Menggulung benang lusi dengan ketegangan seragam sebelum dipasang pada mesin tenun.'),
(4216, 'P0010', 'Shuttle (Pengangkut Benang Pakan)', '1747318447_dkjhdfbhkj.jpg', 'Fungsi: Membawa benang pakan melintas ke kiri-kanan.', 'Mengangkut benang pakan melintang di antara benang lusi untuk membentuk pola tenunan horizontal.'),
(4217, 'P0010', 'Steam Press Machine (Mesin Pres Uap)', '1747318447_sekbfa.jpg', 'Fungsi: Menghaluskan kain dan merapikan struktur tenunan.', 'Merapikan dan melembutkan kain setelah proses tenun dengan uap panas, menghilangkan kerutan dan memberikan hasil akhir yang rapi.'),
(4218, 'P0010', 'Gunting Kain Industri', '1747318447_dkjkdfs.jpg', 'Fungsi: Memotong kain setelah proses tenun selesai.', 'Memotong kain tenunan setelah selesai sesuai ukuran yang ditentukan dengan hasil pemotongan yang rapi dan presisi.'),
(4229, 'P0012', 'Mesin Tenun Jacquard/Dobby Semi-Automatik', '1747326152_adf.jpg', 'Fungsi: Membuat motif bintang kecil yang khas secara akurat.\r\nProgram mesin dengan pola bintang maratur yang terdiri dari motif segitiga dan garis silang yang membentuk bintang di tengah.\r\nMesin akan mengangkat benang lusi sesuai dengan pola yang diinginkan, membuat garis dan bentuk bintang secara rapi.\r\n', 'Mesin ini mengontrol setiap benang lungsi dan pakan secara otomatis, memungkinkan pembuatan pola rumit dan detil, seperti motif bintang, dengan presisi tinggi. Mesin Jacquard atau Dobby mengatur gerakan benang lungsi agar pola yang diinginkan muncul secara konsisten dalam proses penenunan.'),
(4230, 'P0012', 'Mesin Warping', '1747326152_sdfjvhadf.jpg', 'Fungsi: Membuat benang lusi teratur dan sejajar.', 'Mesin warping digunakan untuk menyusun benang lungsi dengan rapat dan teratur sesuai panjang yang dibutuhkan. Mesin ini memastikan benang lungsi terpasang dengan tepat, sehingga hasil penenunan tetap rapi dan pola yang dihasilkan bisa akurat.'),
(4231, 'P0012', 'Shuttle (Pembawa Benang Pakan)', '1747326152_addfhv.jpg', 'Fungsi: Membawa benang pakan saat proses tenun.\r\nCara Pakai:\r\n➔ Isi shuttle dengan benang sesuai warna, dan mesin akan otomatis menenun pola.\r\n', 'Shuttle berfungsi untuk membawa benang pakan melintasi benang lungsi secara horizontal. Dengan cara ini, benang pakan akan disisipkan di antara benang lungsi, membentuk pola tenunan sesuai desain yang diinginkan, termasuk motif seperti bintang pada Ulos Bintang Maratur.'),
(4232, 'P0012', 'Steam Press Machine', '1747326152_akhdb.jpg', 'Fungsi: Menghaluskan kain setelah tenun selesai.', 'Setelah kain selesai ditenun, mesin setrika uap digunakan untuk menghaluskan dan merapikan kain. Uap panas menembus serat kain, mengurangi kerutan, dan memberikan hasil akhir yang lebih halus dan rapi.'),
(4233, 'P0012', 'Gunting Kain Industri', '1747326152_adzfbad.jpg', 'Fungsi: Memotong kain ulos sesuai ukuran final.', 'Gunting kain industri digunakan untuk memotong kain sesuai ukuran yang dibutuhkan. Alat ini juga digunakan untuk merapikan pinggiran kain setelah proses penenunan selesai, memastikan kain memiliki potongan yang presisi dan bersih.'),
(4242, 'P0011', 'Alat Tenun Bukan Mesin (ATBM)', '1747323162_sdjfb.jpg', 'Alat tenun tradisional yang digunakan untuk membuat ulos Lobu-Lobu secara manual, menggunakan kaki dan tangan untuk menjalankan proses penenunan.\r\n•	Fungsi: Menyusun benang lusi dan pakan dengan teknik manual untuk menghasilkan motif\r\n', 'Digunakan untuk menenun benang lusi (vertikal) dan benang pakan (horizontal) menjadi kain ulos dengan cara menyisipkan benang pakan menggunakan shuttle dan menginjak pedal untuk membuka benang lusi.'),
(4243, 'P0011', 'Alat Penggulung Benang Lusi (Palapaan)', '1747323162_vds.jpg', 'Alat untuk menggulung benang lusi yang akan dipasang di alat tenun.\r\nFungsi: Mengatur ketegangan dan kerapatan benang lusi sebelum dimasukkan ke alat tenun\r\n', 'Digunakan untuk menggulung benang lusi secara rapi sebelum dipasang di alat tenun agar benang tidak kusut.\r\n\r\n'),
(4244, 'P0011', 'Shuttle (Parompa)', '1747323162_jahe.jpg', 'Alat untuk membawa benang pakan melalui benang lusi dalam proses penenunan.\r\nFungsi: Membawa benang pakan bolak-balik saat menenun\r\n', 'Digunakan untuk menyisipkan benang pakan dari satu sisi ke sisi lain antara benang lusi, dengan gerakan bolak-balik.'),
(4245, 'P0011', 'Hapan (Beater)', '1747323162_lejrn.jpg', 'Alat untuk memadatkan anyaman benang pakan dan lusi agar lebih rapat dan kokoh.\r\nFungsi: Memadatkan setiap sisiran benang pakan ke dalam anyaman benang lusi\r\n', 'Digunakan untuk memukul dan menekan benang pakan setelah disisipkan, memastikan benang rapat dan rapi di antara benang lusi.'),
(4254, 'P0009', 'Alat Tenun Bukan Mesin (ATBM)', '1747313731_wdfdfw.jpg,1747314660_sdjfb.jpg,1747314759_dg.jpg', 'Fungsi: Digunakan untuk merangkai benang lusi dan pakan secara manual, menciptakan pola simetris di kedua sisi kain', 'digunakan sebagai kerangka utama untuk menenun, di mana benang lusi direntangkan pada bagian depan hingga belakang alat, lalu penenun duduk di bagian tengah untuk mengatur pergerakan benang dan menjalankan proses tenun secara manual dengan kaki dan tangan.'),
(4255, 'P0009', 'Palapaan (Penggulung Lusi)', '1747313731_vds.jpg,1747314660_mbsv.jpg', 'Fungsi: Menggulung dan menyusun benang lusi dengan tegangan yang konsisten', 'dipakai untuk menggulung dan merapikan benang lusi sebelum dipasang pada ATBM, caranya adalah dengan memutar palapaan agar benang tertarik masuk ke bagian belakang alat tenun dalam posisi tegang dan sejajar.'),
(4256, 'P0009', 'Parompa (Shuttle)', '1747313731_adkadhfb.jpg,1747314660_sdbvds.jpg,1747314759_khdg.jpg', 'Fungsi: Menyisipkan benang pakan ke sela benang lusi, bolak-balik hingga motif terbentuk', 'digunakan untuk memasukkan benang pakan secara melintang ke dalam celah benang lusi, caranya dengan mendorong parompa dari satu sisi ke sisi lainnya setiap kali celah benang terbuka oleh injakan kaki pada ATBM.'),
(4257, 'P0009', 'Hapan (Beater)', '1747313731_lejrn.jpg,1747314660_adjhf.jpg', 'Fungsi: Memadatkan hasil tenunan agar kain lebih rapat, kokoh, dan awet', 'digunakan untuk merapatkan benang pakan setiap kali selesai ditenun, dengan cara menarik alat ini ke arah penenun agar benang pakan tertata padat dan rapi di antara benang lusi sesuai pola ulos'),
(4273, 'P0008', 'Mesin Tenun Jacquard Semi-Automatik', '1747302272_dhkds.jpg', 'Fungsi: Menenun ulos secara otomatis berdasarkan pola digital Sibolang.', 'Benang lusi yang telah dipasang pada mesin warping dimasukkan ke dalam mesin tenun Jacquard.\r\nPola motif diatur melalui sistem komputer atau input USB, memungkinkan variasi desain yang fleksibel.\r\nMesin ini mengontrol pergerakan benang lusi dan pakan secara otomatis, menghasilkan kain dengan motif yang konsisten dan berkualitas tinggi.'),
(4274, 'P0008', 'Mesin Warping (Penggulung Benang Lusi)', '1747302272_ddfjh.jpg', 'Fungsi: Mengatur benang lusi agar sejajar dan rapi sebelum ditenun.', 'Benang lusi dari gulungan besar dipasang pada mesin warping.\r\nMesin menggulung benang ke beam dengan ketegangan yang konsisten, memastikan kualitas tenunan yang baik.\r\nBeberapa mesin warping dilengkapi dengan fitur kontrol ketegangan otomatis dan pemutus benang otomatis untuk efisiensi produksi.\r\n\r\n'),
(4275, 'P0008', 'Shuttle (Pengangkut Benang Pakan)', '1747302272_dkjhdfbhkj.jpg', 'Fungsi: Membawa benang pakan melintasi benang lusi.', 'Benang pakan dimasukkan ke dalam shuttle.\r\nShuttle bergerak bolak-balik melalui benang lusi, menyisipkan benang pakan untuk membentuk kain.\r\nDalam mesin tenun modern, pergerakan shuttle dikendalikan secara otomatis untuk meningkatkan kecepatan dan konsistensi penenunan.'),
(4276, 'P0008', 'Steam Press Machine (Mesin Pres Uap)', '1747302272_sddkfjh.jpg', 'Fungsi: Merapikan dan melembutkan kain ulos.', 'Kain yang telah selesai ditenun ditempatkan pada meja pres.\r\nUap panas diterapkan pada kain untuk menghilangkan kerutan dan memperbaiki tekstur kain.\r\nProses ini juga membantu mengatur dimensi kain dan meningkatkan kenyamanan saat digunakan.\r\n\r\n'),
(4277, 'P0008', 'Gunting Kain Industri', '1747302272_dkjkdfs.jpg', 'Fungsi: Memotong kain ulos sesuai ukuran produk akhir.', 'Kain yang telah selesai dipres dan dikeringkan diletakkan pada meja potong.\r\nGunting kain industri digunakan untuk memotong kain sesuai dengan ukuran dan bentuk yang diinginkan.\r\nBeberapa gunting industri dilengkapi dengan fitur otomatis untuk meningkatkan efisiensi dan konsistensi pemotongan.'),
(4286, 'P0007', 'Alat Tenun Bukan Mesin (ATBM)', '1747283525_msnm.jpg,1747314417_gk.jpg', 'Merangkai benang lusi dan pakan dengan metode manual menghasilkan pola simetris dan presisi khas Ragi Pakko', ' digunakan sebagai alat utama untuk menenun ulos secara manual. Penenun duduk di depan ATBM, menginjak pedal untuk membuka jalur benang lusi, menyelipkan benang pakan dengan sekoci, dan memukul hasil tenunan menggunakan hapan agar benang rapat.'),
(4287, 'P0007', 'Palapaan (Penggulung Benang Lusi)', '1747283525_dcsbs.jpg,1747314417_vds.jpg', 'Menggulung dan menyusun benang lusi dengan ketegangan stabil', 'digunakan untuk menggulung seluruh benang lusi yang telah disusun. Benang digulung dengan hati-hati ke palapaan agar tersimpan rapi dan siap dipasang ke bagian belakang alat tenun tanpa berubah urutan atau posisi warnanya.'),
(4288, 'P0007', 'Parompa (Shuttle)', '1747314417_khdg.jpg', 'Mengantar benang pakan melalui sela-sela benang lusi dalam proses bolak-balik manual', ' dilakukan dengan memastikan setiap helai benang memiliki tarikan yang merata saat digulung ke palapaan dan dipasang ke alat tenun. Ini penting agar hasil tenunan rata dan tidak bergelombang atau miring saat ditenun.'),
(4289, 'P0007', 'Hapan (Beater)', '1747314169_lejrn.jpg', 'Memadatkan hasil tenunan agar kain lebih rapat, kokoh, dan awet', 'digunakan untuk memukul benang pakan setiap kali disisipkan ke dalam lungsi. Alat ini ditarik dan dilepaskan oleh penenun agar benang pakan menempel rapat ke baris sebelumnya, memastikan hasil tenunan padat, kuat, dan rapi.'),
(4290, 'P0001', 'Alat Tenun Bukan Mesin', '1746454304_gk.jpg', 'ATBM adalah alat tradisional untuk menenun kain secara manual tanpa bantuan mesin. Alat ini terdiri dari berbagai bagian kayu yang disusun menjadi satu sistem kerja untuk menenun benang lusi dan benang pakan.', 'Duduklah di depan alat tenun, lalu gunakan kaki untuk menginjak pedal agar benang lusi terbuka (terpisah). Setelah celah terbuka, masukkan benang pakan menggunakan shuttle. Setelah itu, gunakan sisir tenun untuk merapatkan benang pakan ke arah kain. Ulangi proses ini secara bergantian untuk membentuk motif ulos Ragihidup sesuai pola yang diinginkan.'),
(4291, 'P0001', 'Gawangan (Rak Lusi)', '1746454304_rts.jpg', 'Gawangan adalah rak atau kerangka tempat menggulung dan menyusun benang lusi sebelum ditenun. Terbuat dari kayu, bentuknya seperti bingkai tegak.', 'Pasang benang lusi satu per satu pada gawangan dengan posisi sejajar dan tegang. Pastikan tidak ada benang yang kusut atau kendur. Setelah semua benang lusi tersusun, benang akan digulung dan diarahkan ke alat tenun agar siap ditenun. Gawangan membantu menjaga urutan dan ketegangan benang supaya motif tenunan tetap rapi.'),
(4292, 'P0001', 'Sisir Tenun (Sisir Pakan)', '1746454304_zrr.jpg', 'Sisir tenun adalah alat bergigi terbuat dari bambu atau logam, digunakan untuk merapatkan benang pakan setiap kali benang dimasukkan ke dalam benang lusi.', 'Setelah benang pakan dimasukkan ke dalam celah benang lusi, tarik sisir tenun ke arah kain untuk merapatkan benang pakan. Lakukan hal ini setiap kali satu baris benang pakan ditenun agar hasil tenunan menjadi padat, kuat, dan motif terlihat jelas.'),
(4293, 'P0001', 'Shuttle (Alat Pembawa Benang Pakan)', '1746454304_fyhfd.jpg', 'Shuttle adalah alat berbentuk seperti perahu kecil yang digunakan untuk membawa dan mengarahkan benang pakan (melintang). Terbuat dari kayu, dan di dalamnya ada gulungan benang pakan.', 'Isi shuttle dengan benang pakan, lalu gerakkan shuttle secara manual dari kanan ke kiri (atau sebaliknya) melewati celah benang lusi yang telah terbuka oleh pedal. Setelah shuttle melewati benang lusi, ambil sisir dan tekan benang pakan ke arah kain. Ulangi proses ini untuk setiap baris tenunan.'),
(4294, 'P0001', 'Wadah Pewarnaan Alami', '1746454304_hikg.jpg', 'Wadah ini biasanya berupa gentong tanah liat atau ember besar, digunakan untuk mencelupkan benang atau kain ke dalam larutan pewarna alami.', 'Siapkan larutan pewarna alami di dalam wadah. Masukkan benang yang akan digunakan ke dalam larutan tersebut. Rendam benang selama beberapa waktu agar warna meresap sempurna. Setelah itu, angkat dan jemur benang hingga kering. Ulangi pencelupan jika dibutuhkan untuk menghasilkan warna yang lebih tajam dan sesuai dengan ciri khas ulos Ragihidup.\r\n\r\n'),
(4311, 'P0013', 'Alat Tenun Bukan Mesin (ATBM)', '1748066726_jadn.jpg', 'Alat tenun tradisional yang digunakan untuk menenun ulos Suri-Suri Nganjang secara manual, menggunakan tangan dan kaki.\r\nFungsi: Menyusun benang lusi dan pakan dengan teknik manual untuk menghasilkan motif khas\r\n\r\n', 'Digunakan sebagai tempat utama menenun. Benang lusi dipasang memanjang di alat ini, lalu penenun duduk, menginjak pedal untuk membuka benang lusi, menyisipkan benang pakan, dan merapatkannya.'),
(4312, 'P0013', 'Alat Penggulung Benang Lusi (Palapaan)', '1748066726_vds.jpg', 'Alat tradisional untuk menggulung benang lusi sebelum dipasang pada alat tenun.\r\nFungsi: Mengatur ketegangan dan kerapatan benang lusi\r\n', 'Digunakan untuk menggulung dan menyusun benang lusi sesuai urutan. Setelah benang diukur dan diberi motif, semua helai digulung di palapaan agar rapi dan mudah dipasang ke alat tenun.'),
(4313, 'P0013', 'Shuttle (Parompa)', '1748066726_adkadhfb.jpg', 'Alat untuk membawa benang pakan melalui benang lusi saat proses penenunan.\r\nFungsi: Membawa benang pakan bolak-balik secara manual\r\n\r\n', 'Alat kecil berbentuk perahu yang digunakan untuk membawa benang pakan. Shuttle ini dilempar atau digerakkan dari sisi kanan ke kiri dan sebaliknya di antara benang lusi saat menenun.'),
(4314, 'P0013', 'Hapan (Beater)', '1748066726_lejrn.jpg', 'Alat untuk memadatkan hasil anyaman benang pakan dan lusi.\r\nFungsi: Memadatkan setiap sisiran benang pakan agar kain lebih rapat dan kokoh\r\n', 'Alat untuk memukul atau merapatkan benang pakan setelah disisipkan. Setelah shuttle lewat, hapan ditarik ke depan untuk memadatkan anyaman agar kain kuat dan motif terlihat jelas.\r\n\r\n'),
(4352, 'P0016', 'Mesin Tenun Jacquard Semi-Automatik', '1748083087_adn.jpg', 'Menenun motif garis-garis sejajar khas Tumtuman secara digital', 'digunakan untuk menenun benang lusi dan pakan secara otomatis dengan sistem kontrol motif digital; benang dimasukkan dan mesin dijalankan untuk mengangkat dan menurunkan benang sesuai pola motif yang telah diprogram.'),
(4353, 'P0016', 'Warping Machine', '1748083087_dffbkd.jpg', 'Menyusun benang lusi secara rapi sebelum proses tenun', 'digunakan untuk menyusun dan menggulung benang lusi secara rapi sebelum dipasang di mesin tenun; benang ditempatkan pada cone lalu ditarik dan digulung seragam ke beam lusi untuk memastikan ketegangan benang stabil.'),
(4354, 'P0016', 'Shuttle', '1748083087_adads.jpg', 'Membawa benang pakan bolak-balik selama proses tenun', 'digunakan untuk membawa benang pakan masuk ke sela-sela benang lusi; shuttle diisi benang pakan lalu dimasukkan ke mesin tenun dan bergerak otomatis bolak-balik mengikuti jalur tenunan.'),
(4355, 'P0016', 'Steam Press Machine', '1748083087_hfbs.jpg', 'Merapikan hasil tenun dengan uap panas', 'digunakan untuk merapikan hasil tenunan setelah selesai; kain ulos diletakkan di atas meja press lalu ditekan menggunakan uap panas untuk menghaluskan permukaan dan mengunci bentuk akhir kain.'),
(4356, 'P0016', 'Gunting Kain Industri', '1748083087_admnfad.jpg', 'Memotong ulos sesuai ukuran akhir', 'digunakan untuk memotong kain ulos dari gulungan atau sisa tenunan; kain diukur sesuai ukuran yang diinginkan lalu digunting dengan gerakan lurus dan cepat untuk hasil potongan yang rapi.'),
(4361, 'P0015', 'Alat Tenun Bukan Mesin (ATBM)', '1748079611_jadn.jpg', 'Fungsi: Menenun ulos secara manual untuk hasil tenunan kokoh dan tebal', 'Alat ini digunakan untuk menggulung benang lungsi sebelum dipasang ke ATBM. Benang digulung rapi sepanjang 4-5 meter dengan ketegangan seragam, kemudian dipasang melintang pada rangka ATBM. Gulungan harus cukup kencang agar benang tidak kendur saat ditenun.'),
(4362, 'P0015', 'Palapaan', '1748079611_ksd.jpg', 'Fungsi: Menggulung benang lusi dengan kontrol tegangan agar tidak mudah putus', 'Sisir logam ini berfungsi mengatur kerapatan benang lungsi. Setiap helai benang dimasukkan satu per satu ke rongganya dengan kerapatan 12-15 helai per cm untuk motif Antak-Antak. Sisorhon juga berperan merapatkan benang pakan setiap kali dilempar.'),
(4363, 'P0015', 'Shuttle (Parompa)', '1748079611_jahe.jpg', 'Fungsi: Membawa benang pakan bolak-balik, khususnya benang dengan pilinan rapat', 'Kayu berbentuk perahu kecil ini diisi benang pakan sepanjang 1-1.5 meter. Penenun melemparnya secara bergantian antara tangan kanan dan kiri melewati shed (celah benang lungsi). Gerakan harus lurus dan cepat untuk mempertahankan kerapatan motif.'),
(4364, 'P0015', 'Hapan (Beater)', '1748079611_rrgf.jpg', 'Fungsi: Memadatkan tenunan dengan kekuatan lebih agar motif antak terlihat jelas', 'Setelah benang pakan dimasukkan, hapan (baliga) dipukulkan dengan tangan untuk merapatkan anyaman. Untuk Ulos Antak-Antak, diperlukan 3-4 pukulan kuat per baris agar motif kotak-kotak terbentuk rapat dan presisi. Kekuatan pukulan harus konsisten sepanjang proses.'),
(4370, 'P0014', 'Mesin Tenun Jacquard Semi-Otomatis', '1748075384_addf.jpg', 'Menenun motif garis Mangiring otomatis sesuai pola digital', 'Benang lusi diatur di torop dan sisorhon, lalu mesin mengangkat benang sesuai pola digital (motif Mangiring), sementara benang pakan masuk otomatis. Pola motif disisipkan horizontal sesuai pengaturan warna.\r\n\r\n'),
(4371, 'P0014', 'Warping Machine', '1748075384_jddf.jpg', 'Menyusun benang lusi secara sejajar', '900 helai benang disusun dengan jarak dan urutan sesuai pola warna. Mesin menarik, mengatur tegangan, dan membagi benang ke 90 rongga sisir (10 helai/rongga), siap untuk ditenun.\r\n\r\n'),
(4372, 'P0014', 'Shuttle', '1748075384_hmaf.jpg', 'Membawa benang pakan bolak-balik', 'Dalam mode semi-otomatis, shuttle bergerak bolak-balik dengan kontrol kecepatan. Benang pakan masuk bersamaan dengan setiap bukaan jalur benang lusi, menyusun struktur horizontal kain.'),
(4373, 'P0014', 'Steam Press Machine', '1748075384_adzfbad.jpg', 'Merapikan dan melembutkan tenunan akhir', ' Setelah kain jadi, diletakkan pada papan press lalu ditekan menggunakan uap panas ±150°C selama beberapa detik, menghilangkan lipatan dan memperkuat struktur tenunan.\r\n\r\n'),
(4374, 'P0014', 'Gunting Kain Industri', '', 'Memotong ulos sesuai ukuran', ' Setelah kain jadi, diletakkan pada papan press lalu ditekan menggunakan uap panas ±150°C selama beberapa detik, menghilangkan lipatan dan memperkuat struktur tenunan.\r\n\r\n'),
(4395, 'P0002', 'Alat Tenun Bukan Mesin (ATBM)', '1745896847_gk.jpg', 'Tenunan Ulos Ragihotang Tradisional dilakukan menggunakan alat tenun kayu sederhana, digerakkan manual.', 'Digunakan dengan cara menginjak pedal untuk mengatur posisi benang lusi, lalu tangan memasukkan benang pakan secara bergantian sambil menggerakkan sisir tenun.'),
(4396, 'P0002', 'Gawangan (Rak Lusi)', '1745896847_gfhg.jpg', 'Rak kayu untuk mengatur dan menggulung benang lusi sebelum dipasang di ATBM.', 'Digunakan dengan cara menggulung dan merentangkan benang lusi pada rak agar tetap tegang dan tidak kusut sebelum dipasang di alat tenun.'),
(4397, 'P0002', 'Sisir Tenun (Sisir Pakan)', '1745896847_zrr.jpg', 'lat berupa sisir kayu/bambu untuk menyelipkan benang pakan ke antara benang lusi.', 'Dipakai dengan cara ditekan ke bawah setelah setiap sisipan benang pakan, untuk merapatkan anyaman agar kain kuat dan rata.'),
(4398, 'P0002', 'Shuttle (Alat Pembawa Benang Pakan)', '1745896847_yjr.jpg', 'Shuttle sederhana dari kayu, digunakan untuk menyisipkan benang pakan dari satu sisi ke sisi lainnya.', 'Digunakan dengan cara melempar atau mendorong shuttle yang membawa benang pakan melewati sela-sela benang lusi.'),
(4399, 'P0002', 'Alat Pewarnaan Tradisional (Tong Kayu):', '1745896847_fhf.jpg', 'Biasanya berupa tong kayu besar atau tempayan tanah liat untuk merendam benang dalam pewarna alami.', 'Dipakai dengan cara merendam benang ke dalam larutan pewarna di dalam tong, lalu diaduk atau diputar supaya warna meresap merata.\r\n\r\n');
INSERT INTO `produk_bahan` (`id`, `kode_produk`, `nama_bahan`, `gambar_bahan`, `deskripsi`, `cara_penggunaan`, `jumlah_benang`) VALUES
(4115, 'P0004', 'Benang Lusi (Warp)', '1745851079_Picture2.jpg', '•Jenis Benang Lusi: Katun atau polyester\r\n•Jumlah Benang Lusi: Berdasarkan pola yang diinginkan, jumlah benang lusi dapat bervariasi. Untuk satu ulos Ragihotang ukuran standar (200 cm x 70 cm), diperlukan sekitar 75 gram benang lusi.\r\n•Kepadatan: 50 benang per inci\r\n', 'Benang lusi adalah benang yang ditempatkan secara membujur (vertikal) pada mesin tenun, menjadi dasar pembentukan pola.', ''),
(4116, 'P0004', 'Benang Pakan (Weft)', '1745851079_Picture4.jpg', '•Jenis Benang Pakan: Benang katun, polyester, atau campuran keduanya\r\n•Jumlah Benang Pakan: Untuk satu ulos Ragihotang, dibutuhkan 600 gram benang pakan, yang terdiri dari 3 warna utama, yaitu merah, putih, dan kuning emas. Setiap warna membutuhkan sekitar 200 gram benang pakan.\r\n•Kepadatan Pakan: 45 anyaman per inci, dengan panjang kain 2 meter (78,7 inci), menghasilkan 3.541 sisiran pakan.\r\n', 'Benang pakan adalah benang yang bergerak melintang (horizontal) untuk menyusun motif pada kain.', NULL),
(4117, 'P0004', 'Pewarna Tekstil', '1745851079_Picture5.jpg', '•	Jenis Pewarna: Remazol atau Procion MX (pewarna reaktif)\r\n•	Warna:\r\no	Scarlet Red\r\no	Bright White\r\no	Gold Yellow\r\no	Black Deep\r\n•	Takaran Pewarna:\r\no	30 gram pewarna untuk setiap 5 liter air\r\no	Dibutuhkan sekitar 20 gram pewarna per warna untuk setiap ulos (total 60 gram untuk 3 warna).\r\n', 'Pewarna yang digunakan harus tahan lama dan memiliki daya serap tinggi agar hasil warna tetap cerah dan tidak cepat luntur.', NULL),
(4118, 'P0004', 'Fixer (Penguat Warna)', '1745851079_Picture6.jpg', '•Jenis Fixer: Sodium Carbonate (Soda Ash)\r\n•Takaran Fixer: 50 gram per 5 liter air\r\n•Penggunaan: 10 gram per warna untuk memperkuat daya serap pewarna.\r\n', 'Fixer digunakan untuk mengikat pewarna dengan serat benang agar warnanya lebih tahan lama.', NULL),
(4119, 'P0004', 'Softener (Pelembut Kain)', '1745851079_Picture7.jpg', '•Jenis: Non-ionic softener\r\n•Takaran: 50 ml per 10 meter kain\r\n•Penggunaan: Untuk 1 ulos ukuran standar, sekitar 10 ml softener dibutuhkan.\r\n', 'Softener digunakan untuk memberikan kelembutan pada kain ulos, sehingga nyaman saat digunakan.', NULL),
(4120, 'P0004', 'Lem Kanji', '1746612949_fyh.jpg', '•Jenis: Kanji alami (Tapioka/Starch)\r\n•Takaran: 200 gram per 5 liter air\r\n•Penggunaan: 3 gram kanji untuk 75 gram benang lusi.\r\n', 'Lem kanji digunakan untuk memperkuat benang lusi agar tidak mudah putus selama proses penenunan.', NULL),
(4137, 'P0003', 'Benang Lusi (Warp)', '1745848718_WhatsApp Image 2025-04-28 at 20.53.08_84d7687b.jpg', 'Jenis Benang Lusi: Katun, polyester, atau campuran keduanya\r\n\r\nJumlah Benang Lusi:\r\nUntuk satu ulos Sadum ukuran standar (200 cm x 70 cm), dibutuhkan sekitar 80 gram benang lusi.\r\n\r\nKepadatan: 55 benang per inci\r\n', 'Benang lusi menyusun struktur dasar kain, yang menjadi tempat benang pakan melintas untuk membentuk pola.', ''),
(4138, 'P0003', 'Benang Pakan (Weft)', '1745848718_wewwe.jpg', '•Jenis Benang Pakan: Katun atau polyester\r\n•Jumlah Benang Pakan:\r\noUntuk satu ulos Sadum ukuran standar, dibutuhkan 500 gram benang pakan, yang terdiri dari dua warna (misalnya merah dan putih).\r\noSetiap warna membutuhkan sekitar 250 gram benang pakan.\r\n•	Kepadatan Pakan: 50 anyaman per inci\r\n', 'Benang pakan membentuk pola pada kain ulos Sadum.', NULL),
(4139, 'P0003', 'Pewarna Tekstil', '1745848718_wrfw.jpg', '•Jenis Pewarna: Remazol atau Procion MX (pewarna reaktif)\r\n•Warna:\r\noMerah\r\noPutih\r\n•Takaran Pewarna:\r\no30 gram pewarna untuk setiap 5 liter air\r\noDibutuhkan sekitar 15 gram pewarna per warna untuk setiap ulos Sadum (total 30 gram untuk dua warna).\r\n', 'Pewarna tekstil yang digunakan untuk memberikan warna pada benang pakan.', NULL),
(4140, 'P0003', '. Fixer (Penguat Warna)', '1745849361_Picture3.jpg', '•Jenis Fixer: Sodium Carbonate (Soda Ash)\r\n•Takaran Fixer: 50 gram per 5 liter air\r\n•Penggunaan: 7 gram per warna untuk setiap ulos Sadum.\r\n', 'Fixer digunakan untuk mengikat pewarna pada benang pakan agar warnanya tidak luntur.', NULL),
(4141, 'P0003', '. Softener (Pelembut Kain)', '1745849361_Picture4.jpg', '•Jenis: Non-ionic softener\r\n•Takaran: 50 ml per 10 meter kain\r\n•Penggunaan: Untuk satu ulos (200 cm x 70 cm), sekitar 8 ml softener dibutuhkan\r\n', 'Softener membuat kain lebih lembut dan nyaman saat digunakan.', NULL),
(4142, 'P0003', 'Lem Kanji', '1745849361_Picture5.jpg', '•Jenis: Kanji alami (Tapioka/Starch)\r\n•Takaran: 200 gram per 5 liter air\r\n•Penggunaan: 3 gram kanji untuk 80 gram benang lusi\r\n', 'Lem kanji digunakan untuk memperkuat benang lusi agar tidak mudah putus selama proses penenunan.', NULL),
(4386, 'P0006', 'Benang Lusi (Warp)', '1746978804_vg.jpg,1747038314_ffs.jpg', 'Density (kepadatan lusi): 50 benang per inci\r\nJumlah Benang Lusi: 1.375 helai (menggunakan rumus density)\r\nTakaran Benang Lusi:\r\n1.500 gram (± 1,5 kg) untuk 1 beam panjang 20 meter, jadi untuk 1 ulos (200 cm panjang x 70 cm lebar) membutuhkan 75 gram benang lusi.\r\n\r\n', 'Menjadi rangka utama kain ulos, dipasang vertikal untuk menjaga kestabilan struktur saat proses penenunan.', ' 1,5 kg'),
(4387, 'P0006', 'Benang Pakan (Weft)', '1747038314_gfbfbf.jpg', 'Hitungan Benang Pakan:\r\nDensity pakan: 45 anyaman per inci\r\nPanjang kain: 2 meter = 78,7 inci\r\nJumlah pakan = 45 × 78,7 = 3.541 sisiran pakan\r\nJumlah Benang Pakan per Warna:\r\nSetiap warna (merah, putih, kuning emas) membutuhkan sekitar 200 gram benang pakan untuk ukuran standar.\r\nJadi untuk satu ulos, kita membutuhkan 600 gram benang pakan (200 gram per warna x 3 warna).\r\n', 'Ditambahkan secara horizontal melalui benang lusi untuk membentuk motif dan pola ulos selama proses tenun.\r\n\r\n', NULL),
(4388, 'P0006', 'Pewarna Tekstil', '1747038314_dhhnddh.jpg', 'Jenis: Remazol atau Procion MX\r\nWarna: Black Deep, Scarlet Red, Bright White, Gold Yellow\r\n•Takaran Pewarna: 30 gram per 5 liter air.\r\n•Untuk pewarna benang pakan, kita akan menggunakan sekitar 20 gram pewarna per warna (merah, putih, kuning emas) untuk satu ulos.\r\n•Total Pewarna yang Dibutuhkan: 60 gram (20 gram per warna x 3 warna).\r\n', 'Digunakan sebelum penenunan untuk memberi warna pada benang agar motif ulos terlihat jelas dan menarik.', NULL),
(4389, 'P0006', 'Fixer (Penguat Warna)', '1747038314_dhhdh.jpg', 'Jenis: Sodium Carbonate (Soda Ash)\r\nTakaran: 50 gram per 5 liter air\r\nSoda Ash untuk Pewarna:\r\nKita membutuhkan sekitar 10 gram soda ash untuk pewarnaan setiap warna.\r\n', ' Dicampurkan setelah pewarnaan untuk mengunci warna agar tidak luntur saat proses pencucian dan penjemuran.', NULL),
(4390, 'P0006', 'Softener (Pelembut Kain)', '1747038314_kk.jpg', 'Jenis: Non-ionic softener\r\nTakaran Softener: 50 ml per 10 meter kain\r\nSoftener yang Dibutuhkan:\r\nUntuk 1 ulos (panjang 200 cm, lebar 70 cm), kita membutuhkan sekitar 10 ml softener.\r\n', 'Diterapkan setelah tenun selesai untuk melembutkan tekstur kain agar lebih nyaman dipakai.', NULL),
(4391, 'P0006', 'Minyak Pelumas Mesin Tekstil', '1747038314_esgets.jpg', 'Jenis: Oil textile grade ISO VG 32 atau 46', 'Melancarkan pergerakan mesin Jacquard.', NULL),
(4392, 'P0006', 'Lem Patrun Benang', '1747038314_kjdc.jpg', '•  Takaran: 200 gram kanji per 5 \r\n    liter air\r\n•  Benang yang Dikenakan Kanji: \r\n  75 gram benang lusi\r\n•  Lem Kanji yang Diperlukan:\r\n   Untuk sizing 75 gram benang \r\n   lusi, kita memerlukan sekitar 3 \r\n   gram kanji (perbandingan 200 \r\n   gram : 5 liter air).\r\n', 'Melapisi benang lusi supaya tidak gampang putus saat ditenun.', NULL),
(4393, 'P0006', 'Kain Lap Serat Halus', '1747038314_dfbfade.jpg', 'Jenis: Microfiber', 'Membersihkan alat dan mesin secara rutin', NULL),
(4404, 'P0005', 'Benang Lusi (Warp)', '1747056531_SV.jpg,1747056796_jve.jpg', 'Benang lusi adalah benang yang disusun secara membujur sebagai dasar struktur kain.\r\nJenis Benang: Kapas pintal manual atau benang kapas halus.\r\nWarna Dominan: Hitam atau biru tua.\r\nJumlah: Sekitar 80 gram per helai ulos (±200 cm x 70 cm).\r\nKepadatan: ±50–52 helai per inci.\r\n', 'Pasang benang lusi pada alat tenun secara vertikal, memastikan jaraknya seragam agar pola ulos terbentuk dengan rapi. Benang lusi akan berfungsi sebagai dasar tempat benang pakan dianyam secara horizontal.', '0,8 kg'),
(4405, 'P0005', 'Benang Pakan (Weft)', '1747056531_adjh.jpg,1747056796_hkbdhbkd.jpg,1747056883_nm xcv.jpg', 'Jenis Benang: Kapas yang telah diwarnai manual.\r\nJumlah: ±600–650 gram terdiri dari:\r\nPutih: 250 gram\r\nMerah: 250 gram\r\nKuning keemasan: 150 gram\r\nKepadatan Pakan: ±45–47 sisiran per inci.\r\n', 'Benang pakan digunakan untuk membentuk motif khas garis-garis paralel ulos Mangiring.', NULL),
(4406, 'P0005', 'Pewarna Alami', '1747056531_skjfs.jpg,1747056796_ljadhf.jpg,1747056883_qq.jpg', 'Hitam/Biru tua: Kulit kayu tarum (Indigofera tinctoria)\r\nMerah: Akar mengkudu (Morinda citrifolia)\r\nKuning: Kunyit (Curcuma longa) atau daun mangga tua', 'Pewarna alami digunakan untuk memberikan warna khas pada benang pakan.', NULL),
(4407, 'P0005', 'Penguat Warna (Mordant)', '1747056531_awffw.jpg,1747056796_vn.jpg', 'Jenis: Tawas (alum), kapur sirih, air jeruk nipis', 'Rendam benang sebelum/atau sesudah pewarnaan', NULL),
(4408, 'P0005', 'Lem Kanji', '1747056531_hdbf.jpg,1747056796_whbwe.jpg', 'Jenis: Tepung beras atau ubi kayu yang dimasak hingga mengental\r\nTakaran: ±3 gram lem untuk 80 gram benang lusi\r\n', 'Lem kanji digunakan dalam pembuatan ulos Mangiring untuk mengeraskan dan menguatkan benang lungsin agar tidak mudah putus atau kusut saat ditenun.', NULL),
(4541, 'P0010', 'Benang Lusi (Warp)', '1747318447_dfxn.jpg', 'Jenis Benang: Polyester atau campuran rayon-polyester\r\nJumlah Benang:\r\nSekitar 120 gram untuk satu ulos ukuran 200 cm x 85 cm\r\nKepadatan: 65 benang per inci\r\nFungsi: Menjadi dasar tenunan yang menopang benang pakan.\r\n', 'Direntangkan memanjang di alat tenun sebagai dasar kain, disusun sesuai pola warna, lalu dimasukkan ke sisir dan torop untuk pembentukan motif.', '1,3 kg'),
(4542, 'P0010', 'Benang Pakan (Weft)', '1747318447_sknj.jpg', 'Benang pakan membentuk pola warna-warni khas Pinucaan.\r\nJenis Benang: Polyester\r\nJumlah Benang: \r\nTotal 750 gram untuk satu ulos\r\nTerbagi menjadi:\r\nMerah: 300 gram\r\nPutih: 150 gram\r\nHitam: 200 gram\r\nKuning: 100 gram\r\nKepadatan Anyaman: 58 anyaman per inci\r\nFungsi: Membentuk kombinasi motif warna-warni Pinucaan.\r\n', 'Dimasukkan melintang secara bolak-balik di antara benang lusi untuk mengisi dan membentuk kain, mengikuti pola horizontal ulos.', NULL),
(4543, 'P0010', 'Pewarna Tekstil', '1747318447_wlfn.jpg', 'Mewarnai benang sebelum proses penenunan.\r\nJenis Pewarna: Remazol series (Remazol Red, Remazol Black, Remazol Yellow, Remazol Brilliant White)\r\nTakaran Pewarna: ➔ Setiap warna butuh 20 gram pewarna dalam 5 liter air\r\nTotal pewarna sekitar 80 gram untuk empat warna.\r\nFungsi: Memberi warna kuat dan stabil.\r\n', 'Digunakan untuk mewarnai benang sebelum ditenun, dengan cara direndam dalam larutan pewarna lalu dikeringkan.', NULL),
(4544, 'P0010', 'Fixer (Pengikat Warna)', '1747318447_flmxngfs.jpg', 'Mencegah warna luntur saat proses cuci dan pakai.\r\nJenis Fixer: Sodium Carbonate (Soda Ash)\r\nTakaran Fixer:\r\n10 gram untuk tiap warna\r\nTotal 40 gram fixer untuk satu ulos.\r\nFungsi: Mengunci warna di serat benang.\r\n', 'Dicampur dalam larutan pewarna atau digunakan setelah proses pewarnaan untuk mengunci warna agar tidak luntur saat dicuci.', NULL),
(4545, 'P0010', 'Softener (Pelembut Kain)', '1747318447_dsdhkdshb.jpg', 'Meningkatkan kenyamanan tekstur kain.\r\nJenis: Non-ionic softener\r\nTakaran: ➔ 12 ml  atau 12 gram non-ionic softener untuk satu helai ulos\r\nFungsi: Membuat kain terasa lebih lembut.\r\n', 'Digunakan setelah tenunan selesai, dicelup atau disemprotkan untuk melembutkan tekstur kain dan mengurangi kekakuan.\r\n\r\n', NULL),
(4546, 'P0010', 'Lem Kanji', '1747318447_yfjf.jpg', 'Melindungi benang lusi saat proses tenun.\r\nJenis: Kanji dari tapioka\r\nTakaran: ➔ 5 gram kanji untuk 120 gram benang lusi\r\nFungsi: Menguatkan benang dan mengurangi risiko putus.\r\n', 'Dioleskan tipis ke benang lusi sebelum ditenun untuk menguatkan dan mengeraskan benang agar tidak mudah putus saat proses tenun.', NULL),
(4559, 'P0012', 'Benang Lusi (Warp)', '1747326152_ahD\'.jpg', 'Jenis Benang: Polyester high-twist\r\nJumlah Benang:\r\n➔ 100 gram untuk ukuran standar ulos 200 cm x 75 cm\r\nKepadatan: 60 benang per inci\r\nFungsi: Memberikan kekuatan struktur ulos.\r\n', 'Benang Lusi dipersiapkan sepanjang 2,6 meter per helai dan disusun pada alat warping. Setiap benang Lusi akan direntangkan melalui alat tenun dan siap menjadi dasar untuk menenun benang Pakan.', '1,5 kg'),
(4560, 'P0012', 'Benang Pakan (Weft)', '1747326152_ahBS.jpg', 'Benang horizontal yang membentuk motif.\r\nJenis Benang: Polyester atau viscose rayon\r\nJumlah Benang: \r\n➔ Total 600 gram untuk satu ulos \r\n➔ Terbagi:\r\nHitam: 250 gram\r\nPutih: 150 gram\r\nMerah: 200 gram\r\nKepadatan Anyaman: 55 anyaman per inci\r\nFungsi: Membentuk motif bintang dan dasar ulos.\r\n', 'Benang Pakan dimasukkan secara otomatis ke dalam alat tenun, bergerak dari kiri ke kanan dan sebaliknya. Pada setiap beberapa sisipan benang Pakan, motif warna seperti merah, putih, emas, hijau, dan biru akan dimasukkan sesuai dengan pola bintang yang telah disusun.', NULL),
(4561, 'P0012', 'Pewarna Tekstil', '1747326152_aefjkjb.jpg', 'Memberi warna sebelum benang digunakan.\r\nJenis Pewarna: Procion MX series\r\nTakaran Pewarna: \r\n➔ 15 gram per warna dalam 5 liter air \r\n➔ Total 45 gram pewarna untuk tiga warna.\r\n', 'Benang-benang yang akan digunakan untuk motif (misalnya benang Pakan dan Benang Lusi) dicelupkan ke dalam larutan pewarna tekstil sebelum digunakan. Warna yang dihasilkan akan tetap tahan lama dan cerah sepanjang proses pembuatan tenunan.', NULL),
(4562, 'P0012', 'Fixer (Pengikat Warna)', '1747326152_flmxngfs.jpg', 'Untuk menjaga warna tetap stabil.\r\nJenis Fixer: Sodium Carbonate (Soda Ash)\r\nTakaran Fixer: \r\n➔ 8 gram per warna\r\n➔ Total 24 gram fixer.\r\n', 'Setelah benang dicelupkan dalam pewarna, benang tersebut direndam dalam larutan fixer selama beberapa waktu untuk memastikan warna menempel dengan kuat pada benang dan tidak mudah luntur saat dicuci atau digunakan.', NULL),
(4563, 'P0012', 'Softener (Pelembut Kain)', '1747326152_dsdhkdshb.jpg', 'Meningkatkan kenyamanan tekstur kain.\r\nJenis: Non-ionic softener\r\nTakaran: ➔ 10 ml softener untuk satu ulos ukuran standart atau 10 gram\r\n', 'Setelah proses penenunan selesai, kain yang telah selesai ditenun dicelupkan atau dilapisi dengan larutan softener. Hal ini membuat kain menjadi lebih halus dan nyaman dipakai, serta memberikan kilau alami pada kain.', NULL),
(4564, 'P0012', 'Lem Kanji', '1747326152_Picture7.jpg', 'Untuk memperkuat benang lusi.\r\nJenis: Kanji alami dari tepung tapioka\r\nTakaran: \r\n➔ 4 gram kanji untuk 100 gram benang lusi.\r\n', 'Lem Kanji dicampurkan dengan air dan kemudian diterapkan pada benang Pakan atau Benang Lusi yang akan digunakan dalam proses menenun. Setelah itu, benang dipegang dalam posisi yang diinginkan selama proses tenun, memberikan hasil yang lebih rapi dan terstruktur.', NULL),
(4575, 'P0011', 'Benang Lusi (Warp)', '1747323162_ahawj.jpg', 'Jenis Benang: Kapas alami, umumnya berwarna hitam atau gelap\r\nJumlah: ±75 gram per helai ulos Lobu-Lobu (±200 cm x 70 cm)\r\nKepadatan: ±50 helai per inci\r\n\r\n', 'Digunakan sebagai benang vertikal yang disusun dalam alat tenun, berfungsi sebagai dasar bagi benang pakan yang akan disisipkan.', '0,5 kg'),
(4576, 'P0011', 'Benang Pakan (Weft)', '1747323162_jgdvf.jpg', 'Benang pakan digunakan untuk memberikan warna dan motif pada kain ulos Lobu-Lobu.\r\nJenis Benang: Kapas alami yang telah diwarnai secara tradisional\r\nJumlah: ±600 gram terdiri dari:\r\nMerah: 250 gram\r\nPutih: 150 gram\r\nKuning: 200 gram\r\nKepadatan Pakan: ±45 sisiran per inci\r\n', 'Digunakan untuk disisipkan secara horizontal di antara benang lusi, membentuk pola dan motif pada kain.\r\n\r\n', NULL),
(4577, 'P0011', 'Pewarna Alami', '1747323162_aekhgf.jpg', 'Pewarna alami yang digunakan untuk memberikan warna pada benang pakan ulos Lobu-Lobu.\r\nJenis Pewarna & Sumber:\r\nMerah: Akar mengkudu (Morinda citrifolia).\r\nKuning: Kunyit (Curcuma longa).\r\nPutih: Kapur sirih.\r\n\r\n', 'Rebus bahan pewarna selama ±1 jam untuk membuat ekstrak pewarna.\r\nRendam benang dalam larutan pewarna selama 30 menit hingga warna meresap.\r\nJemur benang di tempat teduh agar warnanya tetap kuat dan tahan lama.\r\n', NULL),
(4578, 'P0011', 'Penguat Warna (Mordant)', '1747323162_kgadf.jpg', 'Digunakan untuk memastikan warna lebih stabil dan tidak mudah luntur.\r\nJenis: Tawas (alum)\r\nPenggunaan: Campurkan tawas dalam air, rendam benang selama 30 menit\r\n', 'Digunakan dengan merendam benang dalam larutan tanin atau gambir sebelum pewarnaan untuk mengikat dan memperkuat warna pada benang agar lebih tahan lama.\r\n\r\n', NULL),
(4579, 'P0011', 'Lem Kanji', '1747323162_dehdesej.jpg', 'Digunakan untuk memperkuat benang lusi agar tidak mudah putus selama proses penenunan.\r\nJenis: Tepung beras atau tepung singkong (ubi kayu)\r\nTakaran: 3 gram lem untuk setiap 75 gram benang lusi\r\n\r\n', 'Digunakan untuk melapisi benang, memberi kekuatan dan keteguhan pada benang, agar lebih mudah ditenun dan menghasilkan ulos yang lebih kokoh.', NULL),
(4590, 'P0009', 'Benang Lusi (Warp)', '1747313731_jve.jpg', 'Jenis Benang: Kapas alami berwarna dasar hitam pekat atau biru tua (tergantung wilayah)\r\nJumlah: ±85 gram per helai ulos Simarinjam Sisi (±220 cm x 70 cm)\r\nKepadatan: ±54 helai per inci\r\n', 'igunakan dengan direntangkan memanjang di alat tenun sebagai dasar rangka kain; benang ini diatur ketegangannya agar seimbang dan tidak kusut, lalu dipasang pada sisir dan penggulung lusi untuk membentuk pola dasar ulos.', '0,9 kg'),
(4591, 'P0009', 'Benang Pakan (Weft)', '1747313731_nm xcv.jpg,1747314660_djdgf.jpg,1747314759_djhfv.jpg,1747314802_adejfdjafv.jpg', 'Benang pakan membentuk motif garis-garis rapi simetris di kedua sisi kain, yang menjadi ciri khas dari nama \"simarinjam sisi\" (berpelukan dari sisi ke sisi).\r\nJenis Benang: Benang kapas alami, diwarnai tradisional\r\nJumlah: ±680 gram terdiri dari:\r\nMerah Tua: 280 gram\r\nPutih/Krem: 200 gram\r\nHitam/Coklat Tua: 200 gram\r\nKepadatan Pakan: ±48 sisiran per inci\r\n', 'dimasukkan secara horizontal melalui celah-celah benang lusi menggunakan alat bantu seperti torak atau kayu suat, ditenun bolak-balik sambil mengikuti motif tertentu sesuai desain Simarinjam Sisi.', NULL),
(4592, 'P0009', 'Pewarna Alami', '1747313731_hkdfshbkdfhbk.jpg,1747314660_xvbcx.jpg,1747314759_smcvnb.jpg', 'Pewarna alami digunakan untuk memberikan warna kuat dan tahan lama, khususnya warna-warna yang kontras namun harmonis.\r\nJenis Pewarna & Sumber:\r\nMerah Tua: Akar mengkudu matang\r\nHitam/Coklat: Daun tarum (Indigofera tinctoria), kulit jambal\r\nPutih/Krem: Kapur sirih dan bahan pemucat alami\r\n', 'Rebus akar/kulit pewarna selama ±1,5 jam\r\nRendam benang ±1 jam hingga warna meresap\r\nJemur benang di tempat teduh ±6 jam untuk menjaga kestabilan warna\r\n', NULL),
(4593, 'P0009', 'Penguat Warna (Mordant)', '1747313731_dbksd.jpg,1747314660_sdjhc.jpg', 'Tawas (alum), kadang dicampur air abu', 'Direndam 30–40 menit sebelum pewarnaan untuk membantu mengikat warna lebih kuat ke serat benang', NULL),
(4594, 'P0009', 'Lem Kanji', '1747313731_dehdesej.jpg,1747314660_yfjf.jpg', 'Digunakan untuk memperkuat benang lusi agar tidak mudah putus saat proses tenun.\r\nJenis: Kanji dari tepung ubi kayu\r\nTakaran: ±3 gram lem untuk setiap 85 gram benang lusi\r\n\r\n', 'digunakan dengan cara melarutkannya dalam air panas lalu mengoleskannya tipis pada benang lusi sebelum proses penenunan agar benang lebih kuat, kaku, dan tidak mudah putus saat ditenun.', NULL),
(4613, 'P0008', 'Benang Lusi (Warp)', '1747302272_SV.jpg', 'Benang lusi adalah benang yang memanjang vertikal dan menjadi kerangka dasar kain.\r\nJenis Benang: Polyester atau campuran polyester-rayon\r\nJumlah Benang:\r\n➔ Sekitar 100 gram untuk satu ulos ukuran standar 200 cm x 80 cm\r\nKepadatan: 60 benang per inci\r\nFungsi: Menjadi kerangka dasar untuk anyaman ulos.\r\n', 'Dalam pembuatan Ulos Sibolang Modern, benang lusi disiapkan dengan panjang 260 cm per helai (200 cm panjang kain + 2 × 30 cm cadangan). Jumlah benang lusi disesuaikan dengan lebar kain, misalnya 900 helai untuk lebar 90 cm. Benang lusi ini kemudian dipasang pada mesin tenun dengan bantuan mesin warping otomatis, memastikan ketegangan benang stabil dan posisi motif tepat.', '0,8 kg'),
(4614, 'P0008', 'Benang Pakan (Weft)', '1747302272_nm xcv.jpg', 'Benang pakan menyilang horizontal untuk membentuk motif kotak-kotak Sibolang.\r\nJenis Benang: Polyester\r\nJumlah Benang:\r\n➔ Total 600 gram untuk satu ulos\r\n➔ Terdiri dari dua warna utama (misal: hitam dan putih), masing-masing 300 gram.\r\nKepadatan Anyaman: 55 anyaman per inci\r\nFungsi: Membuat pola kotak-kotak khas ulos Sibolang.\r\n', 'Benang pakan dimasukkan secara otomatis oleh sistem shuttle pada mesin tenun Jacquard semi-digital. Dalam proses ini, setiap 50 baris benang pakan, mesin menyisipkan motif warna khas Sibolang (1 baris putih, 1 baris biru, 1 baris putih) sesuai pola digital yang diprogram.', NULL),
(4615, 'P0008', 'Pewarna Tekstil', '1747302272_ddcsdhbk.jpg', 'Digunakan untuk mewarnai benang pakan sebelum proses tenun.\r\nJenis Pewarna: Remazol Black B dan Remazol Brilliant White\r\nTakaran Pewarna:\r\n ➔ 20 gram pewarna hitam dan 15 gram pewarna putih\r\n➔ Dilarutkan dalam 5 liter air per warna.\r\nFungsi: Memberi warna kuat dan tahan lama pada benang.\r\n', 'Pewarnaan dilakukan sebelum proses penenunan. Benang putih diwarnai menggunakan pewarna sintetis untuk memperoleh warna hitam pekat sebagai dasar Ulos Sibolang. Pewarnaan dilakukan dengan merendam benang dalam larutan pewarna pada suhu dan waktu tertentu, kemudian dikeringkan sebelum digunakan dalam proses penenunan.', NULL),
(4616, 'P0008', 'Fixer (Pengikat Warna)', '1747302272_hbkdfvs.jpg', 'Untuk mengunci warna pewarnaan benang.\r\nJenis Fixer: Sodium Carbonate (Soda Ash)\r\nTakaran Fixer: ➔ 8 gram per warna\r\nFungsi: Agar warna tidak cepat luntur.\r\n', 'Setelah proses pewarnaan, benang direndam dalam larutan fixer selama waktu tertentu untuk memastikan warna menempel dengan kuat pada serat. Proses ini penting untuk menjaga ketahanan warna Ulos Sibolang, terutama saat pencucian atau pemakaian.', NULL),
(4617, 'P0008', 'Softener (Pelembut Kain)', '1747302272_dsdhkdshb.jpg', 'Agar ulos terasa lembut saat disentuh.\r\nJenis: Non-ionic softener\r\nTakaran: ➔ 10 ml untuk satu helai ulos\r\nFungsi: Membuat hasil akhir kain lebih nyaman.\r\n', 'Setelah proses penenunan dan pencucian, kain direndam dalam larutan softener untuk memberikan kelembutan tambahan. Proses ini dilakukan sebelum pengeringan dan penyetrikaan, memastikan Ulos Sibolang nyaman dipakai dan memiliki tekstur yang halus.', NULL),
(4618, 'P0008', 'Lem Kanji', '1747302272_fyh.jpg', 'Untuk menguatkan benang lusi saat proses penenunan.\r\nJenis: Kanji dari tapioka\r\nTakaran: ➔ 4 gram kanji untuk 100 gram benang lusi\r\nFungsi: Mencegah benang lusi mudah putus saat proses penenunan.\r\n', 'Sebelum benang lusi dipasang pada mesin tenun, benang direndam dalam larutan lem kanji dan kemudian dikeringkan. Proses ini membantu menjaga ketegangan benang dan mencegah kerusakan selama penenunan. Setelah penenunan selesai, sisa lem kanji dihilangkan melalui pencucian.\r\n\r\n', NULL),
(4629, 'P0007', 'Benang Pakan (Weft)', '1747283525_jgdvf.jpg,1747313913_dfshjfshbjs.jpg,1747314015_nm xcv.jpg,1747314169_fhfh.jpg', 'Jenis Benang: Kapas alami yang telah diwarnai secara tradisional\r\nJumlah: ±720 gram terdiri dari:\r\nMerah Bata: 300 gram\r\nCoklat Tua: 200 gram\r\nPutih/Krem: 120 gram\r\nHitam Tua: 100 gram\r\nKepadatan Pakan: ±50 sisiran per inci\r\n', 'disisipkan melintang ke dalam benang lungsi menggunakan sekoci saat menenun. Gunakan benang hitam untuk dasar, dan selipkan benang merah-putih setiap 60 baris untuk membentuk motif Ragi Pakko di tengah dan sisi kain.', '1,5 Kg'),
(4630, 'P0007', 'Pewarna Alami', '1747283525_dfshkgfes.jpg,1747314015_cbcbc.jpg,1747314169_sdfse.jpg,1747314417_mdbsdfn.jpg', 'Merah Bata: Akar mengkudu (Morinda citrifolia)\r\nHitam: Daun tarum (Indigofera tinctoria) & kulit pohon jambal\r\nCoklat: Kulit pohon jabi dan biji pinang\r\nPutih: Pewarna alami dari kapur sirih\r\n', 'Proses Pewarnaan:\r\n1.Rebus bahan pewarna selama \r\n   1,5–2 jam hingga larutan pekat\r\n2.Rendam benang selama ±1 jam \r\n   dalam larutan hangat\r\n3.Keringkan di tempat teduh ±6–8 \r\n   jam\r\n', NULL),
(4631, 'P0007', 'Penguat Warna (Mordant)', '1747283525_mnvbnjvb.jpg,1747314015_etyteye.jpg', 'Jenis: Tawas (alum) dan abu dapur (untuk warna gelap)', 'Rendam benang ±30–45 menit sebelum pewarnaan untuk mempertahankan daya lekat warna', NULL),
(4632, 'P0007', 'Lem Kanji', '1747283525_vnbvnbn.jpg', 'Jenis: Kanji dari tepung ubi kayu atau sagu\r\nTakaran: ±4 gram lem kanji untuk setiap 90 gram benang lusi\r\n', 'dioleskan ke benang lungsi setelah disusun, sebelum ditenun. Fungsinya untuk menguatkan benang agar tidak kusut atau putus saat proses tenun, lalu dibiarkan kering sebelum dipasang ke alat tenun.', NULL),
(4633, 'P0007', 'Benang Lusi (Warp)', '1747283525_jve.jpg,1747313913_adhkdfeshk.jpg', 'Jenis Benang: Benang kapas alami, dipintal secara manual, berwarna dasar hitam pekat\r\nJumlah: ±90 gram per helai ulos Ragi Pakko (±230 cm x 70 cm)\r\nKepadatan: ±56 helai per inci\r\n', 'disusun secara vertikal sebagai dasar tenunan dan direntangkan pada alat tenun. Setelah disusun sesuai pola warna (hitam, putih, merah), benang lusi dilumuri lem kanji agar kuat, lalu dikeringkan dan dimasukkan satu per satu ke sisorhon dan torop sebelum proses menenun dimulai.', NULL),
(4634, 'P0001', 'Benang Lusi (Warp)', '1746453150_ehkfe.jpg', '•Jenis Benang Lusi: Benang kapas asli, dipintal manual atau benang kapas lokal yang tidak diproses secara kimia.\r\n•Jumlah Benang Lusi: Untuk satu ulos Ragihidup standar (±200 cm x 70 cm), dibutuhkan ±85 gram benang lusi.\r\n•Kepadatan: ±48 benang per inci, menghasilkan tenunan yang kuat namun tetap fleksibel.\r\n', 'Benang lusi berperan sebagai struktur utama ulos, membujur vertikal, dirangkai dengan ketelitian tinggi.', '0,685 kg'),
(4635, 'P0001', 'Benang Pakan (Weft)', '1746453150_hr.jpg', '•	Jenis Benang Pakan: Benang kapas alami, diwarnai dengan pewarna alami.\r\n•	Jumlah Benang Pakan: Sekitar 600 gram untuk satu helai ulos, terdiri dari 4 warna utama: merah darah, hitam pekat, putih alami, dan kuning keemasan.\r\n•	Kepadatan Pakan: ±42 sisiran per inci, total sekitar 3.300 sisiran sepanjang kain.\r\n', 'Benang pakan membentuk motif Ragihidup yang kompleks dan bermakna filosofis.', NULL),
(4636, 'P0001', 'Pewarna Alami', '1746453276_vg.jpg,1746453298_xvbcx.jpg,1746453321_cvcbc.jpg,1746453362_ffh.jpg', '•Sumber Warna:\r\n  oMerah darah: Kulit kayu jabi-jabi\r\n  oHitam: Tanah liat besi (lumpur khusus) dan daun tarum\r\n  oPutih: Warna kapas alami tanpa pewarnaan\r\n  oKuning emas: Ekstrak kunyit atau kulit pohon mangga muda', 'ozSetiap warna memerlukan perendaman dan penjemuran berulang 3–6 kali untuk hasil optimal.', NULL),
(4637, 'P0001', 'Penguat Warna Tradisional', '1746453436_dfgd.jpg,1746453516_654775cb4548a.jpeg,1746453587_719112138.jpg', '•Bahan: Abu dapur, air jeruk nipis, dan air kapur sirih.', 'Membantu mempertahankan daya lekat pewarna alami pada serat benang.', NULL),
(4638, 'P0001', 'Lem Kanji Alami', '1746453639_fyh.jpg', '•Jenis: Kanji dari tepung ubi kayu (tapioka) atau beras.\r\n•Takaran: ±180 gram kanji untuk 5 liter air.\r\n', 'Digunakan saat persiapan benang lusi, membuat benang kuat namun tetap lentur.', NULL),
(4659, 'P0013', 'Benang Lusi (Warp)', '1748066726_adc.jpg', 'Jenis Benang: Kapas alami berwarna dasar merah hati atau coklat gelap\r\nJumlah: ±80 gram per helai ulos Suri-Suri Nganjang (±210 cm x 75 cm)\r\nKepadatan: ±52 helai per inci\r\n', 'Disusun memanjang sebanyak ±950 helai, dimasukkan ke sisir tenun (sisorhon), lalu diikat ke alat tenun sebagai kerangka dasar. Warna hitam dengan selipan merah-putih untuk motif.', '0,7 Kg'),
(4660, 'P0013', 'Benang Pakan (Weft)', '1748066726_jgdvf.jpg', 'Benang pakan digunakan untuk membentuk motif khas dan garis-garis halus pada kain ulos Suri-Suri Nganjang.\r\nJenis Benang: Kapas alami yang telah diwarnai secara tradisional\r\nJumlah: ±650 gram terdiri dari:\r\nMerah Tua: 300 gram\r\nPutih: 180 gram\r\nHitam: 170 gram\r\nKepadatan Pakan: ±47 sisiran per inci\r\n', 'Disisipkan melintang memakai sekoci saat menenun, dari kanan ke kiri secara bergantian, sambil ditekan dengan baliga agar rapat.', NULL),
(4661, 'P0013', 'Pewarna Alami', '1748066726_aekhgf.jpg', 'Pewarna alami digunakan untuk memberikan warna pada benang pakan ulos Suri-Suri Nganjang.\r\nJenis Pewarna & Sumber:\r\nMerah Tua: Akar mengkudu matang (Morinda citrifolia) dan kulit kayu jabi-jabi\r\nPutih: Kapur sirih\r\nHitam: Kulit pohon jambal dan daun tarum (Indigofera tinctoria)\r\n', 'Rebus bahan pewarna selama ±1,5 jam untuk menghasilkan larutan pewarna.\r\nRendam benang dalam larutan selama 45 menit agar warna meresap sempurna.\r\nJemur benang di tempat teduh dan sejuk agar warna tidak cepat pudar.\r\n', NULL),
(4662, 'P0013', 'Penguat Warna (Mordant)', '1748066726_adnd.jpg', 'Digunakan untuk memastikan warna benang tidak mudah luntur.\r\n•	Jenis: Tawas (alum)\r\n•	Penggunaan: Campurkan tawas dalam air, lalu rendam benang selama 30–40 menit sebelum proses pewarnaan.\r\n', 'Benang direndam dalam larutan tawas atau kapur sebelum/ sesudah pewarnaan untuk menjaga warna agar tidak mudah luntur.', NULL),
(4663, 'P0013', 'Lem Kanji', '1748066726_dehdesej.jpg', 'Digunakan untuk memperkuat benang lusi agar tidak mudah putus selama proses penenunan.\r\nJenis: Tepung singkong (ubi kayu)\r\nTakaran: 3,5 gram lem untuk setiap 80 gram benang lusi\r\n', 'Diusapkan ke benang lusi sebelum ditenun, lalu dijemur setengah kering agar benang lebih kuat dan tidak mudah putus saat digunakan.', NULL),
(4706, 'P0016', 'Benang Lusi (Warp)', '1748083087_uksddf.jpg', 'Jenis: Polyester atau campuran rayon-polyester\r\nJumlah: ±85 gram untuk ukuran 200 cm x 70 cm\r\nKepadatan: 52 benang per inci\r\nFungsi: Membentuk struktur dasar ulos\r\n', 'digunakan sebagai benang utama yang dipasang secara memanjang pada alat tenun; berfungsi sebagai kerangka dasar tenunan dan penopang struktur kain.', '0,5 Kg'),
(4707, 'P0016', 'Benang Pakan (Weft)', '1748083087_hjv.jpg', 'Jenis: Polyester\r\nJumlah: ±580 gram (2 warna utama: biru tua dan putih)\r\nBiru tua: 400 gram\r\nPutih: 180 gram\r\nKepadatan: 48 anyaman per inci\r\nFungsi: Membentuk pola garis sejajar khas Tumtuman\r\n', ' digunakan sebagai benang yang ditenun secara melintang melalui benang lusi; berfungsi membentuk isi kain serta motif ulos.\r\n\r\n', NULL),
(4708, 'P0016', 'Pewarna Tekstil', '1748083087_bmv.jpg', 'Jenis: Remazol Blue RR, Remazol Brilliant White\r\nTakaran: 25 gram per warna (total 50 gram) dalam 5 liter air\r\nFungsi: Mewarnai benang pakan\r\n', 'digunakan untuk memberi warna pada benang atau kain ulos; berfungsi menciptakan motif dan kombinasi warna khas ulos Tumtuman modern.', NULL),
(4709, 'P0016', 'Fixer (Pengikat Warna)', '1748083087_sddfb.jpg', 'Jenis: Sodium Carbonate (Soda Ash)\r\nTakaran: 8 gram per warna (total 16 gram)\r\nFungsi: Mengikat warna agar tidak mudah luntur\r\n', 'digunakan setelah proses pewarnaan; berfungsi mengikat warna agar tidak luntur saat dicuci atau terkena sinar matahari.', NULL),
(4710, 'P0016', 'Softener (Pelembut Kain)', '1748083087_hdadbdf.jpg', 'Jenis: Non-ionic softener\r\nTakaran: 10 ml per helai ulos\r\nFungsi: Menjadikan kain lebih lembut dan nyaman\r\n', 'digunakan pada tahap akhir setelah pencucian; berfungsi membuat kain ulos lebih halus, lentur, dan nyaman disentuh.', NULL),
(4711, 'P0016', 'Lem Kanji', '1748083087_sdfmb.jpg', 'Jenis: Kanji dari tapioka\r\nTakaran: 4 gram untuk 85 gram benang lusi\r\nFungsi: Memperkuat benang saat penenunan\r\n', 'digunakan saat proses penegangan benang lusi sebelum ditenun; berfungsi menguatkan benang agar tidak mudah putus dan hasil tenun menjadi lebih rapi dan padat.', NULL),
(4716, 'P0015', 'Benang Lusi (Warp)', '1748079611_ahawj.jpg', 'Jenis: Benang kapas alami berwarna dasar coklat tua atau hitam pekat\r\nJumlah: ±85 gram per helai ulos Antak-Antak (±220 cm x 70 cm)\r\nKepadatan: ±50 helai per inci\r\nJenis: Benang kapas alami berwarna dasar coklat tua atau hitam pekat\r\nJumlah: ±85 gram per helai ulos Antak-Antak (±220 cm x 70 cm)\r\nKepadatan: ±50 helai per inci\r\n', 'Rentangkan benang lusi secara vertikal di alat tenun, lalu kencangkan dengan tarikan seragam.', '1,8 Kg'),
(4717, 'P0015', 'Benang Pakan (Weft)', '1748079611_kbd.jpg', 'Digunakan untuk membentuk corak rumit khas Ulos Antak-Antak.\r\nJenis: Benang kapas yang diwarnai tradisional dan dipilin rapat\r\nJumlah Total: ±670 gram\r\nCoklat Tua: 320 gram.\r\nAbu-abu: 190 gram.\r\nHitam: 160 gram.\r\nKepadatan Pakan: ±45 sisiran per inci\r\n', 'Sisipkan benang pakan berwarna secara horizontal melewati benang lusi, lalu tekan dengan torak untuk membentuk pola antak-antak.', NULL),
(4718, 'P0015', 'Pewarna Alami', '1748079611_khad.jpg', 'Coklat Tua: Kulit pohon nangka & akar jernang\r\nAbu-Abu: Serbuk batu lempung halus & air besi\r\nHitam: Daun tarum (Indigofera) & kulit jambal\r\n', 'Proses Pewarnaan:\r\nRebus bahan selama ±2 jam untuk hasil pekat\r\nRendam benang selama 1 jam dalam larutan pewarna\r\nJemur benang di tempat sejuk agar warna awet\r\n', NULL),
(4719, 'P0015', 'Penguat Warna (Mordant)', '1748079611_dehdesej.jpg', 'Jenis: Tawas dan larutan air kapur\r\nPenggunaan: Rendam benang dalam larutan selama 30–45 menit sebelum pewarnaan\r\n', 'Rendam benang yang sudah diwarnai dalam larutan tawas selama 1 jam, bilas, lalu keringkan.', NULL),
(4726, 'P0014', 'Benang Lusi (Warp)', '1748075384_uksddf.jpg', 'Polyester atau campuran polyester-rayon\r\nJumlah: Sekitar 85 gram untuk ukuran 200 cm x 70 cm\r\nKepadatan: 52 benang per inci\r\nFungsi: Struktur dasar ulos\r\n', 'Disiapkan 900 helai (misalnya hitam dasar + selipan putih/ungu/biru).\r\nDipotong sepanjang 2,6 m, dilapisi lem kanji, lalu dimasukkan ke sisir (sisorhon) dan torop via warping machine.\r\n\r\n', '0,5 Kg'),
(4727, 'P0014', 'Benang Pakan (Weft)', '1748075384_khagd.jpg', 'Polyester\r\nJumlah: Sekitar 580 gram (3 warna utama: hijau daun, kuning keemasan, hitam)\r\nHijau: 250 gram\r\nKuning: 180 gram\r\nHitam: 150 gram\r\nKepadatan: 48 anyaman per inci\r\n', 'Dimasukkan otomatis menggunakan shuttle di mesin Jacquard.\r\nBenang pakan utama hitam, diseling warna ungu/putih/biru tiap pola sisipan untuk motif khas Mangiring.', NULL),
(4728, 'P0014', 'Pewarna Tekstil', '1748075384_khkgdf.jpg', 'Jenis: Remazol Green, Remazol Yellow, Remazol Black\r\nTakaran: 20 gram per warna (total 60 gram) dalam 5 liter air\r\n', 'Benang dicelup dalam larutan pewarna sintetis atau alami (warna stabil dan tajam).\r\nProses pencelupan dilakukan dengan mesin pewarna otomatis agar merata dan konsisten.\r\n\r\n', NULL),
(4729, 'P0014', 'Fixer (Pengikat Warna)', '1748075384_hkdgdfa.jpg', 'Jenis: Sodium Carbonate (Soda Ash)\r\nTakaran: 8–10 gram per warna (total 24–30 gram)\r\nFungsi: Mengikat pewarna pada serat benang\r\n', 'Setelah pewarnaan, benang direndam dalam larutan fixer (biasanya cationic atau resin-based) selama ±30 menit.\r\nKemudian dikeringkan sebelum masuk ke proses winding atau penenunan.', NULL),
(4730, 'P0014', 'Softener (Pelembut Kain)', '1748075384_hgadf.jpg', 'Jenis: Non-ionic softener\r\nTakaran: 10 ml per helai ulos\r\nFungsi: Meningkatkan kelembutan kain\r\n', 'Setelah kain selesai ditenun dan dijemur, disemprot atau direndam dalam larutan softener.\r\nLalu dikeringkan kembali dan dipress menggunakan steam press agar kain lebih halus dan jatuh.\r\n\r\n', NULL),
(4731, 'P0014', 'Lem Kanji', '1748075384_hdbf.jpg', 'Jenis: Kanji dari tapioka\r\nTakaran: 4 gram untuk 85 gram benang lusi\r\nFungsi: Memperkuat benang saat ditenun\r\n', 'Larutan kanji disiapkan (misal: 10% tepung tapioka + air panas).\r\nDioleskan atau disemprot ke benang lusi sebelum warping, lalu dikeringkan menggunakan pengering otomatis.', NULL),
(4752, 'P0002', 'Benang Lusi (Warp)', '1745894934_efea.jpg', '•Jenis Benang Lusi: Kapas alami yang dipintal sendiri atau benang kapas lokal\r\n•Jumlah Benang Lusi: Untuk satu ulos Ragihotang ukuran standar (±200 cm x 70 cm), dibutuhkan ±80 gram benang lusi.\r\n•Kepadatan: Sekitar 45 benang per inci, lebih longgar dibanding ulos modern untuk mempertahankan fleksibilitas kain\r\n', 'Dipasang membujur di alat tenun dengan kondisi tegang sebagai kerangka dasar kain.', ''),
(4753, 'P0002', 'Benang Pakan (Weft)', '1745894934_hr.jpg', '•Jenis Benang Pakan: Kapas alami berwarna, kadang dipadukan dengan serat tanaman lokal\r\n•Jumlah Benang Pakan: Total sekitar 550 gram untuk satu helai ulos, terdiri dari kombinasi warna merah tua (dominan), putih alami, dan aksen kuning keemasan.\r\n•Kepadatan Pakan: Sekitar 40 sisiran per inci, menghasilkan ±3.150 sisiran total sepanjang kain.\r\n', 'Disisipkan melintang di antara benang lusi menggunakan alat bantu seperti torop untuk membentuk motif.', NULL),
(4754, 'P0002', 'Pewarna Alami', '1745894934_sfs.jpg', '•Jenis Pewarna: Pewarna alami tradisional\r\noMerah: Getah pohon mangsi atau kulit kayu jabi-jabi\r\noHitam: Lumpur khusus (tanah besi) dan rendaman daun tarum\r\noKuning: Ekstrak kunyit atau kulit pohon mangga', 'oPewarnaan berlapis hingga mencapai ketajaman warna yang diinginkan.\r\noSetiap sesi pewarnaan bisa memakan waktu 1–2 hari untuk satu warna.\r\n', NULL),
(4755, 'P0002', '. Penguat Benang', '1745894934_fh.jpg', '1 liter air + 2–3 sendok makan kanji (tepung beras atau tepung kanji).', 'Dioleskan atau direndamkan pada benang untuk memperkuat dan mencegah putus saat penenunan.', NULL),
(4756, 'P0002', 'Lem Kanji Alami', '1745894934_fyh.jpg', '•Jenis: Kanji dari beras atau ubi kayu\r\n•Takaran: ±150 gram kanji alami untuk 5 liter air.\r\n', 'Dicelupkan ke benang untuk membuatnya lebih kaku dan rapi saat ditenun.', NULL);
INSERT INTO `produk_hotspots` (`id`, `kode_produk`, `material_photo_id`, `x_position`, `y_position`, `judul`, `deskripsi`, `jenis`) VALUES
(46, 'P0001', NULL, '51%', '58%', ' Motif Tengah Bergelombang Warna Biru Kehijauan', 'Menyimbolkan aliran kehidupan, seperti air atau udara. Motif ini disebut “ragidup” karena menggambarkan denyut kehidupan dan keseimbangan batin. Cocok sebagai lambang doa agar hidup panjang dan penuh makna.', NULL),
(47, 'P0001', NULL, '97%', '41%', 'Jahitan Tepi Halus (Outline Ulos)', 'Jahitan ini menjaga bentuk dan keutuhan ulos. Dalam filosofi Batak, ini simbol dari adat yang membingkai hidup manusia, menjaga supaya tidak lepas dari norma dan nilai budaya.\r\n', NULL),
(48, 'P0001', NULL, '49%', '38%', 'Motif Serat Halus Horizontal di Tengah', 'Ini menunjukkan benang-benang kehidupan yang saling terhubung. Dalam adat Batak, ini berarti hubungan antar manusia (partuturan) — harapan akan silaturahmi dan solidaritas keluarga besar.', NULL),
(49, 'P0001', NULL, '22%', '35%', ' Garis-Garis Putih Vertikal (Tiga Garis di Setiap Sisi Tengah)', 'Mewakili struktur adat dan tahapan kehidupan. Tiga garis sering dimaknai sebagai simbol lahir, hidup, dan mati, atau nilai dasar dalam keluarga Batak ', NULL),
(50, 'P0001', NULL, '91%', '50%', 'Bidang Samping Warna Merah Maroon', 'Simbol kasih sayang, keberanian, dan kekuatan. Warna merah dalam ulos Batak biasanya melambangkan semangat orang tua terhadap anak, dan sering digunakan dalam pemberian ulos saat acara pernikahan.\r\n\r\n', NULL),
(51, 'P0001', NULL, '48%', '4%', ' Ujung Ulos dengan Rumbai (Atas & Bawah)', 'Rumbai atau ujung anyaman ini bermakna kelanjutan hidup dan harapan ke depan. Biasanya, semakin rapi rumbainya, makin dihargai kain itu. Kadang dianggap jalur berkat dan doa bagi penerima ulos.', NULL),
(59, 'P0002', NULL, '24%', '49%', 'Warna Dasar Merah', 'warna merah yang dominan melambangkan keberanian, kekuatan, dan vitalitas. Dalam konteks kehidupan, ini bisa diartikan sebagai semangat hidup, energi, dan tekad.', NULL),
(60, 'P0002', NULL, '54%', '61%', 'Garis Horizontal Berwarna Emas/Kuning Keemasan', 'Garis berwarna emas atau kuning keemasan seringkali diasosiasikan dengan kemuliaan, kekayaan, dan keagungan. Dalam konteks sosial dan adat, warna ini bisa melambangkan status sosial yang tinggi, kehormatan, dan berkat kemakmuran. Hadirnya garis ini dalam Ulos Ragihotang mungkin mengindikasikan harapan akan kehidupan yang sejahtera dan penuh kehormatan bagi pemakainya.', NULL),
(61, 'P0002', NULL, '45%', '58%', 'Garis Horizontal Berwarna Ungu', 'Warna ungu sering dikaitkan dengan kemewahan, spiritualitas, dan kebijaksanaan. Sementara merah muda bisa melambangkan kelembutan, kasih sayang, dan kebahagiaan. Kombinasi warna ini dalam motif horizontal bisa merepresentasikan harapan akan kehidupan yang harmonis, penuh cinta kasih, dan memiliki kedalaman spiritual.\r\n\r\n', NULL),
(62, 'P0002', NULL, '61%', '40%', 'Garis Horizontal Berwarna Oranye/Kuning', 'Warna oranye seringkali melambangkan antusiasme, kreativitas, dan kehangatan. Warna kuning, selain kemuliaan, juga bisa berarti kecerahan, kegembiraan, dan harapan. Garis-garis berwarna ini mungkin menambahkan dimensi optimisme dan semangat dalam menjalani kehidupan.', NULL),
(63, 'P0002', NULL, '40%', '48%', 'Garis Vertikal Tipis Berwarna Gelap', 'Garis-garis vertikal yang membagi bidang merah bisa melambangkan struktur, keteraturan, dan hubungan antar elemen. Fungsinya sebagai pemisah dan penegas motif horizontal mungkin mengisyaratkan pentingnya menjaga keseimbangan dan harmoni dalam berbagai aspek kehidupan.', NULL),
(64, 'P0002', NULL, '61%', '96%', 'Rumbai (Jumbai) Berwarna Putih', 'Rumbai berwarna putih seringkali melambangkan kesucian, kebersihan, dan awal yang baru. Sentuhan warna lain pada rumbai yang senada dengan motif ulos bisa melambangkan keterkaitan dengan tradisi dan identitas keluarga. Rumbai secara umum juga bisa dianggap sebagai simbol harapan akan kesuburan dan keberlanjutan.', NULL),
(70, 'P0003', NULL, '44%', '5%', 'Kepala Ulos dengan Motif Geometris Rapat', 'melambangkan identitas leluhur, warisan budaya yang kaya, dan harapan akan keberkahan serta perlindungan bagi pemakainya. Kerapatan motif bisa mencerminkan keeratan hubungan dalam keluarga atau masyarakat.', NULL),
(71, 'P0003', NULL, '49%', '63%', 'Garis-garis Horizontal Berwarna di Badan Ulos', ' Garis-garis yang berulang melambangkan kesinambungan kehidupan dan hubungan sosial yang terjalin terus-menerus.', NULL),
(72, 'P0003', NULL, '41%', '29%', 'Motif Belah Ketupat Berisi di Badan Ulos', 'Bentuk belah ketupat (wajik) umumnya melambangkan kesuburan, kemakmuran, dan persatuan keluarga', NULL),
(73, 'P0003', NULL, '26%', '44%', 'Garis Vertikal Putih di Tengah', 'Garis-garis vertikal berwarna putih dapat melambangkan pemisah atau batas antar tahapan kehidupan atau aspek sosial', NULL),
(74, 'P0003', NULL, '15%', '49%', 'Bidang Samping Merah Maroon', 'Warna merah maroon yang kaya dan dalam seringkali diasosiasikan dengan kekuatan yang matang, keberanian yang teruji, dan ikatan keluarga yang kuat. Bidang warna ini bisa memberikan fondasi atau batasan bagi makna motif-motif di tengah.', NULL),
(75, 'P0003', NULL, '87%', '99%', 'Rumbai di Ujung Ulos', 'Rumbai seringkali melambangkan harapan akan kesuburan, pertumbuhan, dan keberlimpahan.', NULL),
(146, 'P0004', NULL, '23%', '28%', 'Merah Marun', 'Warna merah marun melambangkan keberanian dan semangat.', NULL),
(147, 'P0004', NULL, '73%', '29%', 'warna Hitam', 'Hitam biasanya melambangkan kekuatan dan keteguhan hati dalam budaya Batak.', NULL),
(148, 'P0004', NULL, '45%', '32%', 'Motif Tengah Berpola Garis Vertikal', 'ini adalah bagian tengah ulos (biasanya disebut bagian punggung saat dikenakan).\r\nGaris vertikal menunjukkan struktur benang lusi, menjadi kerangka utama kain.\r\n', NULL),
(149, 'P0004', NULL, '62%', '37%', 'Motif Samping Garis Horizontal dan Pola Emas', 'Ini adalah hasil dari benang pakan berwarna emas dan merah yang ditenun membentuk motif khas Batak.\r\nPola ini menambah nilai estetika dan mengandung makna kehangatan dan kemakmuran.', NULL),
(150, 'P0004', NULL, '53%', '83%', 'Ujung Kain (Tepi) dengan Tulis Bordir', 'menunjukkan nama tempat atau ucapan doa khas Batak, Bordir ini biasanya dibuat dengan benang tambahan di bagian akhir tenunan, mencerminkan identitas pembuat atau tujuan kain.', NULL),
(151, 'P0004', NULL, '38%', '92%', 'Rumbai (Ujung Benang Lepas)', 'mbai-rumbai pada ujung kain adalah sisa benang lusi, dibiarkan terbuka sebagai ciri khas ulos.\r\nIni juga menandakan bahwa kain dibuat dengan teknik tenun tangan, bukan mesin.', NULL),
(639, 'P0006', NULL, '58%', '9%', 'Warna Dasar Merah', 'Ulos ini memiliki dua warna dominan: merah tua (marun) sebagai latar utama di bagian tengah, dan merah terang di sisi kiri dan kanan. Perpaduan ini menciptakan kontras yang kuat namun harmonis, membuat area bermotif di tengah tampak lebih menonjol.', 'utama'),
(640, 'P0006', NULL, '58%', '27%', 'Motif Horizontal Keemasan', 'Motif utama terdiri dari garis-garis horizontal berwarna kuning keemasan, disusun berulang dan berlapis dari tengah ke bawah. Motif ini menyerupai bentuk geometris kecil berbaris rapat, menciptakan ritme visual yang elegan dan mencolok. Motif keemasan ini adalah hasil tenunan dari benang pakan berwarna khusus, yang ditambahkan secara berkala selama proses menenun.', 'utama'),
(641, 'P0006', NULL, '25%', '16%', ' Garis Vertikal Halus', 'Seluruh kain menunjukkan garis-garis vertikal halus berwarna gelap, kemungkinan berasal dari benang lungsi (benang memanjang). Garis-garis ini tampak paling jelas di bagian atas kain yang polos, memberikan tekstur dasar sebelum motif keemasan dimulai.\r\n\r\n', 'utama'),
(642, 'P0006', NULL, '7%', '29%', 'Sisi Pinggir (Kiri dan Kanan)', 'Bagian tepi kiri dan kanan kain memiliki warna merah terang polos tanpa motif. Area ini berfungsi sebagai bingkai visual yang mempertegas batas dari area utama bermotif dan juga menjadi area transisi jika kain dikenakan atau dilipat.\r\n\r\n', 'utama'),
(643, 'P0006', NULL, '39%', '97%', ' Ujung Kain (Bagian Bawah)', 'Di bagian paling bawah kain terdapat rumbai (fringe) berwarna hitam, yang merupakan sisa dari benang lungsi yang tidak ditenun hingga ujung. Tepat di atas rumbai ini, terdapat satu garis horizontal motif keemasan yang lebih tebal dibanding motif lainnya di atasnya. Ini memberi kesan seperti penutup atau garis akhir dari rangkaian motif, mempertegas batas bawah kain dan menambah kesan mewah.\r\n\r\n', 'utama'),
(649, 'P0005', 48, '73%', '25%', 'Warna Merah', 'Warna dasar yang dominan pada ulos ini adalah merah. Merah dalam budaya Batak biasanya melambangkan kehidupan, keberanian, dan semangat. Warna ini juga memiliki konotasi positif dalam hal kesehatan dan kekuatan.', 'material'),
(651, 'P0005', 48, '52%', '94%', 'Fringe Kuning', 'Ulos biasanya dihiasi dengan fringe atau bagian ujung yang digantung, seperti pada ulos ini yang memiliki fringe kuning di bagian bawah. Warna kuning sendiri sering dikaitkan dengan kebahagiaan, keberuntungan, dan keselamatan dalam budaya Batak. Ini bisa menunjukkan harapan dan doa untuk masa depan yang baik bagi pemakainya.', 'material'),
(652, 'P0005', 48, '72%', '69%', 'Motif Diagonal Berwarna Hitam, Putih, dan Warna Lainnya', 'Pola diagonal yang teratur, dengan kombinasi warna hitam, putih, dan beberapa warna lainnya, sering kali merujuk pada konsep keberagaman dan keseimbangan dalam kehidupan. Garis-garis diagonal ini bisa mengandung makna bahwa kehidupan manusia selalu menghadapi perbedaan, namun tetap memiliki keterhubungan dan keseimbangan.', 'material'),
(653, 'P0005', 48, '42%', '37%', 'Pola Warna Merah-Hitam dan Hijau', 'Pada beberapa bagian, terlihat pola yang memiliki warna merah-hitam serta garis hijau. Warna hijau sering dikaitkan dengan kesuburan dan keberkahan, sedangkan merah-hitam bisa merujuk pada keberanian dan kekuatan dalam menjalani kehidupan, serta simbol perlindungan dalam menghadapi tantangan.', 'material'),
(654, 'P0005', 48, '42%', '96%', 'Fringe Kuning pada Ujung Ulos', 'Bagian ujung ulos yang dihiasi fringe berwarna kuning memberikan simbol kebahagiaan, keberuntungan, dan keselamatan. Warna kuning juga dapat menunjukkan rasa syukur dan penghormatan kepada alam dan leluhur.', 'material'),
(655, 'P0005', 48, '88%', '34%', 'Pola Berulang di Sisi Ulos', 'Di sisi-sisi ulos ini terdapat pola berulang yang memanjang, mencerminkan keseimbangan dan harmoni antara dunia manusia dan alam semesta. Pola yang berulang ini menunjukkan kekuatan dalam keteraturan, serta harapan agar kehidupan berjalan lancar dan penuh berkah.', 'material'),
(661, 'P0007', NULL, '41%', '44%', 'Warna Dasar Hitam Pekat', ' Hitam melambangkan kekuatan, kewibawaan, dan kestabilan. Dalam konteks adat, hitam juga dapat menunjukkan kematangan dan kesakralan.\r\n\r\n', 'utama'),
(662, 'P0007', NULL, '18%', '5%', 'Motif Vertikal Halus (Bagian Atas)', 'Pola vertikal melambangkan perjalanan hidup atau jalur kehidupan. Pola ini juga mencerminkan kesinambungan dan keteraturan dalam kehidupan.', 'utama'),
(663, 'P0007', NULL, '61%', '10%', 'Motif Titik-titik Halus Vertikal (Bagian Tengah)', 'Titik-titik kecil berderet melambangkan jejak kehidupan atau pengalaman hidup. Pola ini juga bisa diartikan sebagai doa dan harapan agar perjalanan hidup selalu terarah.', 'utama'),
(664, 'P0007', NULL, '45%', '26%', 'Tekstur Tenun Halus (Bagian Tengah)', 'Tenun halus menunjukkan kualitas dan keterampilan pembuatnya. Ini juga menandakan nilai estetika dan rasa hormat terhadap tradisi.', 'utama'),
(665, 'P0007', NULL, '47%', '92%', 'Rumbai Panjang di Ujung Kain', 'Rumbai melambangkan keterikatan, hubungan sosial, dan persatuan. Setiap helai rumbai dapat melambangkan individu yang terhubung dalam komunitas.', 'utama'),
(666, 'P0007', NULL, '49%', '76%', 'Anyaman Kotak-kotak Berwarna Coklat dan Merah', 'Pola kotak-kotak melambangkan keteraturan, keseimbangan, dan kesinambungan hidup. Ini juga dapat diartikan sebagai ikatan keluarga atau hubungan antargenerasi.', 'utama'),
(667, 'P0007', NULL, '51%', '84%', 'Pola Horizontal Berwarna Emas', 'Emas melambangkan kemuliaan, kekayaan, dan status sosial. Garis emas di bagian bawah biasanya menunjukkan posisi atau tingkatan sosial pemakainya.\r\n\r\n', 'utama'),
(668, 'P0007', NULL, '70%', '72%', 'Pola Horizontal Berwarna Merah Marun', 'Merah marun melambangkan keberanian, semangat, dan darah leluhur. Ini juga bisa menunjukkan hubungan dengan nenek moyang atau akar budaya.', 'utama'),
(669, 'P0008', NULL, '55%', '49%', 'Warna Dasar Biru Gelap (Indigo)', 'Warna biru tua atau indigo melambangkan ketenangan, kedalaman makna spiritual, serta penghormatan terhadap leluhur. Warna ini khas untuk Ulos Sibolang, dan biasanya digunakan dalam konteks upacara kematian atau duka.', 'utama'),
(670, 'P0008', NULL, '50%', '44%', 'Motif Garis Zigzag dan Anak Panah Putih (di tengah dan atas)', 'Zigzag melambangkan perjalanan hidup yang tidak lurus, penuh tantangan, namun terus maju.\r\nMotif anak panah ke atas melambangkan harapan atau doa yang ditujukan ke langit atau leluhur.', 'utama'),
(671, 'P0008', NULL, '71%', '46%', ' Pinggiran Warna Hitam Pekat', 'Warna hitam melambangkan duka, keteguhan, dan perlindungan. Ini memperkuat fungsi Ulos Sibolang dalam konteks ritual kematian.', 'utama'),
(672, 'P0008', NULL, '68%', '37%', 'Garis Vertikal Biru Muda di Samping', 'Garis vertikal tipis di samping kanan dan kiri bisa melambangkan penjaga atau batas kehidupan—antara dunia yang fana dan dunia arwah.', 'utama'),
(673, 'P0008', NULL, '54%', '91%', 'Rumbai di Bawah (Benang Sisa)', 'Rumbai sering kali melambangkan kesinambungan hidup, serta bagian dari ekspresi akhir tenun yang tidak “diputus” secara kasar.', 'utama'),
(674, 'P0008', NULL, '51%', '21%', 'Gantungan Kayu Ukiran Tradisional (Di Atas)', 'Walaupun bukan bagian dari ulos, gantungan ini menunjukkan nilai estetika dan kebudayaan Batak. Ukiran tersebut biasanya berupa motif gorga, simbol kekuatan dan keagungan.\r\n\r\n', 'utama'),
(675, 'P0009', NULL, '88%', '26%', 'Warna Dasar Kain (Hitam)', 'Hitam sering melambangkan keteguhan, kekuatan, dan kestabilan. Dalam konteks budaya, warna hitam juga melambangkan perlindungan dari energi negatif dan kejahatan. Selain itu, hitam juga dapat melambangkan misteri dan kedalaman spiritual.\r\n\r\n', 'utama'),
(676, 'P0009', NULL, '16%', '20%', 'Garis Tepi (Pinggiran)', 'Garis tepi berwarna putih dan merah melambangkan batas antara dunia luar dan dunia dalam. Putih melambangkan kesucian, ketulusan, dan perlindungan spiritual. Merah melambangkan keberanian, kekuatan, dan semangat hidup. Gabungan kedua warna ini menggambarkan keseimbangan antara dunia jasmani dan rohani.', 'utama'),
(677, 'P0009', NULL, '61%', '25%', 'Motif Ikat Tengah (Berderet)', 'Motif ikat berbentuk kecil-kecil yang berderet ini sering melambangkan ikatan sosial atau kekeluargaan. Dalam beberapa budaya, motif ikat juga dianggap sebagai simbol perlindungan dari energi negatif dan sebagai penghubung antara generasi tua dan muda.', 'utama'),
(678, 'P0009', NULL, '64%', '98%', 'Motif Pita Samping (Garis Merah dan Putih)', 'Motif pita samping yang mengelilingi kain berfungsi sebagai pelindung. Warna merah melambangkan keberanian dan kekuatan, sementara putih melambangkan kesucian dan perlindungan. Motif ini mengisyaratkan bahwa seseorang harus selalu menjaga keseimbangan antara energi positif (putih) dan semangat hidup (merah).', 'utama'),
(679, 'P0009', NULL, '61%', '21%', 'Motif Vertikal (Putih)', 'Garis-garis vertikal pendek berwarna putih melambangkan hubungan antara bumi dan langit, atau manusia dan Sang Pencipta. Pola vertikal juga mengisyaratkan kesinambungan kehidupan, keabadian, dan keseimbangan spiritual.', 'utama'),
(680, 'P0009', NULL, '64%', '93%', 'Pola Anyaman (Tepi Bawah)', 'Pola anyaman horizontal berwarna putih di bagian bawah kain melambangkan fondasi kehidupan. Pola ini menunjukkan bahwa segala sesuatu harus dibangun di atas dasar yang kuat dan kokoh. Dalam konteks spiritual, ini bisa berarti pentingnya menjaga keseimbangan antara duniawi dan rohani.', 'utama'),
(685, 'P0010', NULL, '56%', '40%', 'Bagian Tengah (Motif Ikat Gelap)', 'Bagian tengah kain memiliki pola ikat berwarna hitam dan abu-abu yang berulang secara horizontal. Motif ini melambangkan kesinambungan hidup, perjuangan, dan perjalanan panjang manusia. Selain itu, pola ini juga menggambarkan ikatan erat antara manusia dengan leluhur dan roh-roh nenek moyang, yang selalu menjaga dan melindungi.', 'utama'),
(686, 'P0010', NULL, '19%', '49%', 'Panel Putih di Sisi Kain', 'Pada kedua sisi kain terdapat panel berwarna putih dengan pola anyaman halus yang rapat. Warna putih melambangkan kesucian, ketulusan, dan kesejahteraan hidup. Motif anyaman tersebut juga merepresentasikan hubungan sosial dan ikatan kekeluargaan dalam masyarakat Batak, yang harus tetap terjalin erat dan harmonis.\r\n\r\n', 'utama'),
(687, 'P0010', NULL, '8%', '16%', 'Garis Melintang Merah dan Putih', 'Di tepi atas dan bawah kain terdapat garis-garis melintang berwarna merah dan putih. Garis merah melambangkan keberanian, semangat hidup, dan kekuatan dalam menghadapi cobaan hidup. Sedangkan garis putih melambangkan kesucian, ketulusan, dan perlindungan dari energi negatif. Kombinasi kedua warna ini menandakan keseimbangan antara kekuatan jasmani dan spiritual.', 'utama'),
(688, 'P0010', NULL, '97%', '60%', 'Rumbai Ujung Kain', 'Ujung kain dihiasi dengan rumbai-rumbai berwarna biru tua dan hitam. Rumbai ini melambangkan akhir dari sebuah perjalanan hidup, seperti kematian atau transisi dari satu fase kehidupan ke fase berikutnya. Selain itu, rumbai-rumbai tersebut juga dipercaya sebagai bentuk doa dan harapan agar pemakainya senantiasa dilindungi oleh leluhur.', 'utama'),
(689, 'P0010', NULL, '15%', '47%', 'Noda Kuning pada Panel Putih', 'Pada panel putih terlihat noda kekuningan yang menandakan usia kain tersebut. Noda ini bisa menjadi simbol dari perjalanan waktu, jejak sejarah, atau kenangan dari upacara adat tertentu. Kain ulos yang memiliki noda semacam ini biasanya dianggap sebagai kain yang sakral atau memiliki nilai sejarah tersendiri.', 'utama'),
(690, 'P0010', NULL, '93%', '15%', 'Tepi Kain dengan Motif Garis Sederhana', 'Di sepanjang tepi kain terdapat motif garis hitam dan putih yang sederhana namun tegas. Garis ini berfungsi sebagai pembatas simbolis, menjaga agar energi positif tetap berada di dalam kain tersebut. Selain itu, garis ini juga melambangkan keteraturan hidup dan perlindungan spiritual dari gangguan energi negatif.', 'utama'),
(691, 'P0011', NULL, '72%', '21%', 'Garis Biru Vertikal di Sisi Kiri dan Kanan', 'Dua garis biru vertikal yang tebal di sisi kiri dan kanan kain. Garis ini berfungsi sebagai batas tepi kain dan melambangkan perlindungan serta kestabilan.', 'utama'),
(692, 'P0011', NULL, '57%', '26%', 'Garis-Garis Putih Vertikal di Seluruh Permukaan Kain', 'Garis-garis putih vertikal tipis yang berulang dari atas ke bawah di seluruh permukaan kain. Ini melambangkan perjalanan hidup yang lurus dan terarah.', 'utama'),
(693, 'P0011', NULL, '40%', '56%', 'Area Tengah Kain (Bagian yang Lebih Padat Garisnya)', 'Di tengah kain, terdapat kumpulan garis putih yang lebih rapat dan membentuk pola kotak-kotak. Ini melambangkan ikatan kekeluargaan atau hubungan sosial yang erat.', 'utama'),
(694, 'P0011', NULL, '47%', '93%', 'Ujung Bawah Kain (Bagian Berumbai)', 'Pada ujung bawah kain terdapat rumbai-rumbai benang hitam. Rumbai ini menandakan akhir perjalanan hidup atau sebuah fase kehidupan tertentu.', 'utama'),
(695, 'P0011', NULL, '72%', '77%', 'Bagian Tengah Bawah (Garis Biru dan Putih Berdekatan)', 'Di bagian bawah kain, dekat dengan rumbai, terdapat garis biru dan putih yang berdekatan. Ini melambangkan keseimbangan antara keberanian (biru) dan kesucian (putih)', 'utama'),
(696, 'P0011', NULL, '23%', '37%', 'Permukaan Kain yang Hitam Pekat', 'Latar kain didominasi warna hitam pekat. Hitam melambangkan kekuatan, keteguhan, dan koneksi dengan dunia spiritual.', 'utama'),
(697, 'P0012', NULL, '87%', '25%', 'Pinggiran Kain Berwarna Merah Terang', 'Bagian tepi kain di sisi kiri dan kanan berwarna merah terang yang solid. Merah melambangkan keberanian, kekuatan, dan semangat hidup. Warna merah ini juga berfungsi untuk mengikat fokus agar tetap pada bagian tengah kain.', 'utama'),
(698, 'P0012', NULL, '50%', '15%', 'Garis Pembatas Putih di Tepi Merah', 'Di antara warna merah dan bagian tengah kain terdapat garis putih vertikal tipis. Garis ini melambangkan batas atau pemisah antara dunia luar (tepi kain) dan inti kehidupan (bagian tengah kain). Putih melambangkan kesucian dan perlindungan.', 'utama'),
(699, 'P0012', NULL, '63%', '31%', 'Bagian Tengah Kain Berwarna Merah Tua (Maroon)', 'Bagian tengah kain berwarna merah tua dengan pola garis-garis putih vertikal tipis yang berulang secara teratur. Pola garis-garis putih tersebut melambangkan keteraturan dan kesinambungan hidup. Warna maroon melambangkan kematangan dan kebijaksanaan.', 'utama'),
(700, 'P0012', NULL, '50%', '36%', 'Motif Anyaman Emas di Tengah Kain', 'Di bagian tengah kain, terdapat motif anyaman berwarna emas dengan pola kotak-kotak kecil. Motif ini melambangkan kemakmuran, keagungan, dan hubungan yang erat antarindividu. Warna emas juga melambangkan status sosial yang tinggi.', 'utama'),
(701, 'P0012', NULL, '60%', '86%', 'Garis Horizontal Emas di Bagian Tengah Bawah', 'Terdapat dua garis horizontal berwarna emas di bagian bawah kain. Garis emas ini menandakan batas antara bagian tengah kain dan bagian bawah kain. Warna emas tersebut melambangkan kekayaan dan keberkahan dalam hidup.', 'utama'),
(702, 'P0012', NULL, '59%', '92%', 'Ujung Bawah Kain (Rumbai-Rumbai Berwarna Hitam, Putih, Merah)', 'Pada ujung bawah kain terdapat rumbai-rumbai berwarna hitam, putih, dan merah yang terjalin bersama. Rumbai ini melambangkan ikatan keluarga atau hubungan sosial yang kuat. Kombinasi warna hitam (kekuatan), putih (kesucian), dan merah (keberanian) menunjukkan keseimbangan hidup.', 'utama'),
(715, 'P0013', NULL, '7%', '33%', 'Warna Dasar Hitam', 'Melambangkan keteguhan, kekuatan, dan perlindungan.\r\nDalam budaya Batak, hitam juga mencerminkan kesakralan dan kedalaman spiritual.\r\nWarna ini mendominasi kain sebagai simbol pelindung dalam perjalanan hidup.\r\n\r\n', 'utama'),
(716, 'P0013', NULL, '57%', '32%', 'Garis-Garis Biru Tua Vertikal', 'Garis biru yang tersusun rapi dari atas ke bawah melambangkan keteraturan hidup dan keberlangsungan keturunan.\r\nBiru juga bermakna ketenangan, pengharapan, dan kesetiaan.\r\nPenempatan vertikal menunjukkan arah hidup yang lurus dan berpegang pada adat.', 'utama'),
(717, 'P0013', NULL, '56%', '54%', 'Garis Biru Horizontal di Tengah Kain', 'Ini adalah ciri khas motif “suri-suri”, yang selalu hadir pada bagian tengah ulos.\r\nGaris horizontal menggambarkan penyatu keluarga dan kekuatan hubungan sosial, terutama antar marga atau generasi.', 'utama'),
(718, 'P0013', NULL, '79%', '96%', 'Ujung Kain (Bordir Merah-Putih-Hitam)', 'Meski hanya terlihat sebagian, warna-warna ini umumnya melambangkan Trinitas Batak:\r\nMerah: Kehidupan dan semangat.\r\nPutih: Kesucian dan ketulusan niat.\r\nHitam: Kekuatan dan perlindungan.', 'utama'),
(719, 'P0013', NULL, '32%', '38%', 'Pola Strip Tipis dan Rapat', 'Maknanya adalah ketelitian dan kesungguhan dalam bekerja serta hidup yang penuh disiplin.\r\nDalam budaya Batak, pola halus dan rapi mencerminkan kerja keras dan ketekunan, dua nilai penting dalam keluarga dan masyarakat.\r\n\r\n', 'utama'),
(722, 'P0014', NULL, '68%', '34%', 'Warna Merah Dominan', 'Melambangkan kasih sayang yang mendalam, semangat hidup, dan berkat yang terus-menerus mengiringi.', 'utama'),
(723, 'P0014', NULL, '44%', '40%', 'Garis-Garis Vertikal Rapat (Merah, Pink, Emas, dsb.)', 'Pola garis ini memberi kesan kesatuan generasi, bahwa generasi muda diharapkan melanjutkan tradisi dan nilai luhur keluarga.', 'utama'),
(724, 'P0014', NULL, '49%', '79%', 'Rumbai di Ujung Ulos', 'Rumbai adalah simbol dari \"ujung yang terbuka\", yaitu doa agar yang menerima ulos tetap berkembang dan menyebarkan kebaikan.\r\n\r\n', 'utama'),
(725, 'P0014', NULL, '78%', '27%', ' Bidang Tepi Berwarna merah Gelap (di Sisi Kanan)', 'Sebagai warna di sisi luar, ini menandakan bahwa setiap kehidupan (anak-anak yang \"mangiring\") perlu dibingkai oleh nilai-nilai luhur dan kendali diri.', 'utama'),
(726, 'P0014', NULL, '60%', '36%', 'Transisi Warna dari Merah Cerah ke Merah Tua', 'Transisi warna ini melambangkan perjalanan hidup dari masa muda ke masa dewasa, atau dari awal kehidupan ke kedewasaan spiritual dan sosial.', 'utama'),
(727, 'P0014', NULL, '68%', '57%', 'Simetri Kiri–Kanan Secara Keseluruhan', 'Simetri ini melambangkan keseimbangan dalam memberi dan menerima kasih, serta harmoni antara orang tua dan anak.', 'utama'),
(729, 'P0015', NULL, '60%', '87%', 'Warna Dasar (Hitam)', ' Warna hitam melambangkan kekuatan, keteguhan, dan kesabaran. Dalam tradisi Batak, hitam juga merepresentasikan perjalanan hidup dan tantangan yang harus dihadapi.', 'utama'),
(730, 'P0015', NULL, '48%', '19%', ' Motif Tumbuhan (Seperti daun atau tunas berwarna-warni)', 'Makna: Ini melambangkan pertumbuhan, harapan, dan kelangsungan hidup. Warna-warni tunas menandakan:\r\nHijau: harapan dan kelestarian.\r\nMerah: semangat dan keberanian.\r\nBiru/ungu: ketenangan dan kepercayaan.', 'utama'),
(731, 'P0015', NULL, '46%', '48%', 'Motif Berlian / Rumbai Geometris (Bentuk belah ketupat)', ' Motif ini sering disebut \"gorga\". Bentuk belah ketupat melambangkan keharmonisan dan keseimbangan dalam kehidupan, serta keterikatan keluarga dan leluhur.', 'utama'),
(732, 'P0015', NULL, '11%', '69%', 'Pola Garis Merah Horizontal (berulang)', 'Makna: Melambangkan arah hidup yang tetap dan tidak menyimpang dari nilai-nilai adat. Garis-garis ini adalah simbol dari proses hidup dan jalan spiritual.', 'utama'),
(733, 'P0015', NULL, '39%', '34%', 'Titik-titik dan Segitiga Kecil', 'Ini adalah simbol dari keberagaman manusia dan pengalaman. Juga mengingatkan bahwa setiap individu punya peran dalam menjaga tatanan sosial dan budaya.\r\n\r\n', 'utama'),
(734, 'P0015', NULL, '78%', '32%', 'Pinggiran Merah di Sisi Kiri dan Kanan', 'Warna merah melambangkan semangat, pengorbanan, dan kasih sayang. Dalam posisi ini, ia seolah melindungi dan menjaga pusat ulos, yang berarti peran pelindung dari orang tua atau leluhur.', 'utama'),
(735, 'P0015', NULL, '63%', '95%', 'Rumbai di Ujung Ulos', 'Makna: Rumbai melambangkan kelanjutan hidup dan keturunan, yaitu harapan agar keluarga besar terus berkembang dan menyatu dalam kasih dan adat.\r\n\r\n', 'utama'),
(737, 'P0016', NULL, '40%', '13%', 'Motif Berlian Kecil', 'Motif ini melambangkan kesabaran, ketekunan, dan kestabilan hidup. Dalam budaya Batak, pola berulang kecil ini sering diartikan sebagai lambang usaha keras tanpa henti untuk mencapai tujuan hidup.\r\n\r\n', 'utama'),
(738, 'P0016', NULL, '58%', '33%', 'Garis Vertikal Panjang (di sisi kanan ulos)', 'Garis ini melambangkan keberlanjutan hidup dan kesinambungan generasi, seperti benang merah dalam silsilah keluarga. Ini menegaskan pentingnya menjaga garis keturunan dan hubungan antar marga.\r\n\r\n', 'utama'),
(739, 'P0016', NULL, '52%', '49%', 'Motif Berlian Besar Rapat (bagian tengah bawah)', 'Bagian ini menonjolkan puncak kejayaan atau keberhasilan. Umumnya bagian ini menjadi pusat perhatian karena menunjukkan nilai tertinggi dari perjuangan, sekaligus titik tumpu motif lain.\r\n\r\n', 'utama'),
(740, 'P0016', NULL, '55%', '72%', 'Motif Segitiga Bertumpuk (di bagian tengah bawah dalam petak panel)', 'Melambangkan doa dan pengharapan yang mengarah ke atas, mencerminkan hubungan manusia dengan yang ilahi dan harapan akan berkat dari leluhur atau Tuhan.\r\n\r\n', 'utama'),
(741, 'P0016', NULL, '57%', '91%', 'Motif Horizontal Panjang dengan Pola Simetris (dekoratif bagian bawah)', 'Menunjukkan harmoni dan keseimbangan hidup. Dalam budaya Batak, motif ini menyimbolkan pentingnya menjaga relasi yang serasi dalam keluarga dan masyarakat.', 'utama'),
(742, 'P0016', NULL, '57%', '96%', ' Rumbai-rumbai di Ujung Kain', 'Rumbai ini melambangkan akhir dari perjalanan hidup atau penutup dari setiap usaha, yang tetap harus terlihat indah dan terhormat. Rumbai juga sering dimaknai sebagai lambang kebebasan dan ekspresi.\r\n\r\n', 'utama');
INSERT INTO `produk_material_hotspots` (`id`, `kode_produk`, `material_photo_id`, `judul`, `deskripsi`, `x_position`, `y_position`, `created_at`) VALUES
(69, 'P0001', 41, 'BS4', '4 helai atau putaran benang BS (misalnya warna biru tua atau jenis tertentu)', '14%', '16%', '2025-05-06 15:47:31'),
(73, 'P0001', 41, 'B', 'bisa berarti warna dasar atau akhir motif (misalnya benang hitam atau benang polos)', '70%', '17%', '2025-05-06 15:53:51'),
(78, 'P0001', 41, 'baris 1', 'Gunakan benang sesuai urutan rumus pada alat tenun. Misalnya baris 1:\r\nAmbil 4 helai benang hitam → 1 helai merah → 5 helai hitam → dst.\r\n', '6%', '15%', '2025-05-06 15:56:26'),
(79, 'P0001', 41, 'Tiap baris ', 'Tiap baris mewakili satu pola atau deretan benang dalam tenunan. Bisa untuk satu garis motif atau satu jalur horizontal pada kain.', '43%', '44%', '2025-05-06 15:56:53'),
(80, 'P0001', 41, 'baris ke-10', 'Setelah baris ke-10, Anda bisa mengulang dari baris pertama lagi untuk membentuk pola berulang (repeat pattern).', '3%', '87%', '2025-05-06 15:57:33'),
(81, 'P0001', 41, ' BS (Benang Seling)', 'Memberi warna kontras untuk membentuk pola motif (biasanya merah, hitam, atau warna khas Batak lainnya).\r\nContoh: BS³ artinya 3 helai benang seling dipakai berturut-turut untuk membentuk satu bagian motif.\r\n', '36%', '79%', '2025-05-07 01:34:38'),
(82, 'P0001', 41, 'US (Ulos Sorit)', 'Sebagai benang dasar (biasanya warna netral seperti putih atau abu).\r\nMembuat ruang kosong di antara motif warna agar motif tidak saling bertabrakan.\r\n\r\n', '22%', '16%', '2025-05-07 01:36:12'),
(83, 'P0001', 41, 'SB (Seling Benang)', 'Menandai pergantian arah atau pola penenunan.\r\nMengatur transisi antar-motif atau bagian dalam satu bunga agar terlihat hidup dan tidak kaku.', '19%', '38%', '2025-05-07 01:37:03'),
(84, 'P0001', 41, 'Angka (², ³, ⁴, dst)', 'Menentukan jumlah pengulangan benang atau arah benang.\r\nContoh: BS⁴ = empat benang seling berturut-turut = satu sisi dari kelopak bunga.', '62%', '28%', '2025-05-07 01:38:20'),
(85, 'P0001', 41, 'Urutan Baris (1 s.d. 10)', 'Menyusun langkah demi langkah dalam proses menenun.\r\nContoh: Baris 1-5 membentuk setengah bunga, baris 6-10 biasanya untuk sisi sebaliknya (mirror).\r\n', '5%', '40%', '2025-05-07 01:38:55'),
(86, 'P0002', 42, 'USⁿ (Ulos Sorit)', 'Tarik benang dasar (warp) sebanyak \"n\" helai tanpa disisipi benang motif. Digunakan untuk membentuk latar, memberi jarak antar motif, dan menjaga ketegangan benang agar stabil.\r\n\r\n', '6%', '9%', '2025-05-07 08:53:58'),
(87, 'P0002', 42, 'BSⁿ (Benang Seling/Motif)', 'Sisipkan benang motif berwarna ke dalam tenunan sebanyak \"n\" helai. Digunakan untuk membentuk bagian utama motif, seperti garis atau bentuk bunga.', '30%', '9%', '2025-05-07 08:54:29'),
(88, 'P0002', 42, 'SBⁿ (Seling Benang/Transisi)', 'Sisipkan benang netral (atau warna dasar) sebagai penyambung antar bagian motif. Membantu peralihan agar motif tidak tampak putus atau kasar.', '51%', '33%', '2025-05-07 08:55:08'),
(89, 'P0002', 42, 'SUⁿ (Sisip Ulos/Benang Hias)', 'Tambahkan benang khusus (biasanya benang kilap atau cerah) sebanyak \"n\" helai. Digunakan untuk memperindah bagian tertentu dalam motif, memberi efek visual mencolok.', '38%', '34%', '2025-05-07 08:55:52'),
(90, 'P0002', 42, 'BSU (Benang Seling Ujung)', 'Gabungan benang seling dan penutup motif. Disisipkan di ujung bagian motif untuk menutup dan menjaga posisi benang motif agar tidak bergeser saat ditenun.', '92%', '7%', '2025-05-07 08:56:19'),
(91, 'P0002', 42, 'Uⁿ (Benang Kosong)', 'Tarik benang dasar tanpa motif sebanyak \"n\" helai. Dipakai untuk memberi jarak antar motif agar tidak terlalu padat dan menjaga estetika kain.', '66%', '34%', '2025-05-07 08:56:50'),
(97, 'P0003', 43, 'Uⁿ (Ulos Sorit / Benang Dasar)', 'Tarik benang dasar sebanyak “n” helai tanpa motif.\r\nDigunakan sebagai latar utama ulos, memberi struktur dan kekuatan dasar tenunan. Pada versi modern, benang dasar sering diberi warna netral (hitam, putih, atau abu-abu) untuk menonjolkan elemen dekoratif.', '8%', '5%', '2025-05-07 09:21:17'),
(98, 'P0003', 43, 'Bⁿ (Benang Motif / Seling Motif)', 'Sisipkan benang berwarna atau bermotif sebanyak “n” helai.\r\nBerfungsi sebagai pembentuk pola geometris modern seperti garis-garis, blok warna, atau bentuk stilisasi bunga. Digunakan sebagai penekanan visual utama dalam motif Sadum modern.', '31%', '30%', '2025-05-07 09:22:39'),
(99, 'P0003', 43, 'SUⁿ (Sisip Ulos / Benang Kilap)', 'Tambahkan benang kilap atau warna cerah sebanyak “n” helai.\r\nMemberi efek visual mencolok, menciptakan kesan elegan dan kontemporer. Sering digunakan untuk membuat aksen yang mencolok di bagian tengah atau sisi kain.', '21%', '53%', '2025-05-07 09:23:10'),
(100, 'P0003', 43, 'SBⁿ (Seling Benang / Transisi Motif)', 'Sisipkan benang netral atau warna dasar sebagai penyambung antar bagian motif sebanyak “n” helai.\r\nMemperhalus transisi antar warna atau bentuk motif agar tampilan keseluruhan tetap harmonis. Berperan penting dalam menjaga kontinuitas pola.\r\n\r\n', '66%', '52%', '2025-05-07 09:24:39'),
(101, 'P0003', 43, 'BSU (Benang Seling Ujung)', 'Gabungan dari benang transisi dan penutup motif, disisipkan di bagian akhir motif.\r\nMembantu menjaga stabilitas posisi benang motif, terutama saat proses penyelesaian. Penting untuk menutup motif agar tidak longgar saat ulos digunakan atau dicuci.', '67%', '86%', '2025-05-07 09:30:23'),
(103, 'P0004', 45, 'Uⁿ (Benang Latar / Ulos Dasar)', 'Tarik benang sebanyak \'n\' helai tanpa batas netral. Digunakan sebagai bedang utama menyebarkan pentampi lidang neutral Ulos Ragihotang.', '11%', '5%', '2025-05-07 10:42:27'),
(104, 'P0004', 45, 'SUⁿ (Sisip Benang Kilap)', 'Sisipkan benang kilap atau warna cerah sebanyak \'n\' helai. Untuk mempertegas aksen visual di tengah motif, terutama untuk memperkuat tampilan modern.SUⁿ (Sisip Benang Kilap)', '55%', '5%', '2025-05-07 10:43:14'),
(105, 'P0004', 45, 'Bⁿ (Benang Hitam)', 'Mensutikan benang hitam sebanyak \'n\' helai. Untuk membentuk garis hitam bold, menambah dimensi dan intensitas pada motif Ragihotang.', '80%', '20%', '2025-05-07 10:43:39'),
(106, 'P0004', 45, 'BSU (Benang Seling Ujung', 'Gabungan benang hitam dan benang sela hitam disatukan di ujung motif. Berfungsi sebagai penutup motif agar tetap stabil dan tidak longgar saat digunakan.', '81%', '45%', '2025-05-07 10:44:26'),
(107, 'P0004', 45, 'SBⁿ (Seling Latar / Garis Dasar)', 'Substitusi ulos dasar hitam dengan benang netral sebanyak \'n\' helai. Digunakan untuk menjaga keselarasan pola dan transisi antar motif.', '79%', '33%', '2025-05-07 10:45:49'),
(108, 'P0004', 45, 'SB³ (Ulos Kecil Ragihotang)', 'Digunakan tiga sambungan benang hitam, putih, dan merah. Fungsi utamanya adalah sebagai penguat struktur dan penutup pola pada Ragihotang.', '83%', '5%', '2025-05-07 10:46:42'),
(112, 'P0006', 51, 'US²', 'Pada pola ini, US² menunjukkan bahwa pada bagian ini digunakan dua benang yang memiliki warna atau jenis serupa atau saling melengkapi. Angka \"²\" di sini berarti penggunaan dua benang secara berurutan atau dua langkah tenun untuk bagian ini.', '11%', '6%', '2025-05-12 14:34:34'),
(113, 'P0006', 51, 'B3', 'B3 menunjukkan bagian di mana tiga benang digunakan pada pola ini, mengindikasikan bahwa tiga benang akan disusun dalam bentuk tertentu dengan pengulangan tiga kali.', '41%', '6%', '2025-05-12 14:35:38'),
(114, 'P0006', 51, 'B', 'B digunakan untuk menunjukkan benang atau langkah tenun tertentu yang akan dipakai untuk menciptakan elemen dasar pada desain. Ini biasanya berarti bahwa satu jenis benang atau teknik dasar digunakan pada bagian ini.', '20%', '25%', '2025-05-12 14:36:24'),
(115, 'P0006', 51, 'E', 'E menunjukkan bagian pola yang melibatkan penggunaan benang dengan teknik tertentu, mungkin untuk menciptakan perbedaan tekstur atau untuk penyesuaian warna yang lebih halus dalam pola.', '20%', '25%', '2025-05-12 14:36:42'),
(116, 'P0006', 51, 'SU²', 'SU² menunjukkan bahwa pada bagian ini digunakan dua benang dengan jenis atau warna tertentu, yang kemudian akan diulang dua kali dalam langkah menenun yang sama.', '30%', '41%', '2025-05-12 14:37:12'),
(117, 'P0006', 51, 'B²', 'B² menunjukkan bahwa pada bagian ini digunakan dua benang (bisa dengan warna atau jenis tertentu) yang akan disusun dalam dua langkah berurutan atau dua bagian yang terpisah, sesuai dengan urutan pola.', '45%', '56%', '2025-05-12 14:39:13'),
(118, 'P0005', 52, 'US³', 'Penenun akan menyusun tiga benang secara bersamaan pada bagian ini untuk menciptakan bagian yang lebih tebal atau lebih kaya akan warna, menambahkan kedalaman pada desain ulos.', '10%', '12%', '2025-05-12 16:02:12'),
(119, 'P0005', 52, 'B4', 'Penenun akan menggunakan empat benang yang mungkin memiliki warna berbeda, untuk memberi tekstur atau kekuatan pada bagian tersebut.', '83%', '13%', '2025-05-12 16:02:42'),
(120, 'P0005', 52, 'SU²', 'SU² menunjukkan penggunaan dua benang di bagian ini, yang akan digunakan dalam dua langkah menenun yang terpisah.', '80%', '36%', '2025-05-12 16:03:41'),
(121, 'P0005', 52, 'B³', 'B³ menunjukkan penggunaan tiga benang pada bagian ini, yang digunakan untuk memberikan kekuatan atau ketebalan lebih pada bagian tersebut.', '19%', '51%', '2025-05-12 16:06:12'),
(122, 'P0005', 52, 'B²', 'B² menunjukkan penggunaan dua benang yang diatur berurutan, untuk menciptakan desain yang lebih rapi atau memberi penekanan pada area tertentu.', '33%', '36%', '2025-05-12 16:06:40'),
(123, 'P0005', 52, 'B', 'Digunakan untuk transisi halus dalam motif atau sebagai penyeimbang antar bagian yang lebih kompleks. Penenun hanya memakai satu benang di bagian ini, yang bisa berfungsi untuk menjaga konsistensi arah dan ketegangan benang selama proses tenun.', '65%', '37%', '2025-05-12 16:09:53'),
(124, 'P0010', 60, 'BS6', 'Enam rangkaian benang silang digunakan untuk membentuk struktur dasar kain agar lebih kokoh dan rapi. Ini adalah langkah awal untuk membuat pola utama ulos agar benangnya tidak mudah bergeser.', '10%', '26%', '2025-05-15 16:34:00'),
(125, 'P0010', 60, 'U9 ', 'Sembilan kali lipatan ujung benang berfungsi untuk memperpanjang motif tertentu agar pola lebih jelas terlihat di bagian tengah ulos. Ini juga menandai area yang akan diberi aksen khusus.', '71%', '78%', '2025-05-15 16:34:31'),
(126, 'P0010', 60, 'SU2', 'Dua simpul ujung benang berfungsi untuk mengunci pola agar tidak mudah lepas. Ini penting saat motif yang lebih kompleks mulai ditambahkan agar pola tetap stabil.\r\n\r\n', '37%', '47%', '2025-05-15 16:35:03'),
(127, 'P0010', 60, 'S2', 'Dua kali lepas benang digunakan untuk menciptakan celah atau ruang pada kain. Biasanya untuk membentuk batas antara satu motif dengan motif lainnya agar lebih terpisah dan jelas.\r\n\r\n', '37%', '47%', '2025-05-15 16:36:15'),
(128, 'P0010', 60, 'SB3', 'Tiga kali simpul benang berfungsi untuk mengunci benang pada akhir rangkaian motif. Ini memastikan pola tidak berubah bentuk saat proses penganyaman berikutnya.', '10%', '70%', '2025-05-15 16:36:52'),
(129, 'P0010', 60, 'B5', 'Lima kali rangkaian benang lurus digunakan untuk membentuk garis dasar atau bingkai dari motif ulos. Ini memberikan struktur yang stabil sebelum pola utama dikerjakan.', '42%', '67%', '2025-05-15 16:38:11'),
(130, 'P0012', 61, 'SB5', 'Lima kali simpul benang silang digunakan untuk membuat dasar struktur pola utama ulos. Ini berfungsi untuk menjaga agar benang tetap terikat erat dan membentuk dasar yang kokoh sebelum masuk ke pola berikutnya.', '36%', '76%', '2025-05-15 16:43:32'),
(131, 'P0012', 61, 'US4', 'empat kali lipatan ujung benang berfungsi untuk memperpanjang bagian tertentu pada motif. Ini akan menjadi area fokus pada pola bintang atau garis panjang.\r\n\r\n', '54%', '76%', '2025-05-15 16:45:34'),
(132, 'P0012', 61, 'SU2', ' Dua simpul ujung benang digunakan untuk menutup pola agar tidak mudah longgar dan menjaga pola tetap simetris.', '39%', '22%', '2025-05-15 16:46:13'),
(133, 'P0012', 61, 'B5', 'Lima rangkaian benang lurus digunakan untuk membentuk garis dasar sebagai pembatas antar pola. Ini akan menjadi dasar sebelum pola utama bintang maratur terbentuk.', '44%', '76%', '2025-05-15 16:46:41'),
(134, 'P0012', 61, 'U5 ', 'Lima kali lipatan ujung benang digunakan untuk membentuk area tertentu yang akan dijadikan titik fokus pada pola bintang maratur. Ini biasanya menjadi bagian yang lebih tebal pada motif.', '17%', '56%', '2025-05-15 16:47:06'),
(135, 'P0012', 61, 'SU4', 'Empat kali simpul ujung benang digunakan untuk mengunci pola setelah selesai dibuat. Ini adalah langkah akhir untuk memastikan motif tidak terlepas saat proses penganyaman.', '57%', '54%', '2025-05-15 16:47:47'),
(136, 'P0011', 62, 'B', 'Digunakan sebagai dasar tenunan. Biasanya berwarna hitam/coklat gelap.', '86%', '32%', '2025-05-15 16:59:28'),
(137, 'P0011', 62, 'B', 'Digunakan sebagai aksen atau hiasan corak. Bisa berwarna kontras.', '95%', '22%', '2025-05-15 16:59:55'),
(138, 'P0011', 62, 'U', 'Benang motif utama, biasanya benang berwarna khas (merah, emas, putih).', '82%', '33%', '2025-05-15 17:00:33'),
(139, 'P0011', 62, 'SB', 'Perpaduan yang membentuk motif transisi atau sambungan.', '55%', '60%', '2025-05-15 17:01:04'),
(140, 'P0011', 62, 'BSU', 'Biasanya membentuk titik motif pusat.', '72%', '51%', '2025-05-15 17:01:34'),
(141, 'P0011', 62, 'U², SB², U³', 'Artinya bagian tersebut ditenun dua kali atau tiga kali untuk penebalan atau penegasan pola.', '70%', '81%', '2025-05-15 17:02:07'),
(142, 'P0009', 63, 'B', 'Merupakan komponen utama dalam proses penyusunan lungsi (warp) di alat tenun. Benang dasar disiapkan lebih dulu dan menentukan panjang ulos. Benang ini harus kuat karena menjadi kerangka tenunan, menahan seluruh struktur saat ditenun.', '17%', '20%', '2025-05-15 17:10:03'),
(143, 'P0009', 63, 'S (Sisipan)', 'Digunakan untuk membuat garis bantu atau batas antara motif. Sisipan disisipkan pada saat proses menenun sudah berjalan beberapa baris. Juga digunakan sebagai penanda bagian tengah, pinggir, atau pergantian pola, sehingga penenun tahu kapan harus mengganti warna atau teknik.', '21%', '28%', '2025-05-15 17:10:42'),
(144, 'P0009', 63, 'U (Motif Utama)', 'Elemen ini ditenun saat pola utama dimulai, biasanya memerlukan keterampilan lebih tinggi karena melibatkan pola hias. Penenun harus mengatur posisi benang motif (biasanya dengan teknik tambahan seperti songketan atau turitan). Motif ini menentukan keindahan visual ulos, jadi pengerjaannya lebih lambat dan presisi.', '43%', '44%', '2025-05-15 17:11:19'),
(145, 'P0009', 63, 'BS (Benang Dasar + Sisipan)', 'Merupakan transisi dari bagian kosong ke bagian bermotif, digunakan untuk menyusun bagian awal dan akhir dari blok tenunan motif. Memudahkan penenun untuk menjaga konsistensi ketegangan benang saat berpindah dari benang polos ke bagian bermotif.', '87%', '45%', '2025-05-15 17:11:48'),
(146, 'P0009', 63, 'SB (Sisipan + Dasar)', 'Digunakan untuk menandai batas samping dari pola utama. Ini berfungsi sebagai pengatur lebar pola agar ulos tidak bergeser arah selama penenunan. Juga berfungsi sebagai pengingat bagi penenun tentang panjang pengulangan motif.', '76%', '77%', '2025-05-15 17:12:25'),
(147, 'P0009', 63, 'BSU (Gabungan Benang Dasar, Sisipan, dan Motif)', 'Titik paling rumit dalam tenunan. Pada proses pembuatannya, ini adalah bagian puncak dari siklus pola, dan memerlukan penggabungan 3 jenis benang sekaligus (dasar, sisipan, dan motif). Proses ini membutuhkan fokus tinggi, biasanya ditenun perlahan dan teliti agar motif tidak salah.', '65%', '53%', '2025-05-15 17:12:52'),
(148, 'P0009', 63, 'U² (Motif Ganda)', 'Ini adalah pengulangan motif utama dalam dua atau lebih baris berturut-turut. Dalam praktiknya, bagian ini ditenun dengan penebalan atau penguatan benang motif, kadang dengan tambahan benang dobel. Tujuannya untuk menciptakan bagian pola yang lebih tebal dan dominan. Waktu pengerjaan bagian ini lebih lama karena jumlah simpul dan sisipan benang lebih banyak.', '43%', '76%', '2025-05-15 17:13:17'),
(149, 'P0008', 64, 'B (Benang Dasar)', 'Disiapkan sebagai lungsi di alat tenun, sebagai fondasi struktur ulos.', '18%', '12%', '2025-05-15 17:17:56'),
(150, 'P0008', 64, 'S (Sisipan)', 'Sebagai pembatas antar bagian motif. Juga mempermudah penenun mengetahui kapan motif berganti.', '45%', '24%', '2025-05-15 17:18:38'),
(151, 'P0008', 64, 'U (Motif Utama)', 'Motif \"bolang\" (kotak-kotak kecil) ditenun di bagian ini dengan teknik khusus, umumnya teknik tambahan seperti turitan.', '52%', '12%', '2025-05-15 17:19:01'),
(152, 'P0008', 64, 'BSU²', 'Menandai awal blok motif. Penenun memulai penempatan motif dengan 2 baris motif di antara benang dasar dan sisipan.', '25%', '13%', '2025-05-15 17:19:24'),
(153, 'P0008', 64, 'BSU³', 'Menguatkan motif dengan menambah satu baris lagi pada pola sebelumnya. Digunakan untuk membuat bagian tengah motif agar terlihat padat.', '25%', '56%', '2025-05-15 17:19:58'),
(154, 'P0008', 64, 'UB', 'Digunakan untuk menyisipkan benang motif dalam pola kotak bolang. UB terdiri dari U (motif) yang berada dalam B (dasar). Proses ini dikerjakan dengan hati-hati karena tiap kotak memiliki warna berbeda (biasanya warna gelap dan terang kontras).', '55%', '66%', '2025-05-15 17:20:28'),
(155, 'P0008', 64, 'USBS', 'Penutup dari satu blok motif. Penenun mengunci motif dengan sisipan dan benang dasar kembali untuk menjaga stabilitas tenunan dan melanjutkan ke pengulangan berikutnya.', '82%', '75%', '2025-05-15 17:20:58'),
(156, 'P0007', 65, 'B', 'Benang dasar warna hitam (dasar ulos)', '19%', '32%', '2025-05-15 17:31:44'),
(157, 'P0007', 65, 'SB', 'Sipingkan Benang (biasanya benang merah atau putih disisipkan di antara benang hitam)', '67%', '11%', '2025-05-15 17:32:12'),
(158, 'P0007', 65, 'SB⁴ ', 'Sipingkan Benang diulang 4 kali (sebagai motif utama)', '29%', '42%', '2025-05-15 17:32:45'),
(159, 'P0007', 65, 'RS', 'Ragih Sitolu (motif penutup bagian sisi)', '79%', '53%', '2025-05-15 17:33:14'),
(160, 'P0007', 65, 'BSB / SSB', ' Gabungan warna dan susunan benang ganda (misalnya hitam-merah atau putih-merah)', '40%', '72%', '2025-05-15 17:33:51'),
(161, 'P0007', 65, 'SSI ', 'Sipingkan Sisi Istimewa (bagian tengah ulos, biasanya digunakan pada bagian punggung atau tengah)', '72%', '72%', '2025-05-15 17:34:30'),
(162, 'P0007', 65, 'GG', 'Gabungan garis (batas akhir pada ujung ulos)', '71%', '82%', '2025-05-15 17:34:55'),
(163, 'P0013', 67, 'BS', 'Dipakai sebagai dasar pinggiran ulos untuk memastikan kain tidak mudah melar.', '68%', '56%', '2025-05-24 06:09:20'),
(164, 'P0013', 67, 'US', 'Dipasang di ujung kain untuk mencegah benang terlepas (mengunci anyaman).', '75%', '33%', '2025-05-24 06:10:02'),
(165, 'P0013', 67, 'SB', 'Dipakai di bagian tengah untuk menghubungkan motif dan menambah kekuatan tenunan.', '27%', '58%', '2025-05-24 06:10:53'),
(166, 'P0013', 67, 'SU', 'Dipakai sebagai penanda arah kain (misal: sisi atas/bawah) saat ulos dipakai.', '14%', '81%', '2025-05-24 06:11:30'),
(167, 'P0013', 67, 'Angka (Contoh: BS4, SU2)', 'Menentukan jumlah benang yang dipakai dalam satu deret (BS4 = 4 benang Biru-Sihol).\r\n\r\n', '11%', '6%', '2025-05-24 06:12:13'),
(168, 'P0013', 67, 'SUS', 'Ditenun di tengah ulos sebagai titik pusat untuk memudahkan melipat atau mengenakan.', '72%', '83%', '2025-05-24 06:12:48'),
(169, 'P0013', 67, 'BSB', 'Dipakai di area yang sering ditarik (misal: bagian bahu) agar kain tidak mudah rusak.', '76%', '58%', '2025-05-24 06:13:26'),
(170, 'P0013', 67, 'S', 'Dipakai di dekat tali ulos untuk membantu mengencangkan ikatan.', '61%', '50%', '2025-05-24 06:13:58'),
(171, 'P0013', 67, 'USU', 'Dipakai di akhir tenunan untuk mengakhiri anyaman dengan rapi.\r\n\r\n', '64%', '73%', '2025-05-24 06:14:27'),
(172, 'P0014', 69, 'BM', 'Membentuk garis vertikal utama yang menjadi ciri khas Mangiring\r\nDipasang setiap 10 cm sebagai anchor point untuk memandu penenunan', '56%', '57%', '2025-05-24 08:30:44'),
(173, 'P0014', 69, 'UM', 'Dijalin dengan teknik \"skip stitch\" setiap 5 cm', '17%', '8%', '2025-05-24 08:31:27'),
(174, 'P0014', 69, 'SM', 'Stabilizer struktur kain bagian samping\r\nPenanda area \"no-sewing\" untuk jahitan pinggir', '17%', '65%', '2025-05-24 08:31:51'),
(175, 'P0014', 69, ' UMS', 'Titik referensi utama saat pemotongan kain\r\nArea khusus untuk label/sertifikasi autentikasi', '73%', '78%', '2025-05-24 08:32:18'),
(176, 'P0014', 69, 'BMB', 'Reinforcement pada area stress point (bahu/pinggang)\r\nBase untuk attachment aksesoris (pin logam, dll)', '86%', '56%', '2025-05-24 08:32:50'),
(177, 'P0014', 69, 'S', 'Anchor point untuk mesin overlock finishing\r\nPosisi awal/akhir dalam proses quality control', '54%', '50%', '2025-05-24 08:33:07'),
(178, 'P0014', 69, 'Angka dalam Pola (BM4, UM10, dll)', 'Kode produksi untuk sistem inventory digital\r\nPanduan setup mesin ATBM otomatis', '9%', '7%', '2025-05-24 08:33:51'),
(179, 'P0015', 71, 'BS', 'digunakan untuk menurunkan benang lungsi ke bawah agar shuttle bisa lewat dari sisi bawah tenunan.', '65%', '41%', '2025-05-24 09:56:03'),
(180, 'P0015', 71, 'BS', 'digunakan untuk menurunkan benang lungsi ke bawah agar shuttle bisa lewat dari sisi bawah tenunan.', '65%', '41%', '2025-05-24 09:56:29'),
(181, 'P0015', 71, 'US', 'digunakan untuk mengangkat benang lungsi ke atas dan menciptakan ruang bersama BS untuk jalur shuttle.', '62%', '57%', '2025-05-24 09:57:07'),
(182, 'P0015', 71, 'SU', 'digunakan untuk menyusun benang naik dan turun dalam pola tertentu agar terbentuk motif utama pada kain.', '18%', '60%', '2025-05-24 09:57:33'),
(183, 'P0015', 71, 'SB', 'digunakan untuk menyambung atau menyisip pola tenunan agar transisi antar bagian tetap rapi.', '31%', '86%', '2025-05-24 09:58:16'),
(184, 'P0015', 71, 'S', 'digunakan sebagai sisipan atau pengisi kecil agar pola tidak terputus dan jalur tenun tetap seimbang.', '55%', '49%', '2025-05-24 09:58:43'),
(185, 'P0015', 71, 'SUS / USU / BSB', 'digunakan sebagai kombinasi gerakan naik-turun cepat yang berfungsi mengunci atau mengakhiri motif dengan kokoh.', '74%', '32%', '2025-05-24 09:59:09'),
(186, 'P0016', 73, 'TM ', ' Saat simbol \"TM\" muncul, penenun mengganti shuttle/pakan dengan benang bermotif. Biasanya dijalankan dengan gerakan lambat dan hati-hati agar motif terbentuk jelas dan seimbang.', '65%', '73%', '2025-05-24 10:40:02'),
(187, 'P0016', 73, 'UT', 'Benang pakan dijalankan dengan shuttle biasa, dari kiri ke kanan dan sebaliknya, tanpa perubahan dalam ketegangan atau jenis benang.\r\n\r\n', '49%', '5%', '2025-05-24 10:40:22'),
(188, 'P0016', 73, 'ST ', 'Menggunakan shuttle berisi benang berbeda (misal lebih kasar, atau glossy), dan bisa dijalankan selang-seling di antara baris UT dan TM.', '68%', '32%', '2025-05-24 10:40:44'),
(189, 'P0016', 73, 'UTT', 'Menggunakan benang pakan yang lebih tebal atau digandakan dua helai, ditenun dengan tekanan lebih pada beater agar hasilnya padat dan kuat.\r\n\r\n', '77%', '34%', '2025-05-24 10:41:06'),
(190, 'P0016', 73, 'S', 'Penenun berhenti menenun pada baris itu atau menaikkan semua benang lusi tanpa pakan masuk, sehingga terbentuk celah kecil atau celah lubang sebagai pemisah motif.', '55%', '46%', '2025-05-24 10:41:43');
